window.CFA_QUANT_BRIDGE=[{"module_id":"CFA26-01-01","module_title":"Rates and Returns","los":[{"id":"CFA26-01-01-LOS01","letter":"a","title_en":"Interest Rates and Required Returns","outcome_en":"Rates and Returns: Giải thích lãi suất và các phần bù rủi ro","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Mục tiêu học tập — LOS 1.a","body":"","html":"<p class=\"lead\">Một mức lãi suất có thể được hiểu là <b>lợi suất nhà đầu tư yêu cầu</b>, <b>suất chiết khấu</b> hoặc <b>chi phí cơ hội</b>. Mức lãi suất quan sát trên thị trường còn phản ánh giá trị thời gian của tiền và các khoản bù đắp rủi ro. Bài này chỉ xử lý <strong>LOS 1.a</strong> của Module 1 — không tự đánh dấu 4 LOS khác của Rates and Returns là đã kiểm định.</p><div class=\"badgeline\"><span class=\"tag\">1 LOS</span><span class=\"tag\">20 ý kiến thức được đối chiếu</span><span class=\"tag\">5 ví dụ mới</span><span class=\"tag\">12 câu hỏi mới</span><span class=\"tag muted\">Không phải 5/5 LOS của module</span></div>","trap":""},{"heading":"1. Khái niệm và ý nghĩa","body":"","html":"<p>Nhà đầu tư thường ưu tiên nhận tiền sớm vì có thể sử dụng hoặc đầu tư số tiền đó ngay. Vì vậy, hai khoản tiền có ngày nhận khác nhau chỉ có thể so sánh sau khi quy đổi về cùng thời điểm. <strong>Interest rate (r)</strong> biểu thị tỷ lệ làm cho giá trị hai dòng tiền ở các thời điểm khác nhau trở nên tương đương theo một giả định định giá nhất định.</p><p>Trong ví dụ một kỳ, nếu <span class=\"math\">PV</span> là số tiền hiện tại và <span class=\"math\">FV</span> là số tiền ở cuối kỳ, thì <span class=\"math\">r = FV/PV − 1</span>. Phương trình này giúp minh họa quan hệ giá trị thời gian; trường hợp nhiều kỳ và tần suất ghép lãi thuộc module Time Value of Money.</p>","trap":""},{"heading":"2. Ba cách nhìn lãi suất","body":"","html":"<div class=\"cards3\"><article><h4>Required rate of return</h4><p>Ngưỡng lợi suất <strong>tối thiểu</strong> nhà đầu tư đòi hỏi để chấp nhận một khoản đầu tư với mức độ rủi ro, kỳ hạn và đồng tiền cụ thể. Đây là tiêu chuẩn chấp nhận, không phải lợi nhuận chắc chắn đạt được.</p></article><article><h4>Discount rate</h4><p>Tỷ lệ dùng để quy đổi dòng tiền trong tương lai về giá trị hiện tại. Cần phù hợp với đồng tiền, thời điểm và rủi ro của dòng tiền được định giá.</p></article><article><h4>Opportunity cost</h4><p>Lợi ích từ <strong>phương án thay thế tốt nhất bị bỏ qua</strong> khi sử dụng nguồn lực vào mục đích khác; ví dụ tiêu dùng hôm nay thay vì đầu tư hoặc chọn một tài sản thay vì tài sản khác.</p></article></div><p>Đây là ba <em>cách diễn giải</em> của một mức lãi suất theo từng câu hỏi. Không nên nói mọi tài sản đều dùng cùng một con số, vì dòng tiền có thể khác rủi ro, đồng tiền và kỳ hạn.</p>","trap":""},{"heading":"3. Lãi suất hình thành như thế nào","body":"","html":"<p>Trong mô hình cung – cầu vốn, nhà đầu tư cung ứng vốn và người đi vay có nhu cầu sử dụng vốn. Lãi suất thị trường cân bằng giữa lợi ích trì hoãn tiêu dùng của nhà đầu tư và chi phí sử dụng vốn của người đi vay. Khi nhìn từ phía người đầu tư, lãi suất phải bù đắp cả việc chờ đợi và những rủi ro riêng của dòng tiền.</p>","trap":""},{"heading":"4. Năm thành phần của lãi suất","body":"","html":"<div class=\"formula-big\">r ≈ r<sub>real,RF</sub> + IP + DRP + LP + MP</div><p>Mô hình phân rã <strong>cộng</strong> được trình bày trong Curriculum để nêu trực giác kinh tế. Các phần bù phải được xem trong bối cảnh cùng thời hạn, đồng tiền và các giả định so sánh.</p><table><thead><tr><th>Thành phần</th><th>Bản chất / nguồn bù đắp</th><th>Nhận diện trong đề</th></tr></thead><tbody><tr><td>Real risk-free</td><td>Suất phi rủi ro thực mang tính lý thuyết của một kỳ, không có kỳ vọng lạm phát và không có khả năng vỡ nợ; phản ánh <em>time preference</em>.</td><td>“No expected inflation”, “completely risk-free”, “time preference”.</td></tr><tr><td>Inflation premium (IP)</td><td>Bù đắp sức mua bị hao mòn do <strong>lạm phát kỳ vọng</strong> bình quân trong vòng đời khoản nợ.</td><td>“Expected inflation”; khác lạm phát đã thực hiện.</td></tr><tr><td>Default risk premium (DRP)</td><td>Bù đắp khả năng người vay không thanh toán đúng số tiền hoặc đúng hạn.</td><td>“Probability of missed promised payments”, “credit quality”.</td></tr><tr><td>Liquidity premium (LP)</td><td>Bù đắp nguy cơ phải bán gấp dưới giá trị hợp lý hoặc gánh chi phí giao dịch đáng kể.</td><td>“Hard to sell quickly”, “thin trading”, “price impact”.</td></tr><tr><td>Maturity premium (MP)</td><td>Bù đắp độ nhạy của giá trị nợ với thay đổi lãi suất thị trường khi thời hạn dài hơn, trong điều kiện các yếu tố khác giữ nguyên.</td><td>“Longer maturity” và “interest-rate sensitivity”.</td></tr></tbody></table><p><strong>Phân biệt trọng tâm:</strong> default liên quan <em>không trả được nợ</em>; liquidity liên quan <em>cần bán nhanh</em>; maturity liên quan <em>kỳ hạn và độ nhạy giá</em>. Một khoản chênh lệch yield có thể chứa <em>nhiều</em> premium.</p>","trap":""},{"heading":"5. Nominal so với real risk-free","body":"","html":"<p>Nominal risk-free rate phản ánh cả thời gian chờ và lạm phát kỳ vọng. Theo quan hệ Fisher:</p><div class=\"formula-big\">(1 + r<sub>nominal,RF</sub>) = (1 + r<sub>real,RF</sub>)(1 + IP)</div><p>Khi các tỷ lệ tương đối nhỏ, sử dụng gần đúng: <span class=\"math\">r<sub>nominal,RF</sub> ≈ r<sub>real,RF</sub> + IP</span>. Phép gần đúng có sai lệch bằng tích chéo giữa hai tỷ lệ. <strong>Không</strong> mặc nhiên nhân tất cả DRP/LP/MP theo cách Fisher nếu tài liệu không đặt mô hình đó.</p><p>Ở một đồng tiền và kỳ hạn tương ứng, công cụ nợ chính phủ ngắn hạn có độ tin cậy rất cao (như T-bills trong ví dụ CFA) thường được dùng làm <em>đại diện</em> cho nominal risk-free rate. Đây <strong>không phải</strong> real risk-free rate vì kỳ vọng lạm phát vẫn tồn tại. T-bill 90 ngày thường niêm yết yield ở dạng <strong>annualized</strong>; không được coi con số niêm yết là lợi suất thực nhận trong 90 ngày nếu chưa biết quy ước báo giá.</p>","trap":""},{"heading":"6. Quy tắc so sánh trái phiếu","body":"","html":"<p>Muốn suy chênh lệch lãi suất do một phần bù cụ thể, hãy tìm hai công cụ <strong>giống nhau ở mọi yếu tố khác</strong>. Nếu khác cả kỳ hạn và khả năng trả nợ, không thể gán toàn bộ spread cho maturity hoặc default. Nếu biết LP từ một cặp đối chứng khác, ta có thể điều chỉnh spread của cặp tiếp theo để suy DRP.</p><p><strong>Cận lãi suất:</strong> khi premium cho kỳ hạn được giả định tăng theo maturity và các premium khác ổn định, có thể đặt lower/upper bounds cho trái phiếu có kỳ hạn xen giữa. Đây là kết luận <em>có điều kiện</em>, không phải định luật rằng trái phiếu dài hạn luôn có yield cao hơn trong mọi thị trường.</p><p>Real risk-free, lạm phát kỳ vọng và các premium biến đổi theo nền kinh tế và dự báo tương lai, nên suất yêu cầu có thể thay đổi dù hợp đồng vay không đổi.</p>","trap":""},{"heading":"7. Quy tắc áp dụng và lỗi phổ biến","body":"","html":"<ol class=\"spaced\"><li>Đọc câu hỏi trước: đang yêu cầu <b>định nghĩa một tỷ lệ</b> hay <b>suy một premium từ spread</b>?</li><li>Kiểm tra các cặp so sánh có cùng kỳ hạn, rủi ro vỡ nợ, thanh khoản và đồng tiền hay không.</li><li>Không nhầm <b>inflation premium kỳ vọng</b> với lạm phát lịch sử hoặc đã hiện thực hóa.</li><li>Không coi T-bill nominal risk-free là một real risk-free instrument.</li><li>Để tính mức lãi trong một kỳ ngắn hơn một năm, trước hết phải xem annualized quotation, day-count và cách tính yield.</li><li>Ghi rõ <b>điểm phần trăm</b> khi trừ hai mức lợi suất (ví dụ 4,1% – 3,4% = 0,7 điểm phần trăm), không dùng “% thay đổi tương đối”.</li><li>Suất yêu cầu là tiêu chuẩn định giá, <b>không bảo đảm</b> khoản đầu tư thực tế sinh lời đúng bằng suất đó.</li></ol>","trap":""}],"formulas":[{"name":"4. Năm thành phần của lãi suất","expr":"r ≈ r real,RF + IP + DRP + LP + MP","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. Nominal so với real risk-free","expr":"(1 + r nominal,RF ) = (1 + r real,RF )(1 + IP)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"Lãi suất dưới ba góc nhìn","steps_vi":[],"answer":"","html":"<div class=\"top\">Lãi suất dưới ba góc nhìn</div><div class=\"body\"><p><strong>Đề:</strong> Một nhà đầu tư có 25.000 USD hôm nay; một khoản đầu tư có mức chi trả chắc chắn 26.500 USD sau 1 năm và được xem là tương đương về giá trị theo yêu cầu của nhà đầu tư.</p><ol><li>Chênh lệch là 26.500 − 25.000 = 1.500 USD.</li><li>Lãi suất cân bằng: r = 1.500 / 25.000 = 0,06 = 6%.</li><li>Required return: nếu cùng rủi ro, nhà đầu tư cần tối thiểu 6% để chấp nhận.</li><li>Discount rate: 26.500 / 1,06 = 25.000 USD.</li><li>Opportunity cost: dùng 25.000 USD ngay hôm nay sẽ bỏ lỡ khoản lợi tức 1.500 USD từ phương án thay thế này.</li></ol><p class=\"answer\">Kết luận: 6%/năm là một tỷ lệ có ba cách diễn giải khác nhau trong bối cảnh này.</p><small>Tự biên soạn, kiểm tra logic với CFAI 2026 tr.13</small></div>"},{"question_en":"Phân rã suất sinh lời yêu cầu","steps_vi":[],"answer":"","html":"<div class=\"top\">Phân rã suất sinh lời yêu cầu</div><div class=\"body\"><p><strong>Đề:</strong> Giả định cùng kỳ hạn, real risk-free 1,4%; lạm phát kỳ vọng 2,1%; default 1,3%; liquidity 0,5%; maturity 0,7%.</p><ol><li>Cộng theo mô hình phân rã gần đúng: 1,4 + 2,1 + 1,3 + 0,5 + 0,7.</li><li>Kết quả 6,0% là required nominal rate xấp xỉ, không bảo đảm khoản đầu tư sẽ thực sự sinh lời 6%.</li><li>Nominal risk-free xấp xỉ 1,4 + 2,1 = 3,5%; ba premium còn lại bù cho default, thanh khoản và kỳ hạn.</li></ol><p class=\"answer\">Kết luận: r ≈ 6,0%/năm.</p><small>Tự biên soạn, theo mô hình cộng của CFAI 2026 tr.14</small></div>"},{"question_en":"Fisher exact khác phép cộng xấp xỉ","steps_vi":[],"answer":"","html":"<div class=\"top\">Fisher exact khác phép cộng xấp xỉ</div><div class=\"body\"><p><strong>Đề:</strong> Real risk-free là 2% và inflation premium kỳ vọng 3%, không xét các premium khác.</p><ol><li>Fisher: (1+0,02)(1+0,03)−1 = 0,0506 = 5,06%.</li><li>Gần đúng cộng: 2%+3%=5,00%.</li><li>Khoảng chênh 0,06 điểm phần trăm là tích tương tác 0,02×0,03. Không suy ra tổng required rate có đủ default/liquidity/maturity bằng cách áp dụng Fisher cho tất cả premium nếu đề bài không cho mô hình.</li></ol><p class=\"answer\">Kết luận: Exact 5,06%; approximate 5,00%.</p><small>Tự biên soạn, công thức CFAI 2026 tr.14 và Kaplan tr.14</small></div>"},{"question_en":"Cô lập liquidity, default và chặn trên/dưới lãi suất","steps_vi":[],"answer":"","html":"<div class=\"top\">Cô lập liquidity, default và chặn trên/dưới lãi suất</div><div class=\"body\"><p><strong>Đề:</strong> Có bốn trái phiếu: A (2 năm, thanh khoản cao, default thấp) 2,8%; B (2 năm, thanh khoản thấp, default thấp) 3,4%; C (8 năm, thanh khoản cao, default thấp) 4,1%; D (8 năm, thanh khoản thấp, default cao) 6,4%. Tính liquidity premium, default premium và khoảng hợp lý cho E (6 năm, thanh khoản thấp, default thấp). Giả định các premium thanh khoản/default/lạm phát không đổi theo kỳ hạn, maturity premium tăng theo kỳ hạn.</p><ol><li>A và B chỉ khác thanh khoản: LP = 3,4 − 2,8 = 0,6 điểm phần trăm.</li><li>C và D khác đồng thời default và liquidity: tổng spread = 6,4 − 4,1 = 2,3 điểm phần trăm.</li><li>Loại ảnh hưởng LP: default premium = 2,3 − 0,6 = 1,7 điểm phần trăm.</li><li>E có cùng liquidity/default như B nhưng kỳ hạn dài hơn: r_E &gt; 3,4%.</li><li>So với C kỳ hạn 8 năm, thêm LP để tạo đối chứng thanh khoản thấp: 4,1% + 0,6% = 4,7%; E có kỳ hạn ngắn hơn nên r_E &lt; 4,7%.</li></ol><p class=\"answer\">Kết luận: LP = 0,6 điểm %; DRP = 1,7 điểm %; 3,4% &lt; r_E &lt; 4,7% theo giả định.</p><small>Tình huống mới tự biên soạn theo logic Exhibit 1 CFAI 2026 tr.15–16</small></div>"},{"question_en":"Đọc đúng lãi suất T-bill kỳ hạn 90 ngày","steps_vi":[],"answer":"","html":"<div class=\"top\">Đọc đúng lãi suất T-bill kỳ hạn 90 ngày</div><div class=\"body\"><p><strong>Đề:</strong> Một T-bill kỳ hạn 90 ngày được niêm yết lãi suất 4%/năm. Một người nói: “Mua T-bill này sẽ thu về 4% chỉ trong 90 ngày”.</p><ol><li>Lãi suất 4% được niêm yết trên cơ sở năm, không phải lãi suất nắm giữ 90 ngày.</li><li>Muốn tính lợi suất thực tế 90 ngày cần biết day-count basis, cách báo giá (discount/add-on) và giá mua/thanh toán.</li><li>Nếu đề tự quy định lãi suất đơn 4% và quy ước 360 ngày, ví dụ minh họa 90 ngày sẽ tương ứng khoảng 4%×90/360 = 1%; không được suy 1% nếu không có quy ước.</li></ol><p class=\"answer\">Kết luận: Phát biểu “thu 4% trong 90 ngày” là sai; cần xem quy ước báo giá.</p><small>Tự biên soạn, dựa trên lưu ý CFAI 2026 tr.15</small></div>"}],"questions":[{"stem_en":"An analyst specifies the minimum return required to accept an investment's risk. Which role does this interest rate represent?","options":["Required rate of return","Opportunity cost of another specific choice","Historical inflation rate"],"correct":0,"why_vi":"Required return là mức lợi suất tối thiểu được đòi hỏi; opportunity cost cần nêu rõ phương án thay thế. Lạm phát lịch sử không tự xác lập mức tối thiểu.","trap_vi":""},{"stem_en":"An investor discounts USD 10,600 due in one year to USD 10,000 today using 6%. In this calculation, 6% is the:","options":["Default risk premium","Discount rate","Trading fee"],"correct":1,"why_vi":"Discount rate đưa dòng tiền ở tương lai về hiện tại. Default premium chỉ là một cấu phần có thể có trong lãi suất; trading fee là chi phí giao dịch.","trap_vi":""},{"stem_en":"An investor buys Bond X instead of a comparably risky Bond Y offering a 7% return. The forgone 7% is most closely associated with:","options":["Sunk cost","Liquidity premium","Opportunity cost"],"correct":2,"why_vi":"Giá trị của cơ hội tốt nhất bị từ bỏ là opportunity cost; sunk cost đã phát sinh và không thể thu hồi, liquidity premium là phần bù mất thanh khoản.","trap_vi":""},{"stem_en":"Under the additive approximation, which components make up the nominal risk-free interest rate?","options":["Real risk-free rate plus expected inflation premium","Real risk-free rate plus default premium","Real risk-free rate plus liquidity premium"],"correct":0,"why_vi":"Nominal risk-free = real risk-free + inflation premium (gần đúng). Default/liquidity premium là phần bù rủi ro không thuộc suất phi rủi ro.","trap_vi":""},{"stem_en":"If the real risk-free rate is 2% and expected inflation is 3%, what is the exact nominal risk-free rate using the Fisher relationship?","options":["5.00%","5.06%","6.00%"],"correct":1,"why_vi":"(1,02×1,03)-1 = 5,06%. 5,00% chỉ gần đúng cộng; 6,00% không xuất phát từ dữ kiện.","trap_vi":""},{"stem_en":"Two bonds are identical except that Bond P is harder to sell promptly at a fair price. Bond P's higher required yield is best explained by:","options":["Maturity premium","Default risk premium","Liquidity premium"],"correct":2,"why_vi":"Chỉ thanh khoản thay đổi nên spread phản ánh liquidity premium. Maturity và default được giữ không đổi.","trap_vi":""},{"stem_en":"Two eight-year bonds differ in credit quality and liquidity. The more liquid, safer bond yields 4.1%; the other yields 6.4%. If the incremental liquidity premium is 0.6 percentage points, the incremental default risk premium is:","options":["1.7 percentage points","2.3 percentage points","0.6 percentage points"],"correct":0,"why_vi":"Chênh lệch 6,4−4,1 = 2,3 điểm % chứa cả LP và DRP. DRP=2,3−0,6=1,7 điểm %. Không đồng nhất toàn spread với default.","trap_vi":""},{"stem_en":"A 90-day government bill is quoted at an annualized yield of 3%. Which conclusion is justified without more information?","options":["The investor earns 3% over 90 days","The quoted yield is expressed on an annual basis","The nominal risk-free rate equals the real risk-free rate"],"correct":1,"why_vi":"CFA lưu ý kỳ hạn 90 ngày vẫn thường được quote theo năm. Lãi kỳ 90 ngày cần day-count và cách báo giá; nominal rate có inflation premium.","trap_vi":""},{"stem_en":"In the CFA interest-rate decomposition, the maturity premium primarily compensates investors for:","options":["Interest-rate exposure of longer-maturity debt","Failure of an issuer to pay as promised","The cost of selling an illiquid bond quickly"],"correct":0,"why_vi":"Thời hạn dài hơn nhìn chung làm độ nhạy giá đối với lãi suất cao hơn. Hai phương án khác lần lượt là default và liquidity risk.","trap_vi":""},{"stem_en":"Two bond yields differ in both maturity and liquidity. Which conclusion is most appropriate?","options":["Attribute the entire spread to maturity","Attribute the entire spread to liquidity","A single premium cannot be isolated without additional controls or assumptions"],"correct":2,"why_vi":"Để suy một premium từ yield spread, cần giữ các yếu tố khác không đổi hoặc có thông tin bổ sung để loại tác động đồng thời.","trap_vi":""},{"stem_en":"Which factors can cause required returns to change over time?","options":["Only the real risk-free rate","Both the real risk-free rate and applicable inflation/risk premiums","Only a bond's face value"],"correct":1,"why_vi":"Curriculum nhấn mạnh real risk-free và các premium có thể đổi theo kỳ vọng kinh tế. Mệnh giá một mình không giải thích sự thay đổi của required yield.","trap_vi":""},{"stem_en":"Which description best matches a theoretical real risk-free rate?","options":["A quoted nominal Treasury bill rate that includes expected inflation","The expected return on a large-cap stock","A one-period risk-free rate with no expected inflation"],"correct":2,"why_vi":"Real risk-free rate là khái niệm lý thuyết gắn với sở thích tiêu dùng hiện tại so với tương lai; T-bill quan sát trên thị trường thường mang tính nominal.","trap_vi":""}],"cards":[{"front_en":"Một lãi suất, ba cách diễn giải?","back_vi":"Required rate of return; discount rate; opportunity cost."},{"front_en":"Tại sao real risk-free chỉ mang tính lý thuyết?","back_vi":"Giả định không có kỳ vọng lạm phát, không vỡ nợ trong một kỳ, phản ánh time preference."},{"front_en":"Lãi suất danh nghĩa phi rủi ro gồm?","back_vi":"Real risk-free + expected inflation premium (cộng xấp xỉ; Fisher nhân là quan hệ chính xác)."},{"front_en":"Rủi ro bán nhanh thấp hơn fair value thuộc premium nào?","back_vi":"Liquidity premium, không phải default premium."},{"front_en":"Yield 90-day T-bill niêm yết 4% nghĩa là gì?","back_vi":"Thường là annualized quote; cần day-count và phương pháp báo giá để tìm HPR 90 ngày."},{"front_en":"Khi nào spread xác định một premium?","back_vi":"Khi các yếu tố khác được giữ cố định, hoặc có thông tin để khử các premium còn lại."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn và phạm vi đối chiếu Bảng dưới ghi trang PDF (đánh số từ 1) của tài liệu bạn đã cung cấp. Website chỉ chứa bản diễn giải và câu hỏi mới, không phát hành lại PDF gốc. CFAI26 — CFA Institute Curriculum 2026 • Quantitative Methods • PDF trang 11, 13–16 KAPLAN26 — Kaplan SchweserNotes 2026 • Book 1 • PDF trang 10, 14–15 SAPP26 — SAPP Quantitative Methods 2026 • PDF trang 5–9 và 30 CFAI24 — CFA Institute Prerequisite 2024 • Quant • PDF trang 11–13, 48, 53 MINDMAP — SAPP Quant Revision Mindmap • PDF trang 1 KQB26 — Kaplan Question Bank 2026 • Reading 1, Questions và Answers BONUSQB — Question Banks Bonus • Rates and Returns, Questions và Answers Giới hạn kiểm định: 20 ý kiến thức thuộc LOS 1.a được rà soát trong Curriculum 2026 và các nguồn bổ trợ được nêu trên. Các bộ Mock cũ chưa được kiểm kê theo từng câu hỏi đối với LOS này, vì vậy chưa thể kết luận đã đối chiếu hết mọi câu hỏi lịch sử trong toàn bộ 534 PDF. Hồ sơ chi tiết ngoài website nằm trong tệp ZIP kiểm định riêng."}],"legacy":"sourcefirst-quant-rates-los01.html"},{"id":"CFA26-01-01-LOS02","letter":"b","title_en":"Holding-Period Returns and Mean Returns","outcome_en":"Rates and Returns: Return Measurement — LOS 1.b","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 1.b","body":"","html":"<p class=\"lead\">Tính, giải thích và so sánh các phương pháp đo lường lợi nhuận theo thời gian; chọn đúng phương pháp trong từng hoàn cảnh.</p><div class=\"badgeline\"><span class=\"tag\">28 ý kiến thức có dấu vết nguồn</span><span class=\"tag\">10 ví dụ mới</span><span class=\"tag\">20 câu tự luyện</span><span class=\"tag muted\">Không phải toàn bộ Module 1</span></div><div class=\"callout\"><strong>Điểm dễ nhầm:</strong> HPR toàn thời gian, arithmetic mean một kỳ, geometric mean của chuỗi cùng kỳ và annualized return là các khái niệm khác nhau. Đọc kỹ đơn vị thời gian và giả định tái đầu tư trước khi chọn công thức.</div>","trap":""},{"heading":"1. HPR: đo lợi nhuận đúng trên một kỳ nắm giữ","body":"","html":"<p><strong>Holding Period Return (HPR)</strong> là lợi nhuận thực hiện từ khi bắt đầu đến khi kết thúc <em>một khoảng nắm giữ xác định</em>. Một kỳ có thể là một tuần, quý, năm hoặc cả ba năm; tên HPR không tự động có nghĩa “lợi nhuận một năm”.</p><div class=\"formula-big\">R = (P₁ − P₀ + I₁) / P₀ = capital return + income yield</div><p><b>P₀</b>: giá/giá trị đầu kỳ; <b>P₁</b>: giá/giá trị cuối kỳ; <b>I₁</b>: cổ tức hoặc coupon nhận trong kỳ. Capital return = (P₁−P₀)/P₀; income yield = I₁/P₀. Hai thành phần có thể trái dấu.</p><p><strong>Giả định quan trọng:</strong> công thức đơn giản thường đặt khoản phân phối vào cuối kỳ. Nếu nhận cổ tức trước kỳ kết thúc và tái đầu tư, kết quả thực tế có thể khác. Nếu có nộp/rút tiền ngoài trong kỳ, phải phân đoạn hoặc dùng phương pháp phù hợp với mục tiêu (LOS 1.c).</p><p><strong>Ví dụ trực giác:</strong> giữ cổ phiếu mua 80, bán 84, nhận dividend 4 → capital 5%; income yield 5%; HPR 10%. Nếu giá giảm còn 76 thì capital −5%, nhưng có dividend 4 =&gt; HPR 0%.</p>","trap":""},{"heading":"2. Lợi nhuận nhiều kỳ: nhân, không cộng","body":"","html":"<p>Giả sử không có tiền bên ngoài đưa vào/rút khỏi danh mục và tái đầu tư thu nhập theo giả định, giá trị tài sản cuối kỳ được tính bằng giá trị đầu nhân với từng <strong>gross return factor</strong>.</p><div class=\"formula-big\">R<sub>total</sub> = ∏<sub>t=1…n</sub>(1 + R<sub>t</sub>) − 1</div><p>Ở đây R<sub>t</sub> là HPR của từng kỳ, tính dạng thập phân. Hai kỳ +20% rồi −20% tạo ra (1,20×0,80)−1 = −4%, không phải 0%. Lỗ 50% cần tăng 100% mới quay về vốn ban đầu.</p><p>Nếu một kỳ thua lỗ −100%, giá trị đầu tư còn 0; CAGR của chuỗi về −100% (không phải phép toán vô nghĩa). Trường hợp return thấp hơn −100% không phù hợp với khoản đầu tư không đòn bẩy vốn góp hữu hạn, nhưng có thể phát sinh kết quả đặc thù với đòn bẩy/nợ vượt vốn; cần xét sản phẩm.</p>","trap":""},{"heading":"3. Arithmetic mean: lợi nhuận trung bình một kỳ","body":"","html":"<div class=\"formula-big\">R<sub>A</sub> = (R₁ + R₂ + … + Rₙ) / n</div><p>Arithmetic mean là trung bình các HPR có cùng độ dài. Hữu ích để mô tả lợi nhuận “một kỳ điển hình”, và trong mô hình thống kê có giả định phù hợp, là ước lượng cho <strong>expected one-period return</strong>. Nó <strong>không phải</strong> tỷ lệ tăng trưởng kép mà tài sản đã thực sự đạt qua n kỳ.</p><p>Ví dụ +100% rồi −50%: arithmetic = (+100%−50%)/2 = +25%; tuy nhiên đầu tư 100 tăng 200 rồi quay lại 100, nên tổng HPR bằng 0%. Nếu dùng 25% để ghép lãi hai năm, bạn sẽ dự báo sai lịch sử tăng trưởng.</p><p>“Unbiased estimator” ở tài liệu Kaplan đặt trong bối cảnh ước lượng trung bình phân phối lợi nhuận một kỳ với giả định thống kê phù hợp; không được hiểu arithmetic mean luôn dự báo chính xác CAGR.</p>","trap":""},{"heading":"4. Geometric mean: tỷ lệ tăng trưởng kép lịch sử","body":"","html":"<div class=\"formula-big\">R<sub>G</sub> = [∏(1+R<sub>t</sub>)]<sup>1/n</sup> − 1 = (1+R<sub>total</sub>)<sup>1/n</sup>−1</div><p>Geometric mean là cùng một suất sinh lời mỗi kỳ mà nếu ghép lãi liên tục theo số kỳ sẽ tạo ra đúng hệ số tăng trưởng tổng đã quan sát. Ví dụ chuỗi +20%, −10% có tổng gross factor 1,08: geometric = √1,08 −1 ≈ 3,923%/kỳ, không phải 5%.</p><p><strong>Hai kiểu “annual” cần phân biệt:</strong> nếu dữ liệu gồm 4 HPR nửa năm thì căn bậc 4 cho geometric <em>nửa năm</em>; muốn tỷ lệ <em>một năm</em>, dùng căn bậc 2 với tổng gross factor của hai năm. Nếu đã có 3 suất lợi nhuận năm, căn bậc 3 là suất bình quân năm.</p><p>Với chuỗi gross factor dương, <b>geometric mean ≤ arithmetic mean</b>; bằng nhau khi lợi nhuận từng kỳ bằng nhau. Biến động lớn khiến chênh lệch thường tăng. Không được nhân mean arithmetic qua n kỳ để đại diện tăng trưởng đã xảy ra.</p>","trap":""},{"heading":"5. Harmonic mean: bình quân tỷ số, P/E và cost averaging","body":"","html":"<div class=\"formula-big\">H = n / (1/X₁ + 1/X₂ + … + 1/Xₙ) ; Xᵢ &gt; 0</div><p>Harmonic mean phù hợp khi biến là <strong>tỷ số, suất, giá trên mỗi đơn vị</strong> dương và mẫu số/khối lượng đóng vai trò quan trọng. Nó cho trọng số theo nghịch đảo quan sát, giảm tác động giá trị quá lớn so với arithmetic mean. Với P/E ba doanh nghiệp [12,18,36], harmonic = 18 lần; arithmetic = 22 lần.</p><p><b>Dollar-cost averaging:</b> nếu bỏ <em>cùng số tiền</em> để mua cổ phiếu ở giá khác nhau, số cổ phiếu nhận được tỉ lệ nghịch với giá. Tổng tiền / tổng cổ phiếu bằng harmonic mean của các mức giá. Nếu mua cùng số cổ phiếu mỗi kỳ, không dùng cách suy luận này.</p><div class=\"formula-big\">H<sub>returns</sub> = n / Σ[1/(1+R<sub>t</sub>)] − 1 ; 1+R<sub>t</sub> &gt; 0</div><p>Để tính <em>harmonic mean return</em>, không lấy nghịch đảo trực tiếp của −10%, +20%,… mà chuyển sang gross factors (0,90; 1,20; …), lấy harmonic rồi trừ 1. <strong>Weighted harmonic:</strong> H<sub>w</sub> = Σw<sub>i</sub> / Σ(w<sub>i</sub>/X<sub>i</sub>), với w không âm và Xi dương; phải hiểu trọng số đại diện cái gì.</p>","trap":""},{"heading":"6. Lưu ý kiểm chứng công thức trong tài liệu gốc","body":"","html":"<p>Ở PDF Curriculum 2026 trang 24 có in đẳng thức <span class=\"math\">Arithmetic × Harmonic = Geometric²</span> như một kết quả tổng quát. <strong>Kiểm tra toán học độc lập cho thấy đẳng thức đó đúng cho hai quan sát dương nhưng không đúng cho n quan sát nói chung.</strong> Ví dụ [1, 2, 4] có A=7/3, H=12/7 và G=2; A×H=4, đúng trong trường hợp này do ba số lập cấp số nhân. Nhưng [1,2,3] có A=2, H≈1,6364, G≈1,8171; A×H≈3,2727 khác G²≈3,3019. Vì vậy, khi học không coi đẳng thức này là công thức chung.</p><p><strong>Điều có thể dùng rộng rãi:</strong> với dữ liệu dương, H ≤ G ≤ A; các mean bằng nhau khi mọi quan sát bằng nhau. Đây là lời giải thích bổ sung về điểm không nhất quán, <em>không</em> âm thầm thay thế nội dung tài liệu.</p>","trap":""},{"heading":"7. Trimmed mean, Winsorized mean và việc xử lý outliers","body":"","html":"<p><strong>Trimmed mean</strong>: bỏ một tỷ lệ xác định các quan sát lớn nhất và nhỏ nhất, sau đó bình quân các quan sát giữ lại. <strong>Winsorized mean</strong>: thay các giá trị cực trị hai phía bằng giá trị gần nhất còn trong khoảng, <em>không giảm số quan sát</em>. Phải nêu rõ số lượng/tỷ lệ cắt hai đầu trước khi tính.</p><p>Ví dụ đã sắp thứ tự [1, 2, 4, 8, 70, 100], loại 1 phần tử ở mỗi đầu: trimmed = (2+4+8+70)/4 = 21. Winsorized thay 1→2 và 100→70: (2+2+4+8+70+70)/6 = 26. Hai cách không tương đương.</p><p>Trim/Winsor giảm tác động outlier lớn và nhỏ; harmonic giải quyết cấu trúc tỷ số dương và cũng giảm tác động outlier lớn, nhưng không phải biện pháp phổ quát cho mọi chuỗi có âm hoặc bằng 0.</p>","trap":""},{"heading":"8. Chọn mean theo mục tiêu và dùng Excel đúng","body":"","html":"<table><thead><tr><th>Mục tiêu</th><th>Thước đo ưu tiên</th><th>Lý do/điều kiện</th></tr></thead><tbody><tr><td>Trung bình lợi nhuận kỳ đơn</td><td>Arithmetic</td><td>Thống kê lợi nhuận một kỳ đồng độ dài</td></tr><tr><td>Tăng trưởng kép lịch sử nhiều kỳ</td><td>Geometric</td><td>Khớp ending wealth do compounding</td></tr><tr><td>Tỷ số P/E hoặc giá bình quân mua bằng số tiền cố định</td><td>Harmonic</td><td>Cấu trúc nghịch đảo giá/tỷ số dương</td></tr><tr><td>Chuỗi có outlier nghiêm trọng</td><td>Trimmed / Winsorized</td><td>Quy tắc xử lý cực trị cần công bố trước</td></tr></tbody></table><p>Curriculum có sơ đồ quyết định (PDF trang 26) nhắc các yếu tố: giữ outliers hay không, có compounding không, có outliers cực đoan không. Đừng chọn geometric chỉ vì dữ liệu “có nhiều năm”; cần xem mục tiêu là kỳ vọng một kỳ hay tăng trưởng tích lũy.</p><p><strong>Excel:</strong> với mảng lợi nhuận thập phân <span class=\"math\">R</span>, arithmetic dùng <code>AVERAGE(R)</code>; geometric dùng <code>GEOMEAN(1+R)-1</code>; harmonic return dùng <code>HARMEAN(1+R)-1</code>. Dữ liệu có gross factor bằng 0 hoặc âm cần xử lý riêng vì GEOMEAN/HARMEAN có thể báo lỗi. Nếu dữ liệu là các tỷ số dương như P/E, dùng <code>HARMEAN(P/E)</code> trực tiếp.</p>","trap":""}],"formulas":[{"name":"1. HPR: đo lợi nhuận đúng trên một kỳ nắm giữ","expr":"R = (P₁ − P₀ + I₁) / P₀ = capital return + income yield","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"2. Lợi nhuận nhiều kỳ: nhân, không cộng","expr":"R total = ∏ t=1…n (1 + R t ) − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Arithmetic mean: lợi nhuận trung bình một kỳ","expr":"R A = (R₁ + R₂ + … + Rₙ) / n","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. Geometric mean: tỷ lệ tăng trưởng kép lịch sử","expr":"R G = [∏(1+R t )] 1/n − 1 = (1+R total ) 1/n −1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. Harmonic mean: bình quân tỷ số, P/E và cost averaging","expr":"H = n / (1/X₁ + 1/X₂ + … + 1/Xₙ) ; Xᵢ > 0","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. Harmonic mean: bình quân tỷ số, P/E và cost averaging","expr":"H returns = n / Σ[1/(1+R t )] − 1 ; 1+R t > 0","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · HPR có hai nguồn lợi nhuận","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · HPR có hai nguồn lợi nhuận</div><div class=\"body\"><p><b>Đề:</b> Mua tài sản giá 125, bán 130 cuối kỳ, nhận coupon 7 cuối kỳ.</p><p><b>Giải từng bước:</b> Capital = (130−125)/125=4%; income yield=7/125=5,6%; HPR=(130−125+7)/125=9,6%.</p><p class=\"answer\">Kết luận: 9,60%</p><small>Liên kết kiến thức: fundamentals</small></div>"},{"question_en":"E02 · Cùng tăng và giảm 20% không hòa vốn","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · Cùng tăng và giảm 20% không hòa vốn</div><div class=\"body\"><p><b>Đề:</b> Một tài khoản tăng 20% năm 1 rồi giảm 20% năm 2, đầu tư 10.000 USD.</p><p><b>Giải từng bước:</b> Cuối năm 1: 10.000×1,20=12.000; cuối năm 2: 12.000×0,80=9.600; HPR 2 năm=1,20×0,80−1=−4%.</p><p class=\"answer\">Kết luận: −4,00% hai năm</p><small>Liên kết kiến thức: multiperiod</small></div>"},{"question_en":"E03 · Arithmetic và geometric trong cùng bộ số","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Arithmetic và geometric trong cùng bộ số</div><div class=\"body\"><p><b>Đề:</b> Hai năm có HPR +20% và −10%.</p><p><b>Giải từng bước:</b> Arithmetic=(0,20−0,10)/2=5,00%; total HPR=1,20×0,90−1=8,00%; geometric=√1,08−1=3,923%.</p><p class=\"answer\">Kết luận: A=5,00%/năm; G≈3,923%/năm (hai kỳ đều một năm)</p><small>Liên kết kiến thức: arithmetic</small></div>"},{"question_en":"E04 · Bẫy tăng 100%, giảm 50%","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Bẫy tăng 100%, giảm 50%</div><div class=\"body\"><p><b>Đề:</b> Năm đầu tăng 100%; năm thứ hai giảm 50%; vốn ban đầu 2.000 USD.</p><p><b>Giải từng bước:</b> Giá trị: 2.000→4.000→2.000; arithmetic=25%; geometric=√[(2,00)(0,50)]−1=0%; HPR toàn kỳ=0%.</p><p class=\"answer\">Kết luận: A=25%; G=0%; tổng HPR=0%.</p><small>Liên kết kiến thức: geometric</small></div>"},{"question_en":"E05 · Phân biệt geometric nửa năm và annual","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Phân biệt geometric nửa năm và annual</div><div class=\"body\"><p><b>Đề:</b> Bốn kỳ nửa năm liên tiếp: +4%, −2%, +6%, +1%.</p><p><b>Giải từng bước:</b> Tổng gross=(1,04)(0,98)(1,06)(1,01). G cho một nửa năm lấy căn bậc 4; G annual lấy căn bậc 2 vì tổng 2 năm.</p><p class=\"answer\">Kết luận: G 6 tháng≈2,205%; annual≈4,458%</p><small>Liên kết kiến thức: geometric</small></div>"},{"question_en":"E06 · Harmonic mean của ba P/E","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Harmonic mean của ba P/E</div><div class=\"body\"><p><b>Đề:</b> Ba doanh nghiệp có P/E lần lượt 12x, 18x, 36x.</p><p><b>Giải từng bước:</b> H=3/(1/12+1/18+1/36)=18x; A=(12+18+36)/3=22x; G=(12×18×36)^(1/3)≈19,813x.</p><p class=\"answer\">Kết luận: H=18x; A=22x; G≈19,813x</p><small>Liên kết kiến thức: harmonic</small></div>"},{"question_en":"E07 · Dollar-cost averaging số tiền bằng nhau","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · Dollar-cost averaging số tiền bằng nhau</div><div class=\"body\"><p><b>Đề:</b> Đầu tư đều 600 USD vào cổ phiếu giá 20, 30, 60 USD/cổ phiếu ba kỳ.</p><p><b>Giải từng bước:</b> Mua lần lượt 30, 20, 10 cổ phiếu; tổng 1.800 USD/60 cổ phiếu=30 USD/cổ phiếu; harmonic giá=3/(1/20+1/30+1/60)=30.</p><p class=\"answer\">Kết luận: Average acquisition price=30 USD/cổ phiếu</p><small>Liên kết kiến thức: harmonic</small></div>"},{"question_en":"E08 · Harmonic mean return phải dùng gross factor","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Harmonic mean return phải dùng gross factor</div><div class=\"body\"><p><b>Đề:</b> Ba kỳ lợi nhuận −10%, +20%, +5%.</p><p><b>Giải từng bước:</b> Gross factors: 0,90; 1,20; 1,05. Harmonic gross factor=3/(1/0,90+1/1,20+1/1,05); trừ 1 để có harmonic mean return.</p><p class=\"answer\">Kết luận: Harmonic mean return≈3,562%/kỳ</p><small>Liên kết kiến thức: harmonic</small></div>"},{"question_en":"E09 · Trimmed và winsorized cùng dữ liệu","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Trimmed và winsorized cùng dữ liệu</div><div class=\"body\"><p><b>Đề:</b> Chuỗi [1,2,4,8,70,100], mỗi phía loại/thay một quan sát.</p><p><b>Giải từng bước:</b> Trimmed bỏ 1 và 100 → (2+4+8+70)/4=21. Winsor thay 1→2 và 100→70 → (2+2+4+8+70+70)/6=26.</p><p class=\"answer\">Kết luận: Trimmed=21; Winsorized=26</p><small>Liên kết kiến thức: robust</small></div>"},{"question_en":"E10 · Chứng minh đẳng thức A×H=G² không tổng quát","steps_vi":[],"answer":"","html":"<div class=\"top\">E10 · Chứng minh đẳng thức A×H=G² không tổng quát</div><div class=\"body\"><p><b>Đề:</b> Các giá trị dương [1,2,3].</p><p><b>Giải từng bước:</b> Arithmetic=2; harmonic=3/(1+1/2+1/3)=18/11≈1,63636; geometric=(1×2×3)^(1/3)=6^(1/3)≈1,81712. A×H=36/11≈3,27273, G²≈3,30193.</p><p class=\"answer\">Kết luận: Bất đẳng thức giữa H, G, A vẫn đúng; đẳng thức đã in không tổng quát.</p><small>Liên kết kiến thức: source-note</small></div>"}],"questions":[{"stem_en":"A bond was purchased for 100, is worth 97 at period-end, and paid a coupon of 6. What is its holding-period return?","options":["−3%","3%","6%"],"correct":1,"why_vi":"(97−100+6)/100=3%. Lợi nhuận giá −3%; thu nhập coupon +6%.","trap_vi":""},{"stem_en":"Which input is NOT required for the basic realized one-period holding-period return formula?","options":["Beginning price","Expected return on the industry","Ending price"],"correct":1,"why_vi":"HPR thực hiện cần P0, P1 và thu nhập nhận được; không cần mức kỳ vọng ngành.","trap_vi":""},{"stem_en":"An investment earns +30% in Year 1 and −30% in Year 2. What is its cumulative two-year return?","options":["−9%","0%","+9%"],"correct":0,"why_vi":"1,30×0,70−1=−9%, không được cộng +30% với −30%.","trap_vi":""},{"stem_en":"For annual returns of −5%, +10%, and +7%, the arithmetic mean return is:","options":["3%","4%","12%"],"correct":1,"why_vi":"(−5+10+7)/3=4%.","trap_vi":""},{"stem_en":"An account grows from 100 to 200 in Year 1 and falls back to 100 in Year 2. Its annual geometric mean return is:","options":["0%","25%","50%"],"correct":0,"why_vi":"Gross product=2×0,5=1; căn hai trừ 1 bằng 0%.","trap_vi":""},{"stem_en":"Four consecutive six-month returns are given. Taking the fourth root of their compounded gross return factor yields the:","options":["Annual geometric mean return","Geometric mean return per six-month period","Cumulative return over two years"],"correct":1,"why_vi":"n=4 vì bốn khoảng nửa năm; annualized riêng bằng căn bậc 2 của gross factor hai năm.","trap_vi":""},{"stem_en":"Two annual returns are +15% and −5%. Their geometric mean annual return is closest to:","options":["5.0%","4.5%","10.0%"],"correct":1,"why_vi":"√(1,15×0,95)−1≈4,52%; thấp hơn arithmetic mean 5%.","trap_vi":""},{"stem_en":"Which statistic is most suitable for summarizing compounded historical wealth growth over five years?","options":["Geometric mean","Arithmetic mean","Return in the single best month"],"correct":0,"why_vi":"Geometric mean phản ánh compounding các lợi nhuận thực tế trong 5 năm.","trap_vi":""},{"stem_en":"Given three positive P/E ratios of 12, 18, and 36, their harmonic mean is:","options":["18","22","24"],"correct":0,"why_vi":"H=3/(1/12+1/18+1/36)=18x.","trap_vi":""},{"stem_en":"An investor contributes USD 500 at a share price of USD 10 and another USD 500 at USD 20. The average purchase cost per share is closest to:","options":["USD 15.00","USD 13.33","USD 20.00"],"correct":1,"why_vi":"Tổng 1.000 USD mua được 50+25=75 cổ phiếu, average 13,33 USD = harmonic mean của 10 và 20.","trap_vi":""},{"stem_en":"For returns of −20% and +25%, which expression calculates the harmonic mean of gross returns, then converts it back to a net return?","options":["2/(1/−0.20 + 1/0.25)","2/(1/0.8 + 1/1.25) − 1","(−20 + 25)/2"],"correct":1,"why_vi":"Cần đổi lợi nhuận thành gross factors 1+R >0 trước khi lấy harmonic.","trap_vi":""},{"stem_en":"What distinguishes a trimmed mean from a winsorized mean?","options":["Trimming removes extreme observations, whereas winsorizing replaces them","Trimming always preserves the original sample size","Winsorizing always removes both tails"],"correct":0,"why_vi":"Trimmed giảm cỡ mẫu; winsorized giữ số phần tử nhưng thay các giá trị ở biên.","trap_vi":""},{"stem_en":"For the sorted data [1, 2, 4, 8, 70, 100], what is the mean after trimming one observation from each end?","options":["4","21","26"],"correct":1,"why_vi":"Bỏ 1,100, trung bình 2,4,8,70 = 84/4=21.","trap_vi":""},{"stem_en":"For the data [1, 2, 4, 8, 70, 100], replace the lowest value by 2 and the highest by 70. The winsorized mean is:","options":["21","26","29"],"correct":1,"why_vi":"Chuỗi mới [2,2,4,8,70,70], trung bình 156/6=26.","trap_vi":""},{"stem_en":"For unequal positive observations, which ordering of means is correct?","options":["Arithmetic < geometric","Harmonic > geometric","Harmonic < geometric < arithmetic"],"correct":2,"why_vi":"Bất đẳng thức HM≤GM≤AM; khi khác nhau và các giá trị dương, là bất đẳng thức nghiêm.","trap_vi":""},{"stem_en":"For which case is the identity arithmetic mean × harmonic mean = (geometric mean)² generally valid?","options":["Every dataset containing at least three observations","Two positive observations (and some special datasets)","Every return series containing negative observations"],"correct":1,"why_vi":"Công thức in trong Curriculum không phải đẳng thức tổng quát cho n>2.","trap_vi":""},{"stem_en":"How should Excel calculate the geometric mean of decimal annual returns in A1:A3?","options":["Apply GEOMEAN directly to A1:A3","Apply GEOMEAN to the array (1+A1:A3), then subtract 1","Apply AVERAGE to A1:A3"],"correct":1,"why_vi":"Phải GEOMEAN các 1+R và trừ 1; không dùng trực tiếp GEOMEAN cho các returns có thể âm.","trap_vi":""},{"stem_en":"When is the harmonic mean directly suitable for average share purchase price across transactions?","options":["The same number of shares is bought each time","An equal dollar amount is invested each time","Each purchase is 10% of existing shares"],"correct":1,"why_vi":"Cố định số tiền mỗi kỳ tạo số lượng cổ phiếu tỷ lệ nghịch với giá mua.","trap_vi":""},{"stem_en":"For a simple estimate of an expected one-period return using historical observations, the natural starting point is the:","options":["Arithmetic mean","Historical CAGR in every situation","Harmonic mean of P/E ratios"],"correct":0,"why_vi":"Arithmetic mean đo trung bình các quan sát lợi nhuận một kỳ, không cam kết dự báo chính xác.","trap_vi":""},{"stem_en":"When dividends are received and reinvested within a holding period, which statement is most accurate?","options":["A simple price-change-plus-income HPR may not capture the return on reinvested dividends","Dividends must automatically be counted twice","HPR must be negative"],"correct":0,"why_vi":"Khoản tái đầu tư giữa kỳ làm thay đổi tổng wealth và cần tính đúng theo thời điểm nhận cổ tức.","trap_vi":""}],"cards":[{"front_en":"Hai thành phần total return?","back_vi":"Income yield (dividend/coupon) và capital return (price appreciation/depreciation)."},{"front_en":"HPR một kỳ?","back_vi":"(P1−P0+I1)/P0. Kỳ có thể bất kỳ độ dài, không mặc nhiên 1 năm."},{"front_en":"Tổng HPR qua nhiều kỳ?","back_vi":"Nhân ∏(1+Rt) rồi trừ 1; không cộng các Rt."},{"front_en":"Arithmetic mean phù hợp nhất cho?","back_vi":"Lợi nhuận trung bình một kỳ và ước lượng one-period expected return (với giả định phù hợp)."},{"front_en":"Geometric mean phản ánh gì?","back_vi":"Tỷ lệ tăng trưởng kép bình quân lịch sử của vốn thực sự."},{"front_en":"Geometric annual từ 4 kỳ nửa năm?","back_vi":"Lấy căn bậc 2 của gross factor của 2 năm rồi trừ 1."},{"front_en":"Harmonic mean X>0?","back_vi":"n/Σ(1/Xi); hữu ích cho giá/tỷ số và dollar-cost averaging tiền bằng nhau."},{"front_en":"Harmonic return với Rt âm?","back_vi":"Tính harmonic của gross factors 1+Rt rồi trừ 1, chỉ khi 1+Rt>0."},{"front_en":"Trimmed vs winsorized?","back_vi":"Trimmed loại quan sát biên; winsorized thay giá trị biên bằng giá lân cận."},{"front_en":"Bất đẳng thức ba mean?","back_vi":"HM≤GM≤AM với dữ liệu dương."},{"front_en":"Cẩn trọng đẳng thức AM×HM=GM²?","back_vi":"Không đúng tổng quát khi n>2; đúng mọi bộ hai giá trị dương."},{"front_en":"Excel GEOMEAN cho returns?","back_vi":"GEOMEAN(1+Rt)-1 thay vì GEOMEAN(Rt), gross factor phải dương."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Trang nguồn đã đọc và đối chiếu Trang PDF tính từ trang đầu của từng file, không phải số trang in ở chân giáo trình. CFAI26 — CFA Institute Curriculum 2026, Quantitative Methods, Learning Module 1, trang PDF 16–27 (phần Rates of Return) KAPLAN26 — Kaplan SchweserNotes 2026, Book 1, PDF trang 15–19 (LOS 1.b) SAPP26 — SAPP CFA Level 1 Quant 2026, PDF trang 10–15 (LOS 1.b) CFAI24 — CFA Institute 2024 Prerequisite Reading Quant, PDF trang 116–123 (mean measures, background) MINDMAP — SAPP Quant Revision Mindmap, PDF trang 1 (bản đồ Rates and Returns) BONUSQB — Question Banks Bonus 2026, Rates and Returns Questions, PDF trang 1–16 (chỉ tham khảo dạng đề) Phạm vi kết luận: 28 ý thuộc LOS 1.b được kiểm tra theo Curriculum 2026 và các nguồn phụ có nội dung liên quan. Các đề Mock lịch sử chưa được rà soát tất cả từng câu; vì vậy không tuyên bố đã bao phủ toàn bộ 534 PDF. Bất kỳ lỗi/khác biệt phát hiện giữa các nguồn được ghi nhận minh bạch thay vì sao chép làm công thức áp dụng chung."}],"legacy":"sourcefirst-quant-rates-los02.html"},{"id":"CFA26-01-01-LOS03","letter":"c","title_en":"Money-Weighted and Time-Weighted Returns","outcome_en":"Money-Weighted vs Time-Weighted Returns","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Học đúng LOS 1.c","body":"","html":"<p class=\"lead\">Tại sao cùng một danh mục có thể có hai con số lợi nhuận rất khác nhau? Điểm mấu chốt là ai quyết định nộp/rút vốn và thời điểm vốn thực sự chịu rủi ro.</p><div class=\"badgeline\"><span class=\"tag\">25 ý kiến thức đã đối chiếu</span><span class=\"tag\">9 ví dụ tự tính</span><span class=\"tag\">18 câu luyện tập</span><span class=\"tag muted\">Bài riêng cho LOS 1.c</span></div>","trap":""},{"heading":"1. Hai câu hỏi khác nhau dẫn đến hai thước đo khác nhau","body":"","html":"<p><b>Money-Weighted Return (MWR)</b> phản ánh mức sinh lời gắn với <em>đúng số vốn và đúng thời điểm</em> nhà đầu tư thực tế đưa vào hoặc rút ra. <b>Time-Weighted Return (TWR)</b> phản ánh tốc độ tăng trưởng kép của 1 đồng vốn được đầu tư trong danh mục qua từng phân đoạn, loại bỏ ảnh hưởng cơ học của các khoản nộp/rút vốn bên ngoài.</p><p>Hai nhà đầu tư nắm cùng một quỹ có thể có <b>TWR như nhau</b> nhưng <b>MWR khác nhau</b>, vì một người tăng vốn trước giai đoạn quỹ giảm và người kia tăng vốn trước giai đoạn quỹ tăng. Khi đánh giá kỹ năng người quản lý danh mục mà khách hàng quyết định dòng tiền ngoài, Curriculum ưu tiên TWR; MWR mô tả trải nghiệm tài chính của chính nhà đầu tư.</p><p><strong>Phân biệt thêm:</strong> khoản cổ tức, lãi trái phiếu, lãi/lỗ giao dịch thuộc lợi nhuận do khoản đầu tư tạo ra; nộp/rút vốn của khách hàng là <em>external cash flows</em> đối với TWR. Không tự loại cổ tức khỏi total return.</p>","trap":""},{"heading":"2. MWR và phương trình IRR: quy ước dấu theo góc nhìn nhà đầu tư","body":"","html":"<div class=\"formula-big\">0 = CF₀ + CF₁/(1+r) + CF₂/(1+r)² + … + CFₙ/(1+r)ⁿ</div><p>Với các thời điểm <em>cách đều nhau</em>, giải phương trình giá trị hiện tại bằng 0 để lấy IRR mỗi khoảng. Trong giáo trình, đây chính là <b>money-weighted rate of return</b>. Đứng từ nhà đầu tư: bỏ tiền mua hoặc nộp thêm = âm (outflow); tiền cổ tức không tái đầu tư, bán chứng khoán, rút vốn và <em>giá trị cuối kỳ danh mục giả định thanh lý</em> = dương (inflow). Mọi dòng tiền ở cùng ngày cần cộng đại số trước khi nhập máy.</p><p><strong>Ví dụ:</strong> mua cổ phiếu thứ hai 120 ngay khi nhận dividend 5 =&gt; tiền mới thực chi trong ngày = 120 − 5 = 115, nên CF tại ngày đó là −115 (nếu cổ tức không tái đầu tư vào cổ phiếu sẵn có). Đừng đếm khoản dividend thêm lần nữa ở cuối kỳ.</p><p><strong>Quy ước đối xứng:</strong> từ góc nhìn quỹ, tiền khách hàng nộp vào là <em>inflow</em> cho quỹ; từ góc nhìn nhà đầu tư tính MWR, đó là <em>outflow</em>. Chỉ cần giữ nhất quán dấu, đổi toàn bộ dấu dòng tiền sẽ không thay IRR.</p>","trap":""},{"heading":"3. Thời điểm dòng tiền: t=0, t=1, t=2 phải khớp lịch","body":"","html":"<p>CFAI dùng CF₀ ở đầu kỳ thứ nhất (không discount), CF₁ ở cuối kỳ 1/đầu kỳ 2 và cứ thế. Một khoản <em>đóng ngay đầu năm thứ hai</em> nằm ở <b>t=1</b>, không phải t=2. Nếu đặt sai thời điểm một khoản nộp lớn, MWR có thể đổi đáng kể dù kết quả phát triển danh mục là như nhau.</p><p>IRR tính theo đơn vị khoảng của bảng cash flow. Nếu các dòng tiền cách nhau một quý, kết quả IRR là lợi nhuận một quý; nếu cách nhau 4 tháng thì kết quả là lợi nhuận 4 tháng. Annualized compounded return = (1+IRR<sub>period</sub>)<sup>m</sup>−1, với m kỳ như nhau một năm. Không nhân m nếu câu hỏi yêu cầu chính xác compounded annual rate; phép nhân m chỉ là simple annual approximation.</p>","trap":""},{"heading":"4. TWR chính xác: định giá trước dòng tiền ngoài và chia các phân đoạn","body":"","html":"<ol class=\"spaced\"><li><b>Định giá danh mục ngay trước</b> khoản đóng/rút vốn ngoài đáng kể; lấy đó làm điểm cắt.</li><li>Tính <b>HPR của từng subperiod</b>, không để khoản nộp/rút vốn ngoài làm tăng/giảm return của nhà quản lý.</li><li><b>Liên kết nhân</b> các gross subperiod returns: ∏(1+rᵢ)−1. Với nhiều năm đủ, annualized TWR = [∏(1+R<sub>year</sub>)]<sup>1/N</sup>−1.</li></ol><p>Nếu dòng tiền vào đúng đầu phân đoạn, mẫu số HPR là giá trị sau khi điều chỉnh khoản nộp/rút vào đầu kỳ; tử số là giá trị cuối phân đoạn trước dòng tiền ở mốc kế tiếp. Nếu một dòng tiền xảy ra cuối phân đoạn, định giá trước dòng tiền đó. Không được cộng khoản nộp của nhà đầu tư vào “lợi nhuận”.</p><div class=\"formula-big\">TWR<sub>horizon</sub> = ∏(1+r<sub>subperiod</sub>) − 1</div><p><strong>Quan trọng:</strong> hai phân đoạn 4 tháng và 8 tháng ghép thành một năm thì chỉ nhân hai gross factors để ra return <em>cả năm</em>. Không lấy căn bậc 2; hai phân đoạn không phải hai năm.</p>","trap":""},{"heading":"5. TWR một kỳ đo lường khác annualized TWR","body":"","html":"<p>Biểu thức ∏(1+rᵢ)−1 cho <strong>toàn bộ horizon</strong>. Khi horizon đúng 1 năm, nó chính là annual return. Khi horizon dài N năm, lấy căn bậc N của gross factor tổng rồi trừ 1. Trong một năm có 4 quý, <b>không</b> lấy căn bậc 4 từ 4 HPR quý nếu mục tiêu là suất sinh lời <em>năm</em>; tích bốn yếu tố đã là lợi nhuận năm.</p><p>Do IRR luôn theo kỳ giữa CF, TWR theo horizon của phân đoạn, phải chuẩn hóa cùng tần suất thời gian trước khi so MWR với TWR. So “MWR quý” trực tiếp với “TWR năm” là sai đơn vị.</p>","trap":""},{"heading":"6. Khi nào MWR lớn hơn/nhỏ hơn TWR?","body":"","html":"<p>Nếu nhà đầu tư bỏ vốn <strong>nhiều</strong> trước giai đoạn hiệu quả <strong>kém</strong>, kết quả MWR thường thấp hơn TWR. Ngược lại, vốn tăng trước một giai đoạn mạnh có thể khiến MWR cao hơn TWR. Đây là kết quả trọng số kinh tế theo dòng tiền, không phải quy tắc bất biến nếu dòng tiền rút/nộp phức tạp.</p><p><b>TWR cùng danh mục, MWR khác:</b> khi quỹ có +20% năm 1 và −10% năm 2, nếu nộp thêm ngay đầu năm 2, nhà đầu tư chịu phần lỗ cuối kỳ trên cơ sở vốn lớn hơn. TWR annual ≈ 3,923%, nhưng MWR có thể âm. Tình huống đảo ngược (nộp thêm trước năm tốt) có thể tạo MWR cao hơn TWR.</p>","trap":""},{"heading":"7. Exact versus approximate TWR: định giá hàng ngày","body":"","html":"<p>TWR chính xác yêu cầu định giá ngay trước các dòng tiền ngoài đáng kể. Khi dòng tiền diễn ra thường xuyên, việc này có thể tốn chi phí; CFAI chấp nhận xấp xỉ bằng định giá định kỳ đủ thường xuyên, chẳng hạn theo ngày. Nếu dòng tiền rút/nộp đều xảy ra <em>cuối ngày</em>, liên kết các HPR ngày có thể là TWR chính xác cho kỳ đó. Nếu dòng tiền chen giữa các lần định giá, chỉ là xấp xỉ.</p><p>Độ chính xác của xấp xỉ thường tăng với tần suất định giá, đặc biệt khi dòng tiền không tương quan với biến động thị trường. Đừng gọi “daily linked return” luôn luôn chính xác nếu không biết thời điểm giao dịch.</p>","trap":""},{"heading":"8. Nhập MWR vào máy tính tài chính/Excel","body":"","html":"<p><b>BA II Plus:</b> dùng chức năng <code>CF</code>, xóa bảng dòng tiền cũ, nhập <code>CF0</code>, từng <code>C01</code>, <code>C02</code>… và tần suất <code>F01/F02</code> phù hợp. Vào <code>IRR</code>, bấm <code>CPT</code>. Quy ước âm/dương theo góc nhìn đã chọn; máy không hiểu nộp tiền là “âm” nếu bạn không nhập dấu âm.</p><p><b>Excel:</b> <code>IRR({CF0,CF1,...})</code> dùng được nếu khoảng thời gian giữa các giá trị bằng nhau. Với lịch không đều, phải thiết lập phương trình theo các khoảng thời gian thật; không giả vờ rằng mọi khoảng là một quý/năm. <strong>Không cần máy tính tài chính</strong> cho TWR nếu có đầy đủ HPR từng phân đoạn: chỉ việc nhân các gross factors.</p>","trap":""},{"heading":"9. Giới hạn khi đánh giá nhà quản lý danh mục","body":"","html":"<p>TWR ưu tiên vì ít bị dòng tiền nhà đầu tư chi phối, nhưng <strong>mức TWR cao hơn không tự chứng minh người quản lý tốt hơn</strong>. CFA Institute nhấn mạnh phải xét rủi ro, benchmark, mandate và các yếu tố khác khi đánh giá. MWR cho biết nhà đầu tư cụ thể kiếm được gì trên số tiền đã bỏ vào, nhưng khó dùng so trực tiếp hai khách hàng với lịch nộp/rút khác nhau.</p>","trap":""}],"formulas":[{"name":"2. MWR và phương trình IRR: quy ước dấu theo góc nhìn nhà đầu tư","expr":"0 = CF₀ + CF₁/(1+r) + CF₂/(1+r)² + … + CFₙ/(1+r)ⁿ","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. TWR chính xác: định giá trước dòng tiền ngoài và chia các phân đoạn","expr":"TWR horizon = ∏(1+r subperiod ) − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · Nộp thêm trước năm xấu","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · Nộp thêm trước năm xấu</div><div class=\"body\"><p><strong>Đề:</strong> V0=100; năm 1 tăng 20% lên 120; nộp thêm 100 ở đầu năm 2; năm 2 giảm 10% về 198.</p><p><strong>Phân tích và phép tính:</strong> TWR annual=√(1,20×0,90)−1≈3,923%. MWR theo CF [−100, −100, +198] giải −100−100/(1+r)+198/(1+r)²=0, nên r≈−0,668%.</p><p class=\"answer\">Kết luận: TWR≈+3,923%/năm, MWR≈−0,668%/năm.</p><small>Kiến thức: behavior</small></div>"},{"question_en":"E02 · Nộp thêm trước năm tốt","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · Nộp thêm trước năm tốt</div><div class=\"body\"><p><strong>Đề:</strong> V0=100; năm 1 lợi nhuận 0%; tại t=1 nộp thêm 100; năm 2 sinh lời +20%, giá trị cuối 240.</p><p><strong>Phân tích và phép tính:</strong> TWR annual=√(1,00×1,20)−1≈9,545%. MWR theo CF [−100,−100,+240] giải phương trình IRR, r≈12,788%.</p><p class=\"answer\">Kết luận: MWR≈12,788% &gt; TWR≈9,545%.</p><small>Kiến thức: behavior</small></div>"},{"question_en":"E03 · Cổ tức và mua thêm cổ phiếu","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Cổ tức và mua thêm cổ phiếu</div><div class=\"body\"><p><strong>Đề:</strong> T0 mua 1 cổ phiếu giá 100; T1 giá 120, nhận cổ tức 5 rồi mua thêm 1 cổ phiếu giá 120; T2 bán 2 cổ phiếu giá 130/cổ phiếu và nhận cổ tức 5/cổ phiếu.</p><p><strong>Phân tích và phép tính:</strong> T1 net CF=+5−120=−115; T2 net CF=2×130+2×5=270. IRR CF [−100,−115,+270] ≈16,587%. HPR1=(120+5−100)/100=25%; HPR2=(270−240)/240=12,5%; TWR annual=√(1,25×1,125)−1≈18,585%.</p><p class=\"answer\">Kết luận: MWR≈16,587%; TWR≈18,585%.</p><small>Kiến thức: signs</small></div>"},{"question_en":"E04 · Exact TWR có tiền nộp giữa kỳ","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Exact TWR có tiền nộp giữa kỳ</div><div class=\"body\"><p><strong>Đề:</strong> Danh mục đầu năm 100; giữa năm trước khi nộp vốn giá trị 110; nộp thêm 90, tạo vốn đầu phân đoạn sau là 200; cuối năm giá trị 180.</p><p><strong>Phân tích và phép tính:</strong> Subperiod 1: (110−100)/100=+10%. Subperiod 2: (180−200)/200=−10%. TWR toàn năm=1,10×0,90−1=−1%.</p><p class=\"answer\">Kết luận: TWR năm=−1%; tuyệt đối không coi 90 nộp vào là lợi nhuận.</p><small>Kiến thức: twr-procedure</small></div>"},{"question_en":"E05 · MWR lịch nộp tiền giữa năm","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · MWR lịch nộp tiền giữa năm</div><div class=\"body\"><p><strong>Đề:</strong> Sử dụng dòng tiền của E04 nhưng biểu diễn hai khoảng nửa năm: tại t=0 đầu tư 100; t=0,5 năm nộp 90; t=1 năm nhận 180.</p><p><strong>Phân tích và phép tính:</strong> Giải −100−90/(1+r)^0,5+180/(1+r)=0 theo r hàng năm. Đặt y=√(1+r), giải 100y²+90y−180=0, cho y≈0,965097; r≈−6,859%.</p><p class=\"answer\">Kết luận: MWR annual≈−6,859%; TWR cùng năm=−1%.</p><small>Kiến thức: timing</small></div>"},{"question_en":"E06 · Ghép bốn quý thành một năm","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Ghép bốn quý thành một năm</div><div class=\"body\"><p><strong>Đề:</strong> Danh mục có lợi nhuận quý +5%, −2%, +4%, +3%, không có external CF.</p><p><strong>Phân tích và phép tính:</strong> TWR cả năm = (1,05)(0,98)(1,04)(1,03)−1≈10,22648%. Không lấy căn 4 vì bốn quý cộng lại đúng 1 năm.</p><p class=\"answer\">Kết luận: TWR năm≈10,226%; không phải geometric quarterly return.</p><small>Kiến thức: annualization</small></div>"},{"question_en":"E07 · TWR hai năm cần annualize","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · TWR hai năm cần annualize</div><div class=\"body\"><p><strong>Đề:</strong> Danh mục tăng tổng 12% năm 1 và giảm 5% năm 2, mỗi năm đã có TWR riêng.</p><p><strong>Phân tích và phép tính:</strong> TWR toàn 2 năm=(1,12)(0,95)−1=+6,4%. Annualized TWR=√(1,064)−1≈3,15%/năm.</p><p class=\"answer\">Kết luận: TWR tổng kỳ=6,4%; annualized≈3,15%/năm.</p><small>Kiến thức: annualization</small></div>"},{"question_en":"E08 · Đổi dấu CF không đổi IRR","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Đổi dấu CF không đổi IRR</div><div class=\"body\"><p><strong>Đề:</strong> Nhà đầu tư có CF [−100,−100,+198].</p><p><strong>Phân tích và phép tính:</strong> Đổi toàn bộ dấu thành [+100,+100,−198] sẽ tạo cùng phương trình bằng 0 sau nhân −1 nên cho cùng nghiệm IRR. Nhưng đổi dấu chỉ một CF là làm sai kinh tế.</p><p class=\"answer\">Kết luận: Cùng IRR nếu đổi dấu *toàn bộ* dòng tiền.</p><small>Kiến thức: signs</small></div>"},{"question_en":"E09 · IRR cho dòng tiền bốn tháng","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · IRR cho dòng tiền bốn tháng</div><div class=\"body\"><p><strong>Đề:</strong> Bỏ vốn tại t0 −150; đóng thêm −30 sau 4 tháng; không có dòng tiền sau 8 tháng; nhận +215 sau 12 tháng.</p><p><strong>Phân tích và phép tính:</strong> Dùng CF [−150,−30,0,+215] theo 4 tháng; giải IRR kỳ≈6,462%; annual compounded=(1+IRR)^3−1≈20,665%. Đây là tình huống mới với dòng tiền khác dữ liệu tài liệu gốc.</p><p class=\"answer\">Kết luận: MWR năm khoảng 20,665% (tùy làm tròn IRR kỳ).</p><small>Kiến thức: timing</small></div>"}],"questions":[{"stem_en":"Which return measure is most sensitive to a large external contribution immediately before a period of poor performance?","options":["Time-weighted return","Money-weighted return","Both measures are always equally sensitive"],"correct":1,"why_vi":"MWR tính theo IRR dòng tiền thực tế và nhạy về timing/amount của vốn. TWR triệt ảnh hưởng cơ học của external cash flows.","trap_vi":""},{"stem_en":"From the investor's perspective, an additional USD 50 contribution at t=1 is recorded as:","options":["CF1 = −50","CF1 = +50","CF0 = −50"],"correct":0,"why_vi":"Tiền nộp vào là cash outflow của nhà đầu tư tại chính thời điểm t=1.","trap_vi":""},{"stem_en":"On the same date an investor buys an additional USD 120 of fund units and receives a USD 5 cash dividend. With no other cash flows, the net cash flow is:","options":["+125","−125","−115"],"correct":2,"why_vi":"+5−120=−115.","trap_vi":""},{"stem_en":"Which equation defines the money-weighted return (IRR) for equally spaced cash flows?","options":["Σ CFt/(1+r)^t = 0","Π(1+Rt) − 1","Σ Rt/n"],"correct":0,"why_vi":"MWR là IRR của cash flows thực tế theo quy ước dấu.","trap_vi":""},{"stem_en":"For an exact time-weighted return, a portfolio should be valued at which point around a significant external cash flow?","options":["Immediately after the external cash flow only","Immediately before the external cash flow","Only at the beginning and end of the year"],"correct":1,"why_vi":"Giá trị ngay trước cash flow giúp cô lập HPR của phân đoạn trước, tránh coi vốn mới là lợi nhuận.","trap_vi":""},{"stem_en":"A portfolio earns 12% in the first four months and 8% in the next eight months. Its linked return over the full year is closest to:","options":["10.0%","20.96%","9.9%"],"correct":1,"why_vi":"1,12×1,08−1=20,96%; hai phân đoạn cộng thành một năm, không lấy căn 2.","trap_vi":""},{"stem_en":"A portfolio's annual returns are +10%, −5%, and +15%. Which formula produces the annualized time-weighted return over three years?","options":["(1.10 × 0.95 × 1.15)^(1/3) − 1","1.10 × 0.95 × 1.15 − 1","(10 − 5 + 15)/3"],"correct":0,"why_vi":"Vì chuỗi kéo dài 3 năm, căn bậc 3 của gross factor toàn kỳ.","trap_vi":""},{"stem_en":"If successive investor cash flows occur four months apart, a conventional equally spaced IRR calculation first gives a return per:","options":["Year","Month","Four-month period"],"correct":2,"why_vi":"IRR trả về lãi mỗi khoảng cách đều của dãy CF; annualize compound với m=3.","trap_vi":""},{"stem_en":"If the money-weighted return is +5% for four months, the annualized compound return is closest to:","options":["5.00%","15.76%","15.00%"],"correct":1,"why_vi":"(1,05)^3−1=15,7625%; nhân 3 chỉ là xấp xỉ 15%.","trap_vi":""},{"stem_en":"Two investors hold the same fund over the same period but contribute on different dates. Which result is typically possible?","options":["Same fund TWR but different investor MWRs","Investor MWRs must always be identical","Fund TWR automatically changes solely because of the contribution amounts"],"correct":0,"why_vi":"TWR tách external CF; MWR phụ thuộc lượng tiền và timing của từng nhà đầu tư.","trap_vi":""},{"stem_en":"A portfolio earns +10% in one subperiod and −10% in the next. What is its linked time-weighted return?","options":["0%","−1%","−10%"],"correct":1,"why_vi":"1,10×0,90−1=−1%.","trap_vi":""},{"stem_en":"A large contribution is made just before a period of negative performance. Relative to TWR, the investor's MWR will tend to be:","options":["Higher","Necessarily equal","Lower"],"correct":2,"why_vi":"Một khoản vốn lớn chịu return kém tạo tác động lớn lên IRR của nhà đầu tư.","trap_vi":""},{"stem_en":"Given accurate subperiod holding-period returns, how is the total time-weighted return calculated?","options":["Solve IRR from investor cash flows","Multiply gross subperiod returns and subtract 1","Average the subperiod returns arithmetically"],"correct":1,"why_vi":"TWR liên kết compounding của các phân đoạn đã chia theo cash flows ngoài.","trap_vi":""},{"stem_en":"Under which condition can daily linked returns represent an exact TWR?","options":["External cash flows are correctly aligned with daily valuations, for example at every day's end","Large unvalued intraday flows occur","The dataset merely contains 365 observations"],"correct":0,"why_vi":"Exact TWR phải định giá ngay trước external CF; nếu CF giữa hai lần định giá, daily link chỉ xấp xỉ.","trap_vi":""},{"stem_en":"Portfolio A has a higher TWR than Portfolio B. Is this alone sufficient to identify better management?","options":["Yes, always","No; risk, objectives, and benchmarks also matter","No, because TWR is inherently invalid"],"correct":1,"why_vi":"Curriculum nhấn mạnh đánh giá performance phải điều chỉnh rủi ro và so theo mục tiêu/benchmark.","trap_vi":""},{"stem_en":"An investor contributes 100 at t=0 and another 100 at t=1, then withdraws 198 at t=2. Which investor-perspective IRR cash flows are correct?","options":["[−100, +100, +198]","[−100, −100, +198]","[+100, −100, +198]"],"correct":1,"why_vi":"Từ phía người đầu tư hai lần nộp vốn là âm, terminal value nhận về là dương.","trap_vi":""},{"stem_en":"For a money-weighted return calculation, a cash coupon received but not reinvested should be:","options":["Included as a positive cash flow when received","Ignored entirely","Always added to CF0"],"correct":0,"why_vi":"Cash received by investor is an inflow at its date; nếu coupon đã dùng để mua thêm thì phải lập net CF cùng ngày.","trap_vi":""},{"stem_en":"Which statement about time-weighted performance is most accurate?","options":["TWR removes market risk","TWR measures linked investment performance, but risk and benchmarks are still needed to evaluate skill","TWR measures only new contributions"],"correct":1,"why_vi":"TWR loại external CF effect, không loại rủi ro giá và không cho đánh giá đầu tư “tốt” tuyệt đối.","trap_vi":""}],"cards":[{"front_en":"Money-weighted return là gì?","back_vi":"IRR của các dòng tiền thực tế của nhà đầu tư, xét cả lượng và thời điểm vốn."},{"front_en":"Time-weighted return là gì?","back_vi":"Tốc độ tăng trưởng ghép lãi của 1 đơn vị vốn, tách external cash flows."},{"front_en":"Khi nhà đầu tư nộp thêm vốn, dấu CF ở góc nhìn nhà đầu tư?","back_vi":"Âm; khoản rút/cổ tức không tái đầu tư/terminal value là dương."},{"front_en":"Ba bước exact TWR?","back_vi":"Định giá ngay trước external CF; tính HPR mỗi phân đoạn; nhân (1+HPR) rồi trừ 1."},{"front_en":"Nộp thêm tiền trước kỳ lỗ lớn làm MWR thế nào?","back_vi":"MWR có xu hướng thấp hơn TWR."},{"front_en":"Hai phân đoạn 4 tháng+8 tháng trong một năm: dùng căn bậc 2 không?","back_vi":"Không. Nhân gross returns của hai phân đoạn để tính return trọn 1 năm."},{"front_en":"Đo return trên 3 năm thì annualized TWR thế nào?","back_vi":"(Gross factor toàn 3 năm)^(1/3)−1."},{"front_en":"IRR máy tính với CF cách đều nhau 4 tháng là lãi kỳ nào?","back_vi":"Lãi mỗi 4 tháng; annualize compound bằng (1+IRR)^3−1."},{"front_en":"Cổ tức được nhận cùng ngày mua thêm chứng khoán xử lý?","back_vi":"Gộp algebraic net CF theo ngày, tránh đếm hai lần."},{"front_en":"Daily TWR có chính xác nếu nộp/rút giữa ngày?","back_vi":"Không nhất thiết, cần định giá đúng ngay trước thời điểm dòng tiền ngoài."},{"front_en":"Đánh giá nhà quản lý có cần xét thêm rủi ro?","back_vi":"Có. TWR cao chưa đủ kết luận hiệu quả điều chỉnh rủi ro tốt."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn kiểm tra CFAI26 — CFA Institute Curriculum 2026, Quantitative Methods, PDF trang 27–36, gồm Exhibits 10–15, Examples 8–10 và phần giải thích 3 bước TWR KAPLAN26 — Kaplan SchweserNotes 2026 Book 1, PDF trang 19–22, Module 1.2 (MWR/TWR) SAPP26 — SAPP Quant 2026, PDF trang 16–23 (IRR, timeline, ví dụ cổ tức, máy tính tài chính) CFAI24 — CFA Institute 2024 Prerequisite Quant (nền tảng PV/IRR, dùng khi giải dòng tiền), đối chiếu theo chủ đề MINDMAP — SAPP Quant Revision Mindmap, PDF trang 1, sơ đồ Rates and Returns QBANK — Question Banks Bonus 2026, Rates and Returns, PDF trang 1–16, xem dạng bài không sao chép nội dung Phạm vi trung thực: đã đối chiếu 25 ý về MWR/TWR với Curriculum, Kaplan và SAPP; số liệu ví dụ và câu hỏi mới. Chưa xác nhận đã rà soát toàn bộ câu hỏi của tất cả Mock Exam lịch sử có liên quan. Các LOS chưa thực hiện không được coi là đã kiểm định."}],"legacy":"sourcefirst-quant-rates-los03.html"},{"id":"CFA26-01-01-LOS04","letter":"d","title_en":"Annualized and Continuously Compounded Returns","outcome_en":"Annualized and Continuously Compounded Returns","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 1.d","body":"","html":"<p class=\"lead\">LOS 1.d — Annualization, periodic compounding, effective annual rate và log returns</p><div class=\"badgeline\"><span class=\"tag\">21 ý kiến thức đối chiếu</span><span class=\"tag\">9 ví dụ mới</span><span class=\"tag\">16 câu luyện tập</span><span class=\"tag muted\">Chỉ nghiệm thu phạm vi LOS này</span></div>","trap":""},{"heading":"1. Annualized return giúp so sánh những kỳ không cùng độ dài","body":"","html":"<p>Một suất sinh lời 4% trong một quý <strong>không tương đương</strong> 4% trong một năm. Chuẩn hóa về năm giúp so các tài sản có kỳ nắm giữ khác nhau và đưa tỷ lệ về đúng đơn vị mô hình định giá. Mọi phép chuyển theo quy tắc ghép lãi phải nêu rõ <strong>độ dài kỳ</strong> và <strong>quy ước số ngày</strong>.</p><div class=\"formula-big\">R<sub>annual</sub> = (1+R<sub>period</sub>)<sup>c</sup>−1</div><p><b>c</b> là số kỳ loại đang đo trong một năm: 12 với lợi nhuận một tháng; 4 với lợi nhuận một quý; 365/d với kỳ dài d ngày (theo quy ước 365 ngày). Nếu kỳ dài hơn một năm, c có thể nhỏ hơn 1, ví dụ 18 tháng → c=12/18=2/3.</p>","trap":""},{"heading":"2. Từ lợi nhuận ngày/tuần/tháng/quý sang năm","body":"","html":"<p>Đối với kỳ d ngày và quy ước 365 ngày: <span class=\"math\">(1+R<sub>d</sub>)<sup>365/d</sup>−1</span>. Với lợi nhuận tuần nếu lấy 52 tuần/năm: <span class=\"math\">(1+R<sub>week</sub>)<sup>52</sup>−1</span>. Với kỳ 2 tháng: lấy lũy thừa 6. Với 18 tháng: lũy thừa 2/3.</p><p><strong>Chiều ngược lại:</strong> R<sub>month</sub>=(1+R<sub>annual</sub>)<sup>1/12</sup>−1; R<sub>week</sub>=(1+R<sub>annual</sub>)<sup>1/52</sup>−1. Nếu lấy lợi nhuận ngày theo tuần giao dịch, dùng 5 trading days; nếu theo ngày lịch, có 7 ngày/tuần. Số ngày năm giao dịch có thể lấy gần 250 (hoặc quy ước khác), không được tự đổi 365 thành 252 khi đề đang dùng 365.</p>","trap":""},{"heading":"3. Stated annual rate, periodic interest và số kỳ tính lãi","body":"","html":"<p><strong>Quoted/stated annual rate (R<sub>s</sub>)</strong> khi ghép lãi m lần/năm tạo tỷ lệ <strong>mỗi kỳ</strong> bằng R<sub>s</sub>/m. Tổng số kỳ qua N năm là mN.</p><div class=\"formula-big\">FV = PV × (1+R<sub>s</sub>/m)<sup>mN</sup> ; PV = FV/(1+R<sub>s</sub>/m)<sup>mN</sup></div><p>Không dùng lãi suất được ghi 6% năm trực tiếp cho mọi tháng. Với annual compounding m=1; semiannual m=2; quarterly m=4; monthly m=12. <b>Effective annual rate (EAR)</b> của lãi danh nghĩa R<sub>s</sub> được tính bằng <span class=\"math\">(1+R<sub>s</sub>/m)<sup>m</sup>−1</span>. Nếu R<sub>s</sub> dương, ghép lãi nhiều lần hơn tạo EAR cao hơn khi cùng nominal R<sub>s</sub>.</p>","trap":""},{"heading":"4. Annualization giả định tái đầu tư với lợi suất tương tự","body":"","html":"<p>Curriculum lưu ý rằng annualize lợi nhuận ngắn hạn ngầm giả định rằng suất sinh lời có thể tái lập theo các kỳ tương tự. Một tuần tăng mạnh không bảo đảm những tuần còn lại cũng tăng tương đương. Con số annualized để <em>so sánh quy ước</em>, không phải dự báo chắc chắn cho năm kế tiếp.</p><p>Với chuỗi nhiều kỳ lãi/lỗ thực tế khác nhau, hãy tính tổng gross return bằng phép nhân theo thời gian, không lặp lại một lợi nhuận đơn kỳ đã xảy ra rồi giả định nó sẽ kéo dài mãi mà không cảnh báo.</p>","trap":""},{"heading":"5. Liên tục ghép lãi: m→∞ và hàm mũ","body":"","html":"<p>Khi tăng tần suất ghép lãi vô hạn với R<sub>s</sub> không đổi, giới hạn của (1+R<sub>s</sub>/m)<sup>mN</sup> là <span class=\"math\">e<sup>R<sub>s</sub>N</sup></span>, trong đó e≈2,71828.</p><div class=\"formula-big\">FV = PV × e<sup>r<sub>cc</sub>N</sup> ; PV = FV × e<sup>−r<sub>cc</sub>N</sup></div><p>Các tỷ lệ <b>simple/nominal quoted</b>, <b>effective annual</b> và <b>continuously compounded (log)</b> có mối liên hệ chặt nhưng không cùng con số: nếu r<sub>cc</sub> là suất liên tục <em>một năm</em>, EAR = e<sup>r<sub>cc</sub></sup>−1; r<sub>cc</sub> = ln(1+EAR).</p>","trap":""},{"heading":"6. Log return: từ gross price relative đến liên tục","body":"","html":"<div class=\"formula-big\">r<sub>cc</sub> = ln(P₁/P₀) = ln(1+HPR) ; HPR=e<sup>r<sub>cc</sub></sup>−1</div><p>Điều kiện sử dụng <span class=\"math\">ln(P₁/P₀)</span>: đang xét <strong>price return không có dòng phân phối</strong> hoặc dùng chỉ số <em>total return</em> đã điều chỉnh đầy đủ. Nếu nhận dividend chưa đưa vào P, dùng P1/P0 sẽ bỏ sót income; phải xác định đúng gross return trước khi lấy ln.</p><p>Nếu HPR=+12%, log return = ln(1,12)≈11,333%, nhỏ hơn HPR tương ứng. Nếu r<sub>cc</sub>=8%/năm, HPR hiệu dụng một năm = e<sup>0,08</sup>−1≈8,329%.</p>","trap":""},{"heading":"7. Tính cộng của log return qua nhiều kỳ","body":"","html":"<p>Vì ln(a×b)=ln a+ln b, log return của từng kỳ có tính <strong>cộng</strong> trên cùng chuỗi liên tục: r<sub>cc,0,T</sub>=r<sub>cc,0,1</sub>+…+r<sub>cc,T−1,T</sub>. Điều này không có nghĩa arithmetic HPR trở thành additive: các HPR thông thường vẫn phải liên kết gross factors bằng phép nhân.</p><p>Ví dụ hai kỳ liên tục log +5% và −2% =&gt; tổng log=+3%, HPR tổng=e<sup>0,03</sup>−1≈3,045%. Chú ý ngược lại từ log về HPR phải qua hàm mũ, không chỉ “cộng 3%” như lợi nhuận thông thường.</p>","trap":""}],"formulas":[{"name":"1. Annualized return giúp so sánh những kỳ không cùng độ dài","expr":"R annual = (1+R period ) c −1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Stated annual rate, periodic interest và số kỳ tính lãi","expr":"FV = PV × (1+R s /m) mN ; PV = FV/(1+R s /m) mN","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. Liên tục ghép lãi: m→∞ và hàm mũ","expr":"FV = PV × e r cc N ; PV = FV × e −r cc N","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Log return: từ gross price relative đến liên tục","expr":"r cc = ln(P₁/P₀) = ln(1+HPR) ; HPR=e r cc −1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · Lợi nhuận hai tháng","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · Lợi nhuận hai tháng</div><div class=\"body\"><p><b>Đề:</b> Một trái phiếu có HPR 2,5% trong đúng hai tháng. Tính annualized return theo compounding.</p><ol><li>c=12/2=6.</li><li>Rannual=(1,025)^6−1=0,1596934.</li><li>Giải thích: giả định mức sinh lời hai tháng lặp lại 6 kỳ trong năm.</li></ol><p class=\"answer\">Kết quả: 15,969%/năm (annualized, không phải dự báo)</p><small>Nhóm kiến thức: intro</small></div>"},{"question_en":"E02 · Khoản giữ 18 tháng","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · Khoản giữ 18 tháng</div><div class=\"body\"><p><b>Đề:</b> Một chứng chỉ quỹ tăng tổng cộng 16% trong 18 tháng.</p><ol><li>c=12/18=2/3.</li><li>Rannual=(1,16)^(2/3)−1≈0,104007.</li><li>Không lấy 16%/1,5 như annualized compounded return.</li></ol><p class=\"answer\">Kết quả: 10,401%/năm</p><small>Nhóm kiến thức: convert</small></div>"},{"question_en":"E03 · Từ return năm về return tháng","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Từ return năm về return tháng</div><div class=\"body\"><p><b>Đề:</b> Một tỷ lệ hiệu dụng năm 12%. Tính suất hiệu dụng tháng tương đương.</p><ol><li>Rmonth=(1,12)^(1/12)−1≈0,009488793.</li><li>Kiểm tra: (1+Rmonth)^12−1=12%.</li></ol><p class=\"answer\">Kết quả: 0,949%/tháng</p><small>Nhóm kiến thức: convert</small></div>"},{"question_en":"E04 · PV ghép lãi 12 lần/năm","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · PV ghép lãi 12 lần/năm</div><div class=\"body\"><p><b>Đề:</b> Cần 3 triệu USD sau 7 năm; lãi niêm yết 4,8%/năm, ghép lãi hàng tháng.</p><ol><li>Periodic rate=4,8%/12=0,4%/tháng.</li><li>Tổng kỳ=7×12=84.</li><li>PV=3.000.000/(1,004)^84≈2.145.306,65 USD.</li></ol><p class=\"answer\">Kết quả: PV≈2.145.306,65 USD</p><small>Nhóm kiến thức: periodic</small></div>"},{"question_en":"E05 · Quoted rate khác EAR","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Quoted rate khác EAR</div><div class=\"body\"><p><b>Đề:</b> Khoản tiền gửi có quoted annual rate 6%, ghép lãi mỗi quý.</p><ol><li>Quarterly rate=0,06/4=1,5%.</li><li>EAR=(1,015)^4−1≈0,06136355.</li></ol><p class=\"answer\">Kết quả: EAR≈6,136%</p><small>Nhóm kiến thức: periodic</small></div>"},{"question_en":"E06 · Đổi HPR sang log return","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Đổi HPR sang log return</div><div class=\"body\"><p><b>Đề:</b> Giá tài sản tăng từ 200 lên 224, không có cổ tức.</p><ol><li>HPR=224/200−1=12%.</li><li>rcc=ln(224/200)=ln(1,12)≈0,1133287.</li></ol><p class=\"answer\">Kết quả: Log return≈11,333%</p><small>Nhóm kiến thức: log</small></div>"},{"question_en":"E07 · Đổi liên tục sang hiệu dụng","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · Đổi liên tục sang hiệu dụng</div><div class=\"body\"><p><b>Đề:</b> Lãi suất ghép liên tục 8% cho một năm.</p><ol><li>R_eff=exp(0,08)−1≈0,0832871.</li><li>So với nominal 8%, effective cao hơn do compounding.</li></ol><p class=\"answer\">Kết quả: EAR≈8,329%</p><small>Nhóm kiến thức: continuous</small></div>"},{"question_en":"E08 · Cộng log returns","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Cộng log returns</div><div class=\"body\"><p><b>Đề:</b> Hai kỳ có log returns +5% và −2%, không có external cash flows.</p><ol><li>Tổng log return=0,05−0,02=0,03.</li><li>Tổng HPR=exp(0,03)−1≈0,03045453.</li></ol><p class=\"answer\">Kết quả: HPR tổng≈3,045%</p><small>Nhóm kiến thức: log-add</small></div>"},{"question_en":"E09 · Quy ước ngày 365","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Quy ước ngày 365</div><div class=\"body\"><p><b>Đề:</b> Một khoản đầu tư sinh lời 0,15% trong 10 ngày, theo 365 calendar days/year.</p><ol><li>Rannual=(1,0015)^(365/10)−1≈0,056233.</li><li>Quy ước 365 là giả định; đề khác có thể dùng chuẩn ngày khác.</li></ol><p class=\"answer\">Kết quả: Annualized≈5,623%</p><small>Nhóm kiến thức: convert</small></div>"}],"questions":[{"stem_en":"A two-month holding-period return is +2.5%. Its annualized compound return is closest to:","options":["5.00%","15.97%","30.00%"],"correct":1,"why_vi":"(1,025)^6−1≈15,969%.","trap_vi":""},{"stem_en":"An investment earns +16% over 18 months. Its annualized compound return is closest to:","options":["10.40%","16.00%","12.00%"],"correct":0,"why_vi":"(1,16)^(12/18)−1≈10,401%.","trap_vi":""},{"stem_en":"An effective annual return of 12% corresponds to which effective monthly rate?","options":["Exactly 1.00%","Approximately 0.95%","12.00%"],"correct":1,"why_vi":"(1,12)^(1/12)−1≈0,9489%.","trap_vi":""},{"stem_en":"A quoted annual rate of 6% is compounded quarterly. What is its effective annual rate?","options":["6.00%","6.50%","6.136%"],"correct":2,"why_vi":"(1+0,06/4)^4−1≈6,136%.","trap_vi":""},{"stem_en":"In PV = FV(1 + Rs/m)^(−mN), what does m denote?","options":["Number of compounding periods per year","Number of years","Inflation rate"],"correct":0,"why_vi":"m=compounding frequency/year; tổng kỳ là mN.","trap_vi":""},{"stem_en":"For a positive quoted annual interest rate held constant, increasing compounding frequency generally causes the effective annual rate to:","options":["Decrease","Rise toward its continuous-compounding limit","Remain unchanged"],"correct":1,"why_vi":"Số kỳ tính lãi nhiều hơn nâng hiệu dụng, giới hạn m→∞.","trap_vi":""},{"stem_en":"A weekly effective return is 0.2%. Using 52 weeks, the annualized compound return is closest to:","options":["10.40%","10.95%","0.20%"],"correct":1,"why_vi":"(1,002)^52−1≈10,95%.","trap_vi":""},{"stem_en":"To annualize a 100-day holding-period return under a 365-day convention, the exponent on its gross return factor is:","options":["100/365","365/100","12"],"correct":1,"why_vi":"c=365/100 cho HPR 100 ngày.","trap_vi":""},{"stem_en":"What is the continuously compounded (log) return corresponding to a +12% holding-period return?","options":["ln(1.12)","e^0.12 − 1","Exactly 12%"],"correct":0,"why_vi":"ln(1+0,12)≈11,333%; giá dương không có dividend.","trap_vi":""},{"stem_en":"A continuously compounded annual return of 8% implies which effective annual return?","options":["8.000%","7.700%","8.329%"],"correct":2,"why_vi":"e^0,08−1≈8,329%.","trap_vi":""},{"stem_en":"Two consecutive continuously compounded returns are +5% and −2%. Their aggregate log return is:","options":["+3%","+3.05%","−10%"],"correct":0,"why_vi":"Log returns cộng đại số =0,05−0,02=0,03.","trap_vi":""},{"stem_en":"Two continuously compounded returns sum to 3%. The corresponding ordinary holding-period return is:","options":["Exactly 3%","e^0.03 − 1, approximately 3.045%","e^(−0.03) − 1"],"correct":1,"why_vi":"Phải chuyển ngược từ log sang ordinary return qua exp.","trap_vi":""},{"stem_en":"A stock pays a substantial dividend, but only its beginning and ending prices are known. What does ln(P1/P0) measure?","options":["Always the log total return","Not necessarily the log total return, because the dividend is omitted","It is impossible to compute any price return"],"correct":1,"why_vi":"Cần gross total-return factor có bao gồm cổ tức nếu muốn đo total return.","trap_vi":""},{"stem_en":"Why may annualizing a single week with a +5% return be misleading as a forecast?","options":["Annualization guarantees the following year's return","Only missing dividends can cause an error","It implicitly extrapolates an unusually strong weekly performance"],"correct":2,"why_vi":"Annualization chuẩn hóa số đo, giả định repeated reinvestment có thể không thực tế.","trap_vi":""},{"stem_en":"How is an effective annual return converted to an equivalent effective weekly rate using 52 weeks?","options":["(1+Rannual)^(1/52) − 1","Rannual × 52","(1+Rannual)^52 − 1"],"correct":0,"why_vi":"Weekly exponent là 1/52, không phải 52.","trap_vi":""},{"stem_en":"A problem specifies a 365-calendar-day convention. Which annualization count must NOT be substituted without justification?","options":["365","250 trading days","365/10 for a 10-day holding period"],"correct":1,"why_vi":"Theo đề phải 365 calendar days, 250 chỉ phù hợp nếu quy ước trading days được nêu.","trap_vi":""}],"cards":[{"front_en":"Annualize 2-month HPR?","back_vi":"(1+HPR)^(12/2)−1, giả định các kỳ tương đương."},{"front_en":"Annualize 18-month HPR?","back_vi":"(1+HPR)^(12/18)−1."},{"front_en":"Từ annual về monthly?","back_vi":"(1+Rannual)^(1/12)−1."},{"front_en":"Quoted Rs và periodic rate?","back_vi":"Periodic rate=Rs/m; tổng số kỳ=mN."},{"front_en":"EAR từ nominal quoted?","back_vi":"(1+Rs/m)^m−1."},{"front_en":"PV với m compounding?","back_vi":"FV/(1+Rs/m)^(mN)."},{"front_en":"FV continuous compounding?","back_vi":"PV×exp(rN)."},{"front_en":"Log return từ HPR?","back_vi":"ln(1+HPR)."},{"front_en":"HPR từ log return?","back_vi":"exp(rcc)−1."},{"front_en":"Log returns có cộng được không?","back_vi":"Có, nếu cùng chuỗi thời gian, với gross price relatives phù hợp."},{"front_en":"Nếu có dividend, ln(P1/P0) có đủ total return?","back_vi":"Không nếu dividend chưa phản ánh trong P1; dùng gross total return factor."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn đã đối chiếu CFAI2026 — CFA Institute Curriculum 2026, Quantitative Methods, PDF trang 37–41 (Annualized Return và continuously compounded returns). KAPLAN2026 — Kaplan SchweserNotes 2026 Book 1, PDF trang 22–24, Module 1.3 (LOS 1.d). SAPP2026 — SAPP Quant 2026, PDF trang 24 (LOS 1.d chuyển sang Module 2), cùng trang 38–40 (FV/PV định kỳ và liên tục). PREREQUISITE — CFA Institute Prerequisite Quant 2024, Time Value of Money — tài liệu nền tảng cho PV/FV/compounding; chỉ dùng đối chiếu khái niệm. MINDMAP — SAPP Quant Revision Mindmap, PDF trang 1 — Rates and Returns, Time Value of Money. QBANK — Question Banks Bonus 2026 Rates and Returns, PDF trang 1–16 — đối chiếu dạng bài, không tái sử dụng nguyên văn. Đã đối chiếu trong phạm vi các trang chuyên môn ghi trên, không tuyên bố kiểm kê hết mọi câu hỏi của 534 PDF hoặc được CFA Institute chứng thực. Sự khác biệt giữa các nguồn phải được ghi thành hồ sơ riêng."}],"legacy":"sourcefirst-quant-rates-los04.html"},{"id":"CFA26-01-01-LOS05","letter":"e","title_en":"Gross, Net, Real and Leveraged Returns","outcome_en":"Gross, Net, Real, After-tax and Leveraged Returns","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 1.e","body":"","html":"<p class=\"lead\">LOS 1.e — Lựa chọn và diễn giải các thước đo lợi nhuận phù hợp</p><div class=\"badgeline\"><span class=\"tag\">27 ý kiến thức đối chiếu</span><span class=\"tag\">10 ví dụ mới</span><span class=\"tag\">20 câu luyện tập</span><span class=\"tag muted\">Chỉ nghiệm thu phạm vi LOS này</span></div>","trap":""},{"heading":"1. Vì sao phải phân biệt các tỷ lệ lợi nhuận?","body":"","html":"<p>Để so sánh người quản lý quỹ với kết quả thực nhận của một nhà đầu tư, cần đặt các suất lợi nhuận về <b>cùng cơ sở</b>. Bốn điều chỉnh trọng tâm trong LOS 1.e là <b>fees, taxes, inflation, leverage</b>. Một tỷ lệ cao hơn chưa chắc làm nhà đầu tư có sức mua cuối kỳ cao hơn; chi phí, thuế, lạm phát và vốn vay đều quan trọng.</p><p>Trước khi tính, viết rõ đối tượng được đo: tài sản/quỹ hay <em>vốn tự có của nhà đầu tư</em>; chi phí nào đã hạch toán; thuế tính trên dòng nào; chu kỳ lạm phát có khớp kỳ đo lợi nhuận không.</p>","trap":""},{"heading":"2. Gross return so với Net return — quy tắc chi phí theo CFAI 2026","body":"","html":"<div class=\"formula-big\">Gross return = Return on managed assets − Trading commissions &amp; execution expenses</div><div class=\"formula-big\">Net return = Gross return − Management &amp; administrative expenses</div><p>Curriculum dùng <b>gross return</b> là lợi nhuận đã trừ các khoản <b>chi phí cần thiết để giao dịch</b>, nhưng <b>chưa trừ</b> phí quản lý, lưu ký và chi phí quản trị liên quan đến nhà đầu tư/quỹ. Khi so sánh <em>investment skill</em> của manager, gross có ích vì một số phí riêng của nhà đầu tư khác nhau. <b>Net return</b> phản ánh lợi nhuận quỹ tạo ra cho nhà đầu tư sau phí quản lý/hành chính; vẫn có thể là <b>pre-tax nominal</b> nếu chưa trừ thuế và chưa điều chỉnh lạm phát.</p><p>Các công thức trừ phần trăm trực tiếp trong ví dụ đúng khi tất cả thành phần được biểu diễn trên <b>cùng một vốn gốc và cùng kỳ</b>. Với phí thu theo AUM trung bình hoặc trong nhiều kỳ, phải căn cứ thời điểm tính phí và dòng tiền của đề, không tùy tiện cộng/trừ số phần trăm báo giá.</p>","trap":""},{"heading":"3. Pre-tax vs After-tax nominal return","body":"","html":"<p><b>Pre-tax nominal return</b> chưa trừ thuế, chưa điều chỉnh lạm phát. <b>After-tax nominal return</b> lấy lợi nhuận đầu tư trừ nghĩa vụ thuế liên quan đến <b>dividends, interest và realized gains</b> theo quy tắc của nhà đầu tư. Cổ tức, lãi trái phiếu và lãi vốn ngắn/dài hạn có thể chịu <b>thuế suất khác nhau</b> tùy luật và loại tài khoản. Khoản tăng giá chưa thực hiện thường khác khoản đã bán để hiện thực hóa; trái phiếu mua chiết khấu có thể chịu thuế trên lãi dồn tích trong một số chế độ.</p><div class=\"formula-big\">R<sub>after-tax</sub> = R<sub>pre-tax</sub> − Taxes paid (as % of invested capital)</div><p>Nếu giả định toàn bộ <b>lợi nhuận</b> 8% đã hiện thực hóa và cùng chịu thuế 25%, suất sau thuế = 8%×(1−25%)=6%. Không lấy tổng vốn gốc nhân thuế 25%; thuế thường đánh vào phần thu nhập chịu thuế, trừ khi đề nói khác. Nếu nhiều nguồn thuế suất, tính thuế riêng rồi cộng. Đây là mô hình học thuật, không phải hướng dẫn thuế của bất kỳ quốc gia nào.</p>","trap":""},{"heading":"4. Nominal vs Real: sức mua và Fisher exact","body":"","html":"<div class=\"formula-big\">1+R<sub>nominal</sub> = (1+R<sub>real</sub>)(1+π)</div><div class=\"formula-big\">R<sub>real</sub> = (1+R<sub>nominal</sub>)/(1+π) − 1</div><p>π là lạm phát <b>cùng kỳ</b>. Khi các tỷ lệ nhỏ, xấp xỉ R<sub>real</sub>≈R<sub>nominal</sub>−π; công thức chia mới là chính xác. Real return đo <b>mức tăng sức mua</b>, cho phép so sánh qua kỳ có lạm phát khác nhau; khi so các nước còn cần chú ý <b>đồng tiền của nhà đầu tư</b> và biến động tỷ giá, không đơn giản chỉ trừ lạm phát từng nước nếu lợi nhuận ở các đồng tiền khác nhau.</p><p>Ví dụ: danh mục tăng danh nghĩa 9,5%, lạm phát 3% → thực =(1,095/1,03)−1≈6,311%. Nếu nominal nhỏ hơn inflation, real return có thể âm dù danh mục sinh lời dương.</p>","trap":""},{"heading":"5. After-tax real return: đúng thứ tự điều chỉnh","body":"","html":"<div class=\"formula-big\">R<sub>real,after-tax</sub> = (1+R<sub>nominal,after-tax</sub>)/(1+π) − 1</div><p>Thứ tự chuẩn: <b>(1) tính lợi nhuận sau phí</b> nếu mục tiêu là số thực nhận, <b>(2) trừ thuế theo căn cứ chịu thuế</b>, rồi <b>(3) chia cho lạm phát</b>. Không lấy real return trước rồi giả định thuế đánh trên real return nếu đề xác định thuế trên nominal return. Mức thuế cá nhân có thể không thể xác định chỉ từ thông tin quỹ: tùy marginal tax rate, giai đoạn nắm giữ, tài khoản miễn/hoãn thuế.</p>","trap":""},{"heading":"6. Leveraged return: lợi nhuận trên vốn tự có và chi phí vay","body":"","html":"<p>Nếu nhà đầu tư sở hữu vốn E và vay B để mua tổng tài sản E+B, tài sản tạo suất sinh lời R<sub>p</sub>, nợ vay có lãi suất r<sub>D</sub>, giả sử cùng kỳ và bỏ qua các phí ngoài lãi vay:</p><div class=\"formula-big\">R<sub>L</sub> = [R<sub>p</sub>(E+B) − r<sub>D</sub>B]/E</div><div class=\"formula-big\">R<sub>L</sub> = R<sub>p</sub> + (B/E)(R<sub>p</sub>−r<sub>D</sub>)</div><p><b>B/E là debt-to-equity</b>, không phải tỷ lệ nợ trong tổng tài sản. Nếu tài sản sinh lời 10%, chi phí vay 6%, B/E=1,5 thì return trên equity = 10%+1,5×4%=16%. Nhưng nếu tài sản giảm −8%, cùng cấu trúc vốn thì R<sub>L</sub>=−8%+1,5(−8%−6%)=−29%. Đòn bẩy làm khuếch đại cả lời lẫn lỗ, có thể phát sinh margin call và bán tài sản bắt buộc.</p><p>Với future có margin chỉ bằng một phần notional, thay đổi giá trị hợp đồng / cash margin có thể gấp nhiều lần thay đổi giá tài sản cơ sở. Công thức <b>R<sub>margin</sub>≈L×R<sub>underlying</sub></b> trong trường hợp giản lược chưa tính financing cost, maintenance margin, variation margin, phí và chênh lệch giá.</p>","trap":""},{"heading":"7. Risk premium nhân chính xác và quy tắc trình bày","body":"","html":"<div class=\"formula-big\">1+R<sub>nominal risky</sub> = (1+R<sub>nominal rf</sub>)(1+RP)</div><div class=\"formula-big\">RP = (1+R<sub>risky</sub>)/(1+R<sub>rf</sub>) − 1</div><p>Với mức sinh lời tài sản rủi ro 8,5%, T-bill 3% cùng kỳ, premium theo quy ước <b>nhân</b> của CFAI/SAPP ≈ (1,085/1,03)−1=5,340%. Chênh lệch số học là 5,5 điểm %; hai kết quả là <b>quy ước khác nhau</b>, không tự thay cách tính khi đề yêu cầu công thức nhân. Cách phân rã real risk-free × inflation × risk premium cũng cần nhất quán với quy ước của từng tài liệu; Kaplan có lưu ý cách đặt risk premium trong trình bày CFAI.</p><p>Trước khi chọn đáp án, xem đề hỏi <em>spread</em> dạng chênh lệch điểm phần trăm hay <em>premium implied by compounded identity</em>; nếu không nói rõ, bám đúng định nghĩa/công thức được yêu cầu trong bài.</p>","trap":""}],"formulas":[{"name":"2. Gross return so với Net return — quy tắc chi phí theo CFAI 2026","expr":"Gross return = Return on managed assets − Trading commissions & execution expenses","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"2. Gross return so với Net return — quy tắc chi phí theo CFAI 2026","expr":"Net return = Gross return − Management & administrative expenses","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Pre-tax vs After-tax nominal return","expr":"R after-tax = R pre-tax − Taxes paid (as % of invested capital)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. Nominal vs Real: sức mua và Fisher exact","expr":"1+R nominal = (1+R real )(1+π)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. Nominal vs Real: sức mua và Fisher exact","expr":"R real = (1+R nominal )/(1+π) − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. After-tax real return: đúng thứ tự điều chỉnh","expr":"R real,after-tax = (1+R nominal,after-tax )/(1+π) − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Leveraged return: lợi nhuận trên vốn tự có và chi phí vay","expr":"R L = [R p (E+B) − r D B]/E","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Leveraged return: lợi nhuận trên vốn tự có và chi phí vay","expr":"R L = R p + (B/E)(R p −r D )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Risk premium nhân chính xác và quy tắc trình bày","expr":"1+R nominal risky = (1+R nominal rf )(1+RP)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Risk premium nhân chính xác và quy tắc trình bày","expr":"RP = (1+R risky )/(1+R rf ) − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · Gross vs net với cùng kỳ","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · Gross vs net với cùng kỳ</div><div class=\"body\"><p><b>Đề:</b> Danh mục 2.000.000 USD tăng 12% trước commission. Trading commission chiếm 0,4% vốn đầu kỳ; management fee 1,1%, administration 0,3%. Tính gross và net theo giả định mọi phí cùng vốn gốc.</p><ol><li>Gross=12%−0,4%=11,6%.</li><li>Net=11,6%−1,1%−0,3%=10,2%.</li><li>Dùng gross để so skill manager và net để so kết quả quỹ cho investor trước thuế.</li></ol><p class=\"answer\">Kết quả: Gross=11,60%; net=10,20%.</p><small>Nhóm kiến thức: gross-net</small></div>"},{"question_en":"E02 · Hiệu ứng phí quỹ theo vốn","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · Hiệu ứng phí quỹ theo vốn</div><div class=\"body\"><p><b>Đề:</b> Một quỹ có phí hành chính cố định 240.000 USD/năm và AUM đầu năm 12.000.000 USD. Cùng base, phí tương ứng bao nhiêu %?</p><ol><li>Fee%=240.000/12.000.000=0,02.</li><li>Đổi ra tỷ lệ=2,0%.</li><li>Nếu AUM gấp đôi và fixed fees không đổi, chi phí tương đương 1,0%.</li></ol><p class=\"answer\">Kết quả: 2,00% AUM; quỹ lớn hơn có fee burden thấp hơn khi fixed costs không đổi.</p><small>Nhóm kiến thức: gross-net</small></div>"},{"question_en":"E03 · Thuế 1 nguồn lợi nhuận","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Thuế 1 nguồn lợi nhuận</div><div class=\"body\"><p><b>Đề:</b> Danh mục thu nhập chịu thuế 8% (đã thực hiện) trong năm và thuế suất 25% trên khoản lợi nhuận, bỏ qua các ngoại lệ.</p><ol><li>Tax charge theo % vốn gốc=8%×25%=2%.</li><li>After-tax nominal return=8%−2%=6%.</li></ol><p class=\"answer\">Kết quả: 6,00%.</p><small>Nhóm kiến thức: pretax-tax</small></div>"},{"question_en":"E04 · Thuế khác nhau cho lãi và cổ tức","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Thuế khác nhau cho lãi và cổ tức</div><div class=\"body\"><p><b>Đề:</b> Đầu tư đầu kỳ 100.000 USD: thu lãi coupon 3.000 USD (thuế 30%) và cổ tức 1.200 USD (thuế 15%); không có gain vốn.</p><ol><li>Gross income=4.200 USD, pre-tax return=4,2%.</li><li>Tax=3.000×30%+1.200×15%=1.080 USD.</li><li>After-tax income=3.120 USD.</li></ol><p class=\"answer\">Kết quả: After-tax nominal return=3,12%.</p><small>Nhóm kiến thức: pretax-tax</small></div>"},{"question_en":"E05 · Fisher exact và approximate","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Fisher exact và approximate</div><div class=\"body\"><p><b>Đề:</b> Danh mục có return danh nghĩa +9,5%, inflation +3% trong cùng kỳ.</p><ol><li>Approx real≈9,5%−3%=6,5%.</li><li>Exact real=(1,095/1,03)−1≈0,063106796.</li><li>Sai lệch≈0,1893 điểm phần trăm.</li></ol><p class=\"answer\">Kết quả: Exact real≈6,311%; approximation≈6,5%.</p><small>Nhóm kiến thức: real</small></div>"},{"question_en":"E06 · Nominal dương nhưng real âm","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Nominal dương nhưng real âm</div><div class=\"body\"><p><b>Đề:</b> Khoản tiền tăng danh nghĩa 2%, inflation 4%.</p><ol><li>Real=(1,02/1,04)−1≈−0,01923077.</li><li>Sức mua cuối kỳ thấp hơn đầu kỳ dù nominal return dương.</li></ol><p class=\"answer\">Kết quả: Real≈−1,923%.</p><small>Nhóm kiến thức: real</small></div>"},{"question_en":"E07 · After-tax real đúng thứ tự","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · After-tax real đúng thứ tự</div><div class=\"body\"><p><b>Đề:</b> Net nominal return 11% đã thực hiện, thuế 20% trên toàn bộ return, lạm phát 4%.</p><ol><li>After-tax nominal=11%×(1−20%)=8,8%.</li><li>After-tax real=1,088/1,04−1≈0,046153846.</li><li>Không tính thuế 20% trên real 11%-4% trước.</li></ol><p class=\"answer\">Kết quả: After-tax real≈4,615%.</p><small>Nhóm kiến thức: real-aftertax</small></div>"},{"question_en":"E08 · Leverage tăng return trên equity","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Leverage tăng return trên equity</div><div class=\"body\"><p><b>Đề:</b> E=4 triệu, B=6 triệu, portfolio Rp=10%, borrowing rD=6%, cùng một năm.</p><ol><li>B/E=6/4=1,5.</li><li>RL=10%+1,5×(10%−6%)=16%.</li><li>Kiểm tra tiền: tổng asset profit=1 triệu, interest=0,36 triệu, net profit=0,64 triệu; /4 triệu=16%.</li></ol><p class=\"answer\">Kết quả: RL=16,00%.</p><small>Nhóm kiến thức: leverage</small></div>"},{"question_en":"E09 · Leverage khuếch đại loss","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Leverage khuếch đại loss</div><div class=\"body\"><p><b>Đề:</b> Cùng E=4 triệu, B=6 triệu và rD=6%, portfolio giảm 8%.</p><ol><li>RL=−8%+1,5×(−8%−6%)=−29%.</li><li>Tiền: −0,8 triệu asset loss−0,36 triệu interest=−1,16 triệu; /4=−29%.</li></ol><p class=\"answer\">Kết quả: RL=−29,00%.</p><small>Nhóm kiến thức: leverage</small></div>"},{"question_en":"E10 · Risk premium compounded","steps_vi":[],"answer":"","html":"<div class=\"top\">E10 · Risk premium compounded</div><div class=\"body\"><p><b>Đề:</b> Asset risky có nominal return 8,5%; nominal risk-free return 3%, cùng kỳ.</p><ol><li>Theo gross factor: RP=(1,085/1,03)−1.</li><li>RP≈0,053398058.</li><li>Chênh lệch số học 8,5%−3,0%=5,5 điểm %; không cùng công thức.</li></ol><p class=\"answer\">Kết quả: Compounded RP≈5,340%; simple spread=5,5 điểm phần trăm.</p><small>Nhóm kiến thức: risk-premium</small></div>"}],"questions":[{"stem_en":"Under the CFA 2026 convention, which cost is already deducted when reporting gross investment return?","options":["Annual management fee","Trading commission and execution expenses","Investor's capital gains tax"],"correct":1,"why_vi":"Gross đã trừ trading commission/execution expenses, chưa trừ phí quản lý. CFAI PDF p41.","trap_vi":""},{"stem_en":"Gross return is 10%; management and administrative fees are 1% and 0.4%, respectively, each assessed on beginning capital. What is net return?","options":["8.6%","9.4%","10.0%"],"correct":0,"why_vi":"Gross đã trừ trading costs; khi management và admin đều trên cùng vốn gốc, net =10%−1%−0,4%=8,6%.","trap_vi":""},{"stem_en":"Why might gross return be useful when comparing investment managers?","options":["It helps compare investment skill before investor-specific management fees","It already excludes every tax","It is necessarily equal to real return"],"correct":0,"why_vi":"Gross tách các phí riêng của investors, cho phép so investment management skill.","trap_vi":""},{"stem_en":"A net return stated before adjustments for inflation and income tax is best described as:","options":["After-tax real return","Pre-tax nominal return","Real risk-free return"],"correct":1,"why_vi":"Net sau chi phí quản lý vẫn có thể là pre-tax nominal.","trap_vi":""},{"stem_en":"If an investment's gain is 8% and a 25% tax applies to that gain, its after-tax nominal return is:","options":["6%","8%","2%"],"correct":0,"why_vi":"Thuế 2 điểm % trên return 8%; after-tax =8%×0,75=6%.","trap_vi":""},{"stem_en":"An investor receives USD 3,000 of interest taxed at 30% and USD 1,200 of dividends taxed at 15%. Total tax is:","options":["USD 1,260","USD 1,080","USD 900"],"correct":1,"why_vi":"Áp dụng thuế riêng cho từng loại thu nhập: 3.000×30%=900 và 1.200×15%=180; tổng thuế 1.080 USD.","trap_vi":""},{"stem_en":"Which item is NOT automatically taxed at the same time and in the same way as a realized capital gain?","options":["An unrealized gain","A dividend already received","A coupon already received"],"correct":0,"why_vi":"Các quy định tax có thể phân biệt realized gains, unrealized gains và accrual.","trap_vi":""},{"stem_en":"An investment earns a 9.5% nominal return while inflation is 3%. The exact real return is closest to:","options":["6.50%","6.311%","12.50%"],"correct":1,"why_vi":"Real exact dựa trên tỷ số gross nominal và gross inflation: (1,095/1,03)−1≈6,311%, khác xấp xỉ 6,5%.","trap_vi":""},{"stem_en":"A nominal return of +2% accompanies inflation of +4%. The exact real return is closest to:","options":["+2.0%","Exactly −2.0%","−1.923%"],"correct":2,"why_vi":"Mức tăng giá hàng hóa vượt lợi suất danh nghĩa; dùng Fisher exact (1,02/1,04)−1≈−1,923% sức mua.","trap_vi":""},{"stem_en":"When nominal return and inflation are substantial, which expression is most appropriate for exact real return?","options":["(1+nominal)/(1+inflation) − 1","Nominal minus inflation is always exact","Nominal times inflation"],"correct":0,"why_vi":"Fisher exact chia hai gross factors; hiệu số là approximation.","trap_vi":""},{"stem_en":"If pretax nominal return is +11%, gains are taxed at 20%, and inflation is 4%, what is after-tax real return?","options":["4.615%","7.000%","8.800%"],"correct":0,"why_vi":"After-tax nominal=8,8%; 1,088/1,04−1≈4,615%.","trap_vi":""},{"stem_en":"Which factors can cause after-tax real returns to differ across investors holding the same asset?","options":["Tax rates, holding periods, and account types","Different compounding within the same fund is inevitable","The risk-free rate is always zero"],"correct":0,"why_vi":"Curriculum nêu tax varies with investor rates, duration, account type.","trap_vi":""},{"stem_en":"An investor contributes equity of USD 4 million and borrows USD 6 million. The debt-to-equity ratio is:","options":["60%","1.5","0.67"],"correct":1,"why_vi":"Cần phân biệt tỷ số: debt-to-equity B/E=6/4=1,5, trong khi tỷ lệ nợ trên tổng vốn B/(B+E)=6/10=60%.","trap_vi":""},{"stem_en":"An investor earns 10% on assets financed with debt carrying a 6% cost and a debt-to-equity ratio of 1.5. Ignoring other costs, the return on equity is:","options":["10%","16%","6%"],"correct":1,"why_vi":"Sử dụng return trên equity sau lãi vay: RL=Rp+(B/E)(Rp−rD)=10%+1,5×4%=16%; không phải 10% của tài sản.","trap_vi":""},{"stem_en":"An asset loses 8%; borrowing costs 6%; and the debt-to-equity ratio is 1.5. The leveraged return on equity is:","options":["−8%","−20%","−29%"],"correct":2,"why_vi":"Chi phí vay vẫn phải thanh toán khi tài sản lỗ: RL=−8%+1,5×(−8%−6%)=−29%, mức thua lỗ khuếch đại.","trap_vi":""},{"stem_en":"Under which condition can leverage reduce return on equity below the underlying asset return?","options":["Return on assets is below the borrowing rate","Return on assets exceeds the borrowing rate","No borrowing is used"],"correct":0,"why_vi":"Theo RL=Rp+(B/E)(Rp−rD), khi borrowing cost cao hơn asset return thì phần điều chỉnh mang dấu âm, làm giảm lợi nhuận vốn chủ.","trap_vi":""},{"stem_en":"A futures position requires a 10% margin relative to its notional value. Ignoring costs and interest, a 1% favorable move in the underlying implies what approximate return on initial margin?","options":["0.1%","1%","10%"],"correct":2,"why_vi":"Leverage notional/margin=10, return on posted margin ~1%×10=10%.","trap_vi":""},{"stem_en":"Using the compounded premium relationship, a risky return is 8.5% and the risk-free return is 3%. What is the implied risk premium?","options":["5.500%","5.340%","3.000%"],"correct":1,"why_vi":"1,085/1,03−1≈5,340%. 5,5pp là arithmetic difference.","trap_vi":""},{"stem_en":"Which factor converts a nominal gross return into an exact inflation-adjusted gross return?","options":["1 − inflation","1/(1+inflation)","1 + inflation"],"correct":1,"why_vi":"Gross nominal factor chia gross inflation factor.","trap_vi":""},{"stem_en":"A 1% management fee is assessed on average annual assets under management rather than beginning-of-year assets. What is required to calculate the net return accurately?","options":["Always deduct exactly 1 percentage point from beginning-capital return","Check the fee base, timing, and accrual convention","Ignore the management fee"],"correct":1,"why_vi":"Phải đồng bộ đơn vị phí và return; phép trừ trực tiếp chỉ đúng khi cùng cơ sở và cùng kỳ.","trap_vi":""}],"cards":[{"front_en":"Gross return trong CFAI trừ chi phí nào?","back_vi":"Trừ commission/trading execution, nhưng chưa trừ management/admin và personal tax."},{"front_en":"Net return là gì?","back_vi":"Gross sau khi trừ managerial và administrative expenses theo quy ước của cùng kỳ."},{"front_en":"Net = after-tax real?","back_vi":"Không. Net của quỹ vẫn có thể pre-tax nominal."},{"front_en":"Pre-tax vs after-tax nominal?","back_vi":"After-tax trừ tax trên dividends, interest, realized gains theo luật và tình huống của investor."},{"front_en":"Thuế trên unrealized gain?","back_vi":"Không tự giả định giống realized gain; tax rules và accrual (discount bond) có ngoại lệ."},{"front_en":"Fisher exact real return?","back_vi":"(1+Rnominal)/(1+inflation)−1."},{"front_en":"Approximation của real return?","back_vi":"Rnominal−inflation, không exact nếu tỷ lệ lớn."},{"front_en":"After-tax real sequence?","back_vi":"Sau phí (nếu net) → sau thuế → chia gross inflation factor."},{"front_en":"Leverage return công thức đầy đủ?","back_vi":"RL=[Rp(E+B)−rD×B]/E = Rp+(B/E)(Rp−rD)."},{"front_en":"B/E khác gì B/(E+B)?","back_vi":"B/E là debt-to-equity; B/(E+B) là debt share of assets."},{"front_en":"Khi Rp<rD, leverage tác động?","back_vi":"Giảm return trên equity so với return của asset."},{"front_en":"Compounded risk premium?","back_vi":"(1+Rrisky)/(1+Rrf)−1 (khác arithmetic spread)."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn đã đối chiếu CFAI2026 — CFA Institute Curriculum 2026, Quantitative Methods, PDF trang 41–45, LOS 1.e (gross/net; after-tax; real; leveraged return; risk premiums). KAPLAN2026 — Kaplan SchweserNotes 2026 Book 1, PDF trang 24–26, Learning Module 1.3, LOS 1.e; có chú giải khác biệt cách đặt risk premium. SAPP2026 — SAPP Quant 2026, PDF trang 25–28, LOS 1.e và các ví dụ real return, risk premium. PREREQUISITE — Prerequisite Reading 2024 Quant, khái niệm về tỷ lệ, suất sinh lời và lãi suất (nguồn nền; không dùng thay quy ước 2026). MINDMAP — Mindmap Revision Quant, mục Rates and Returns — kiểm tra hệ thống thuật ngữ. QBANK — Question Banks và Mock Exam nhiều nguồn đã kiểm kê; dùng kiểm tra dạng câu hỏi, không sao chép nội dung đề gốc hay tuyên bố duyệt hết 489 tệp. Đã đối chiếu trong phạm vi các trang chuyên môn ghi trên, không tuyên bố kiểm kê hết mọi câu hỏi của 534 PDF hoặc được CFA Institute chứng thực. Sự khác biệt giữa các nguồn phải được ghi thành hồ sơ riêng."}],"legacy":"sourcefirst-quant-rates-los05.html"}],"disclaimer_vi":"Giữ nguyên học liệu gốc; xem nguồn đối chiếu trong từng bài."},{"module_id":"CFA26-01-02","module_title":"Time Value of Money in Finance","los":[{"id":"CFA26-01-02-LOS01","letter":"a","title_en":"Present Value of Fixed-Income and Equity","outcome_en":"Present Value of Fixed-Income and Equity Instruments","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 2.a","body":"","html":"<p class=\"lead\">LOS 2.a — Discount Bonds, Coupon Bonds, Annuities &amp; Dividend Discount Models</p><div class=\"badgeline\"><span class=\"tag\">41 ý kiến thức đối chiếu</span><span class=\"tag\">15 ví dụ mới</span><span class=\"tag\">30 câu luyện tập</span><span class=\"tag muted\">Chỉ nghiệm thu phạm vi LOS này</span></div>","trap":""},{"heading":"1. Mục tiêu LOS 2.a — Present Value của fixed income và equity","body":"","html":"<p>CFA Institute 2026 yêu cầu <b>calculate and interpret the present value (PV) of fixed-income AND equity instruments based on expected future cash flows</b>. Với bất kỳ tài sản nào, giá trị hôm nay bằng <em>giá trị hiện tại của các dòng tiền kỳ vọng</em>, chiết khấu theo thời điểm nhận và suất sinh lời yêu cầu.</p><div class=\"formula-big\">PV = Σ<sub>t=1…T</sub> CF<sub>t</sub>/(1+r)<sup>t</sup></div><p>Trái phiếu có contractual interest/principal, còn cổ phiếu có cổ tức không bảo đảm. Chỉ đưa các dòng tiền phù hợp vào mô hình: principal khi đáo hạn, coupon theo kỳ, dividend theo chính sách và dự báo. <b>r</b> phải khớp rủi ro, kỳ hạn và tần suất của CF. Giá trị tính toán không đồng nghĩa chắc chắn với giá thị trường khi dự báo khác kỳ vọng.</p><div class=\"note\"><b>Khác nhãn SAPP:</b> Slide SAPP gọi PV của trái phiếu là LOS 2.a và PV cổ phiếu là 2.b, trong khi CFA Institute Curriculum 2026 gộp cả hai trong LOS 2.a. Do đó bài này có đủ hai phần; phần implied required return/growth được dành cho LOS 2.b của Curriculum.</div>","trap":""},{"heading":"2. Discounting: một dòng tiền và ghép lãi liên tục","body":"","html":"<p>Một khoản tiền FV ở thời điểm t có giá trị hiện tại <b>FV/(1+r)<sup>t</sup></b> khi suất chiết khấu r áp dụng mỗi kỳ. Nếu r cao hơn (các yếu tố khác giữ nguyên), PV thấp hơn; khi t dài hơn, PV của FV cố định cũng thấp hơn với r dương. Với continuous compounding theo r<sub>cc</sub> một kỳ, <b>PV=FV×e<sup>−r<sub>cc</sub>t</sup></b>.</p><p><b>Thời điểm dòng tiền:</b> Khoản tiền ở t=0 chưa cần discount; khoản cuối kỳ t=1 dùng một kỳ. Với nhiều khoản ở nhiều thời điểm, định giá từng khoản rồi cộng. Lãi suất niêm yết năm, trả coupon mỗi 6 tháng thì chuyển sang <b>r<sub>period</sub>=YTM/2</b> và N=2×số năm nếu quoted YTM ghép lãi nửa năm như quy ước trong ví dụ.</p>","trap":""},{"heading":"3. Zero-coupon / discount bond: một khoản principal tại maturity","body":"","html":"<div class=\"formula-big\">P<sub>0</sub> = FV/(1+r)<sup>N</sup></div><p>Zero-coupon không có coupon trung gian; nhà đầu tư mua theo PV và thu FV đáo hạn. Với <b>r&gt;0</b> và FV cố định, P0 thấp hơn FV; với <b>−1&lt;r&lt;0</b>, P0 cao hơn FV. Khi lãi suất tăng, giá giảm; khi còn ít kỳ đến maturity và r không đổi, giá hội tụ về FV — discount bond accretes upward, còn premium discount bond (negative yield) có thể amortize xuống FV.</p><p>Đặc biệt, khi tính <b>giá sau 3 năm</b> cho trái phiếu ban đầu còn 12 năm, đưa <b>N=9</b> năm còn lại, không dùng N=12. Khi đề cho giá và hỏi YTM hàm ý, đó là LOS 2.b, nhưng việc phân biệt PV và yield giúp kiểm tra chiều tác động ở LOS này.</p>","trap":""},{"heading":"4. Coupon bond: chiết khấu coupon và principal riêng","body":"","html":"<div class=\"formula-big\">P<sub>0</sub> = Σ<sub>i=1…N</sub> C/(1+r)<sup>i</sup> + FV/(1+r)<sup>N</sup></div><div class=\"formula-big\">P<sub>0</sub> = C[1−(1+r)<sup>−N</sup>]/r + FV/(1+r)<sup>N</sup></div><p>Với fixed-rate coupon bond, <b>C=FV×annual coupon rate/m</b>, r là <b>annual YTM/m</b>, N=m×years (nếu YTM theo kỳ m lần/năm). Tính coupon rate trên <b>face/par value</b>, còn discount rate là <b>market yield/YTM</b> — hai tỷ lệ không phải một.</p><p>Ở ngày coupon: nếu coupon rate = YTM (và cùng ghép lãi), giá ≈ par; coupon rate &gt; YTM → premium; coupon rate &lt; YTM → discount. Khi YTM tăng (giữ CF và thời gian), bond price giảm. Ở một số ngày giữa hai kỳ coupon, có clean/dirty price và accrued interest; phạm vi hiện ở ngày định giá trùng coupon, còn quy ước giữa coupon sẽ được đào sâu tại Fixed Income.</p>","trap":""},{"heading":"5. Semiannual coupons, maturity và việc tránh sai kỳ","body":"","html":"<p>Ví dụ trái phiếu par 1.000, coupon 6%/năm, coupon trả 2 lần/năm, YTM niêm yết 8%/năm, còn 4 năm:</p><p><b>C=1.000×6%/2=30</b> mỗi nửa năm, <b>r=8%/2=4%</b> mỗi kỳ, <b>N=4×2=8</b>. Giá là 30×[1−(1,04)<sup>−8</sup>]/0,04 + 1.000/(1,04)<sup>8</sup>. Không dùng coupon 60 với r=4% hay N=4 vì sẽ trộn đơn vị.</p><p>Thay đổi YTM có thể làm giá trái phiếu coupon tăng/giảm; nếu coupon rate bằng YTM trên coupon date thì về par. Khi số coupon kỳ t còn lại thay đổi, phải thay N tương ứng, và với bond option embedded có thể cần kỹ thuật khác ngoài mô hình fixed cash flow giản lược.</p>","trap":""},{"heading":"6. Perpetual bonds: dòng coupon vô hạn","body":"","html":"<div class=\"formula-big\">PV<sub>perpetuity</sub> = C/r</div><p>Nếu trái phiếu vĩnh viễn trả coupon cố định C vào <b>cuối mỗi kỳ</b> mãi mãi, không có principal payoff cố định ở maturity và r&gt;0, chuỗi hình học hội tụ thành C/r. Một trái phiếu callable/perpetual có redemption provisions có thể không thể coi là perpetuity chắc chắn; đề phải cho giả định không exercise quyền chọn hoặc giả định dòng tiền cố định vĩnh viễn.</p><p>Ví dụ coupon vĩnh viễn 4 đơn vị/năm, YTM yêu cầu 5%/năm → PV=80 đơn vị. Với coupon theo quý, quy đổi coupon quý và yield quý trước khi dùng C/r.</p>","trap":""},{"heading":"7. Annuity: khoản trả đều cả lãi và gốc","body":"","html":"<div class=\"formula-big\">PV = A[1−(1+r)<sup>−N</sup>]/r</div><div class=\"formula-big\">A = PV·r/[1−(1+r)<sup>−N</sup>]</div><p>Khoản vay mortgage trả đều <b>end-of-period (ordinary annuity)</b> sẽ trả cùng số tiền A từng kỳ. Khoản trả A gồm <b>interest = outstanding principal × r</b> và <b>principal repayment = A−interest</b>. Dư nợ kỳ sau = dư nợ trước − principal repayment. Dần về cuối kỳ, interest giảm và principal share tăng nếu r cố định, payment không đổi.</p><p><b>Không nhầm coupon bond:</b> coupon bond thường trả coupon đều và gốc trả một lần khi đáo hạn; annuity instrument trả dần cả principal. Nếu annuity due (trả đầu kỳ), PV của ordinary annuity được nhân (1+r) khi cùng N, vì mỗi dòng tiền sớm hơn một kỳ. Curriculum ở đây chủ yếu dùng ordinary annuity.</p>","trap":""},{"heading":"8. Calculator BA II Plus và kiểm tra dấu dòng tiền","body":"","html":"<p>Kaplan yêu cầu quen thao tác <b>BA II Plus N, I/Y, PV, PMT, FV</b>. Để tránh máy tự hiểu lãi suất năm là lãi suất tháng, Kaplan khuyến nghị đặt <b>P/Y=1</b> (2nd P/Y → 1 → ENTER → 2nd QUIT), sau đó nhập <b>I/Y theo lãi mỗi kỳ</b> và <b>N số kỳ</b>. Khi giá PV là tiền nhà đầu tư bỏ ra (dòng ra), máy dùng dấu âm trong phương trình tiền, trong khi FV/PMT là dòng tiền vào. Đọc kết quả âm theo ý nghĩa chiều dòng tiền, không tự hiểu giá trị tài sản âm.</p><p>Khoản coupon bond: P/Y=1; N=8; I/Y=4; PMT=30; FV=1.000; CPT PV sẽ trả âm vì PMT, FV là inflows. Lấy trị tuyệt đối để trình bày bond price. <b>Đổi sang bài khác: CLR TVM</b> để tránh giá trị cũ ảnh hưởng phép tính.</p>","trap":""},{"heading":"9. Equity: dividend valuation và bản chất dòng tiền dự kiến","body":"","html":"<p>Cổ phiếu là quyền sở hữu, cổ tức <b>không phải contractual coupon</b> và có thể thay đổi hoặc không được chi. Không có maturity cố định, nên PV dựa trên chuỗi dividend kỳ vọng vô hạn khi mô hình định giá bằng cổ tức hợp lý. <b>Required return</b> của equity phản ánh rủi ro và là suất discount, không tự dùng coupon/YTM của trái phiếu.</p><p>Ba mẫu chính trong Curriculum: <b>constant dividend (no growth)</b>, <b>constant dividend growth</b> và <b>changing growth/two-stage</b>. Trong từng mẫu phải dùng <em>dividend đúng thời điểm</em>: D<sub>0</sub> là cổ tức vừa chi; D<sub>1</sub> là cổ tức dự kiến cuối kỳ tiếp theo.</p>","trap":""},{"heading":"10. Constant-dividend và Gordon Growth Model","body":"","html":"<div class=\"formula-big\">P<sub>0</sub> (constant D) = D/r</div><div class=\"formula-big\">P<sub>0</sub> (constant g) = D<sub>1</sub>/(r−g) = D<sub>0</sub>(1+g)/(r−g)</div><p>Constant D thực chất là perpetuity dividend không tăng. Gordon Growth Model giả định D tăng với g cố định mãi mãi và <b>r&gt;g</b> để tổng PV hội tụ; không dùng khi r≤g với dòng dividend tăng mãi và r là required return dương. D<sub>1</sub> mới là dividend vào cuối năm 1, nếu đề cho D<sub>0</sub> thì nhân (1+g).</p><p>Giả định r không đổi, tăng g có thể làm P0 tăng mạnh do <b>(r−g)</b> nhỏ lại. Cần đặc biệt cảnh giác việc áp dụng Gordon Growth cho doanh nghiệp tăng trưởng cao trong ngắn hạn nhưng không bền vững mãi mãi.</p>","trap":""},{"heading":"11. Changing growth / Two-stage dividend discount model","body":"","html":"<p>Giả sử dividend D<sub>0</sub> đã chi, tăng g<sub>s</sub> từ năm 1 đến năm n, sau đó tăng đều g<sub>l</sub> (long-term) từ năm n+1 đến vô hạn, với <b>r&gt;g<sub>l</sub></b>. Làm theo ba bước:</p><ol><li>Dự báo từng dividend D<sub>t</sub>=D<sub>0</sub>(1+g<sub>s</sub>)<sup>t</sup> cho t=1…n.</li><li>Giá trị terminal <b>P<sub>n</sub>=D<sub>n+1</sub>/(r−g<sub>l</sub>)</b>, trong đó <b>D<sub>n+1</sub>=D<sub>n</sub>(1+g<sub>l</sub>)</b>, đặt ở cuối năm n.</li><li>Chiết khấu P<sub>n</sub> về hôm nay rồi cộng với PV của dividends n năm đầu: <b>P<sub>0</sub>=Σ D<sub>t</sub>/(1+r)<sup>t</sup>+P<sub>n</sub>/(1+r)<sup>n</sup></b>.</li></ol><p><b>Bẫy:</b> terminal value không nằm ở năm n+1; D<sub>n+1</sub> ở đầu tử, <em>giá trị P<sub>n</sub></em> ở cuối năm n; không chiết khấu P<sub>n</sub> theo n+1. Với mô hình ba giai đoạn, tính từng giai đoạn một và dừng tăng trưởng cao khi các giả định nguồn yêu cầu.</p>","trap":""},{"heading":"12. Bảng quyết định chọn mô hình và diễn giải giá trị","body":"","html":"<table><thead><tr><th>CF được đề cho</th><th>Mô hình PV</th><th>Cảnh báo</th></tr></thead><tbody><tr><td>Principal duy nhất tại maturity</td><td>Discount/zero-coupon bond</td><td>r và số kỳ còn lại</td></tr><tr><td>Coupon kỳ + principal cuối</td><td>Coupon bond</td><td>Không nhầm coupon với YTM</td></tr><tr><td>Coupon vô hạn cố định</td><td>Perpetuity C/r</td><td>r&gt;0, xét quyền call</td></tr><tr><td>Khoản trả cuối kỳ đều và trả dần gốc</td><td>Ordinary annuity</td><td>Interest/principal split</td></tr><tr><td>Cổ tức vĩnh viễn cố định</td><td>Constant-dividend DDM</td><td>D là dòng cuối kỳ</td></tr><tr><td>Cổ tức tăng đều mãi mãi</td><td>Gordon DDM</td><td>r&gt;g, D1 vs D0</td></tr><tr><td>Giai đoạn tăng cao rồi ổn định</td><td>Two-stage DDM</td><td>Pn và Dn+1 khác thời điểm</td></tr></tbody></table><p>Việc xác định PV yêu cầu <b>dự báo cash flows và discount rate</b>. Nếu đề cho P0 rồi yêu cầu tính return/yield/growth hàm ý, chuyển sang <b>LOS 2.b</b>; nếu đề yêu cầu định giá các dòng tương đương để kiểm tra no-arbitrage, chuyển sang <b>LOS 2.c</b>.</p>","trap":""}],"formulas":[{"name":"1. Mục tiêu LOS 2.a — Present Value của fixed income và equity","expr":"PV = Σ t=1…T CF t /(1+r) t","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Zero-coupon / discount bond: một khoản principal tại maturity","expr":"P 0 = FV/(1+r) N","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. Coupon bond: chiết khấu coupon và principal riêng","expr":"P 0 = Σ i=1…N C/(1+r) i + FV/(1+r) N","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"4. Coupon bond: chiết khấu coupon và principal riêng","expr":"P 0 = C[1−(1+r) −N ]/r + FV/(1+r) N","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Perpetual bonds: dòng coupon vô hạn","expr":"PV perpetuity = C/r","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Annuity: khoản trả đều cả lãi và gốc","expr":"PV = A[1−(1+r) −N ]/r","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Annuity: khoản trả đều cả lãi và gốc","expr":"A = PV·r/[1−(1+r) −N ]","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"10. Constant-dividend và Gordon Growth Model","expr":"P 0 (constant D) = D/r","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"10. Constant-dividend và Gordon Growth Model","expr":"P 0 (constant g) = D 1 /(r−g) = D 0 (1+g)/(r−g)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · PV một khoản cuối kỳ","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · PV một khoản cuối kỳ</div><div class=\"body\"><p><b>Đề:</b> Nhận 2.500 USD sau 5 năm, discount rate 4%/năm, annual compounding.</p><ol><li>PV=2.500/(1,04)^5.</li><li>Chiết khấu 5 lần vì CF chỉ nhận tại cuối năm thứ 5.</li></ol><p class=\"answer\">Kết quả: PV≈2,054.82 USD.</p><small>Nhóm kiến thức: pvbasics</small></div>"},{"question_en":"E02 · PV continuous discount","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · PV continuous discount</div><div class=\"body\"><p><b>Đề:</b> Nhận 3.000 EUR sau 3 năm với discount rate ghép liên tục 3,5%/năm.</p><ol><li>PV=3.000×exp(−0,035×3).</li><li>Không thay exp bằng (1+0,035)^−3 nếu đề yêu cầu continuous.</li></ol><p class=\"answer\">Kết quả: PV≈2,700.97 EUR.</p><small>Nhóm kiến thức: pvbasics</small></div>"},{"question_en":"E03 · Zero-coupon bond với yield dương","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Zero-coupon bond với yield dương</div><div class=\"body\"><p><b>Đề:</b> Zero-coupon face 1.000, maturity 8 năm, YTM 4,5% annual compounding.</p><ol><li>PV=1.000/(1,045)^8.</li><li>PV&lt;face vì yield dương.</li></ol><p class=\"answer\">Kết quả: Giá≈703.19.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E04 · Zero-coupon với negative yield","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Zero-coupon với negative yield</div><div class=\"body\"><p><b>Đề:</b> Zero-coupon face 1.000, 3 năm đến đáo hạn, yield −0,4%/năm.</p><ol><li>PV=1.000/(0,996)^3.</li><li>PV&gt;face, investor chấp nhận return âm.</li></ol><p class=\"answer\">Kết quả: Giá≈1,012.10.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E05 · Thay đổi giá khi còn ít năm","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Thay đổi giá khi còn ít năm</div><div class=\"body\"><p><b>Đề:</b> Zero-coupon face 1.000, yield 5% không đổi, lúc đầu còn 6 năm; 2 năm sau còn 4 năm.</p><ol><li>Price at initial=1.000/1,05^6.</li><li>Price after 2 years=1.000/1,05^4.</li><li>Giá tăng vì kỳ chiết khấu còn lại giảm.</li></ol><p class=\"answer\">Kết quả: P0≈746.22; P2≈822.70.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E06 · Coupon bond premium","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Coupon bond premium</div><div class=\"body\"><p><b>Đề:</b> Trái phiếu face 1.000, coupon 7%/năm, trả hàng năm, còn 6 năm, YTM 5%.</p><ol><li>C=1.000×7%=70, r=5%, N=6.</li><li>PV=70×[1−1,05^−6]/0,05+1.000/1,05^6.</li><li>Coupon &gt; YTM ⇒ premium.</li></ol><p class=\"answer\">Kết quả: P≈1,101.51, cao hơn par 1.000.</p><small>Nhóm kiến thức: coupon</small></div>"},{"question_en":"E07 · Coupon bond discount","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · Coupon bond discount</div><div class=\"body\"><p><b>Đề:</b> Bond face 1.000, annual coupon 3%, còn 6 năm, market YTM 5%.</p><ol><li>C=30, r=5%, N=6.</li><li>PV=30×[1−1,05^−6]/0,05+1.000/1,05^6.</li><li>Coupon &lt; YTM ⇒ discount.</li></ol><p class=\"answer\">Kết quả: P≈898.49, thấp hơn par.</p><small>Nhóm kiến thức: coupon</small></div>"},{"question_en":"E08 · Semiannual bond","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Semiannual bond</div><div class=\"body\"><p><b>Đề:</b> Bond face 1.000, coupon 6%/năm, 4 năm, semiannual, nominal annual YTM 8% semiannual compounding.</p><ol><li>PMT=1.000×6%/2=30.</li><li>N=4×2=8, r=8%/2=4% mỗi nửa năm.</li><li>PV=30×[1−1,04^−8]/0,04+1.000/1,04^8.</li></ol><p class=\"answer\">Kết quả: P≈932.67.</p><small>Nhóm kiến thức: frequency</small></div>"},{"question_en":"E09 · Perpetual coupon","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Perpetual coupon</div><div class=\"body\"><p><b>Đề:</b> Một perpetual bond coupon cố định 2,50 USD mỗi quý; required yield 6% danh nghĩa năm, quarterly compounding.</p><ol><li>Quarterly r=6%/4=1,5%.</li><li>PV=C/r=2,5/0,015.</li></ol><p class=\"answer\">Kết quả: PV≈166.67 USD/face unit.</p><small>Nhóm kiến thức: perp</small></div>"},{"question_en":"E10 · Trả góp mortgage","steps_vi":[],"answer":"","html":"<div class=\"top\">E10 · Trả góp mortgage</div><div class=\"body\"><p><b>Đề:</b> Khoản vay 240.000 USD, lãi danh nghĩa 6%/năm, trả đều hàng tháng trong 20 năm.</p><ol><li>r=6%/12=0,5% tháng; N=240.</li><li>A=240.000×0,005/[1−1,005^−240].</li></ol><p class=\"answer\">Kết quả: A≈1,719.43 USD/tháng.</p><small>Nhóm kiến thức: annuity</small></div>"},{"question_en":"E11 · Phân rã trả nợ tháng đầu","steps_vi":[],"answer":"","html":"<div class=\"top\">E11 · Phân rã trả nợ tháng đầu</div><div class=\"body\"><p><b>Đề:</b> Dùng mortgage ở E10, tính interest, principal repayment và closing balance tháng 1.</p><ol><li>Interest tháng 1=240.000×0,5%=1.200.</li><li>Principal repayment=A−1.200.</li><li>Dư nợ mới=240.000−principal repayment.</li></ol><p class=\"answer\">Kết quả: Interest=1.200; principal≈519.43; dư nợ≈239,480.57 USD.</p><small>Nhóm kiến thức: annuity</small></div>"},{"question_en":"E12 · Equity cổ tức cố định","steps_vi":[],"answer":"","html":"<div class=\"top\">E12 · Equity cổ tức cố định</div><div class=\"body\"><p><b>Đề:</b> Preferred stock dự kiến chi 4,20 USD/cổ phiếu cuối mỗi năm vĩnh viễn, required return 7%.</p><ol><li>Mô hình fixed D perpetuity.</li><li>P0=D/r=4,20/0,07.</li></ol><p class=\"answer\">Kết quả: P0=60,00 USD/cổ phiếu.</p><small>Nhóm kiến thức: ddm</small></div>"},{"question_en":"E13 · Gordon Growth: D0 ≠ D1","steps_vi":[],"answer":"","html":"<div class=\"top\">E13 · Gordon Growth: D0 ≠ D1</div><div class=\"body\"><p><b>Đề:</b> Cổ tức vừa chi D0=2,40, tăng đều 4% vĩnh viễn; required return 10%.</p><ol><li>D1=2,40×1,04=2,496.</li><li>P0=D1/(0,10−0,04)=2,496/0,06.</li></ol><p class=\"answer\">Kết quả: P0=41,60 USD.</p><small>Nhóm kiến thức: ddm</small></div>"},{"question_en":"E14 · Two-stage growth & terminal value","steps_vi":[],"answer":"","html":"<div class=\"top\">E14 · Two-stage growth &amp; terminal value</div><div class=\"body\"><p><b>Đề:</b> Một cổ phiếu vừa chi D0=1,80; cổ tức tăng 12%/năm trong 3 năm, sau đó tăng 4% vĩnh viễn; r=10%.</p><ol><li>D1=2,016; D2=2,25792; D3=2,5288704.</li><li>D4=D3×1,04, P3=D4/(10%−4%).</li><li>P0=D1/1,10+D2/1,10²+D3/1,10³+P3/1,10³.</li></ol><p class=\"answer\">Kết quả: D4≈2.630025; P3≈43.8338; PV dividends≈5.5988; P0≈38.5317 USD.</p><small>Nhóm kiến thức: twostage</small></div>"},{"question_en":"E15 · Par bond khi coupon bằng yield","steps_vi":[],"answer":"","html":"<div class=\"top\">E15 · Par bond khi coupon bằng yield</div><div class=\"body\"><p><b>Đề:</b> Bond mặt giá 1.000, coupon 5% năm, trả hàng năm, còn 7 năm; yield 5%.</p><ol><li>C=50, yield=5%, N=7.</li><li>PV=50×[1−1,05^−7]/0,05+1.000/1,05^7.</li><li>Kết quả đúng bằng par tại coupon date.</li></ol><p class=\"answer\">Kết quả: P≈1,000.00.</p><small>Nhóm kiến thức: coupon</small></div>"}],"questions":[{"stem_en":"Under CFA Level I 2026 LOS 2.a, present-value applications include which securities?","options":["Fixed-income securities only","Both fixed-income and equity securities","Equity securities only"],"correct":1,"why_vi":"CFAI 2026 ghi rõ fixed-income AND equity; SAPP đánh nhãn các phần khác nhau.","trap_vi":""},{"stem_en":"A payment of USD 2,500 is due in five years and the annual discount rate is 4%. Its present value is closest to:","options":["USD 2,054.82","USD 2,500.00","USD 2,000.00"],"correct":0,"why_vi":"PV=2.500/1,04^5; tăng discount rate làm PV giảm khi CF giữ nguyên.","trap_vi":""},{"stem_en":"For a cash flow of USD 3,000 in three years discounted at a continuously compounded rate of 3.5%, which expression gives its present value?","options":["3,000e^(−0.035×3)","3,000(1+0.035)^3","3,000+0.035×3"],"correct":0,"why_vi":"Continuous discounting dùng nhân exp(−rN), không dùng simple accumulation.","trap_vi":""},{"stem_en":"For a zero-coupon bond with a positive yield to maturity, its current price is generally:","options":["Always equal to face value","Below face value","Above face value"],"correct":1,"why_vi":"Với yield dương, mẫu số (1+r)^N>1 nên PV<FV.","trap_vi":""},{"stem_en":"A zero-coupon bond with a USD 1,000 face value and a negative annual yield of −0.4% over three years will trade:","options":["Below USD 1,000","Exactly at USD 1,000","Above USD 1,000"],"correct":2,"why_vi":"Với yield âm (>-100%), mẫu số (1+r)^3<1 ⇒ giá lớn hơn face.","trap_vi":""},{"stem_en":"A zero-coupon bond has six years until maturity. Two years later, with the discount rate unchanged, how many years remain in its present-value calculation?","options":["6","2","4"],"correct":2,"why_vi":"Tại t=2, còn 4 năm đến maturity; chỉ discount các kỳ còn lại.","trap_vi":""},{"stem_en":"A bond has a USD 1,000 face value and pays a 7% annual coupon. Its annual cash coupon is:","options":["USD 70","USD 7","USD 1,070"],"correct":0,"why_vi":"Coupon C=face×coupon rate=1.000×7%=70; YTM chỉ dùng để chiết khấu.","trap_vi":""},{"stem_en":"A fixed-coupon bond has a 7% coupon rate and a 5% yield to maturity. On a coupon payment date, it normally trades at:","options":["A discount","A premium","Par value necessarily"],"correct":1,"why_vi":"Coupon rate lớn hơn market discount rate nên coupon stream có PV cao hơn par.","trap_vi":""},{"stem_en":"A fixed-coupon bond has a 3% coupon rate and a 5% yield to maturity. On a coupon payment date, it normally trades at:","options":["A discount","A premium","Par value"],"correct":0,"why_vi":"Coupon rate thấp hơn YTM nên P0<face.","trap_vi":""},{"stem_en":"A semiannual coupon bond has a 6% annual coupon rate, an 8% nominal annual yield, and a USD 1,000 face value. The periodic coupon and periodic yield are:","options":["USD 60 and 8%","USD 30 and 4%","USD 60 and 4%"],"correct":1,"why_vi":"Phải chia cả coupon và yield cho 2, số kỳ nhân 2.","trap_vi":""},{"stem_en":"For a four-year bond making semiannual coupon payments, the number of discounting periods is:","options":["4","2","8"],"correct":2,"why_vi":"Có 2 kỳ coupon mỗi năm; 4 năm tức 8 kỳ.","trap_vi":""},{"stem_en":"A perpetuity pays USD 2.50 each quarter and the nominal annual required return is 6%, compounded quarterly. Its present value is closest to:","options":["USD 41.67","USD 166.67","USD 100.00"],"correct":1,"why_vi":"Quarterly r=0,06/4=0,015; P=2,5/0,015=166,67.","trap_vi":""},{"stem_en":"Why is the simple perpetuity formula C/r potentially inappropriate for a callable bond?","options":["Its payments are certainly perpetual","Redemption can terminate its payments","Its yield to maturity must be zero"],"correct":1,"why_vi":"Nếu call xảy ra thì future coupons kết thúc, cần mô hình CF phù hợp.","trap_vi":""},{"stem_en":"For an amortizing loan with periodic payment A, the interest component of the first payment equals:","options":["Opening loan balance × periodic interest rate","Principal repaid in the current period × annual interest rate","The entire payment A"],"correct":0,"why_vi":"Interest tính trên opening balance; principal repayment = A−interest.","trap_vi":""},{"stem_en":"A USD 240,000 loan is repaid in 240 equal monthly payments with a monthly interest rate of 0.5%. The monthly payment is closest to:","options":["USD 1,719.43","USD 1,200.00","USD 2,400.00"],"correct":0,"why_vi":"A=PV×r/(1−(1+r)^−N), bao gồm cả interest và amortization.","trap_vi":""},{"stem_en":"On a financial calculator configured with P/Y=1, what interest rate should be entered as I/Y when cash flows occur once per period?","options":["The interest rate per cash-flow period","An annual rate in every case","The inflation rate"],"correct":0,"why_vi":"Kaplan khuyên P/Y=1 và nhập lãi mỗi kỳ vào I/Y, N là số kỳ.","trap_vi":""},{"stem_en":"When a BA II Plus TVM calculation returns a negative PV while future receipts are entered as positive, the negative sign generally indicates:","options":["The asset has negative economic value","The present cash flow is an outflow","The investment return must be negative"],"correct":1,"why_vi":"Dấu cashflow theo quan điểm nhà đầu tư; lấy trị tuyệt đối để báo bond price.","trap_vi":""},{"stem_en":"Which feature best distinguishes a conventional bond coupon from an ordinary equity dividend?","options":["Coupon payments are contractual; ordinary dividends are discretionary","Dividends are always guaranteed","Equity always has a fixed principal repayment date"],"correct":0,"why_vi":"Equity không có promised maturity and common stock dividends có thể thay đổi.","trap_vi":""},{"stem_en":"A preferred share pays a constant annual dividend of USD 4.20 and requires a 7% return. Its value under a perpetuity assumption is:","options":["USD 60.00","USD 57.14","USD 4.20"],"correct":0,"why_vi":"PV=4,20/0,07=60; perpetuity dividend bắt đầu cuối kỳ 1.","trap_vi":""},{"stem_en":"In the Gordon growth model, D0=USD 2.40, g=4%, and r=10%. The current share price is:","options":["USD 40.00","USD 41.60","USD 24.00"],"correct":1,"why_vi":"D1=D0(1+g)=2,496, P0=2,496/(0,10−0,04)=41,60.","trap_vi":""},{"stem_en":"Which restriction is required for the constant-growth dividend discount model with a positive perpetual growth rate?","options":["Required return r exceeds growth g","Growth g is at least r","Required return r equals zero"],"correct":0,"why_vi":"Khi r≤g, infinite geometric PV không hội tụ theo công thức D1/(r−g).","trap_vi":""},{"stem_en":"In a two-stage dividend discount model with high growth through Year 3, the terminal value P3 is placed:","options":["At t=0","At the end of Year 3","At the end of Year 4"],"correct":1,"why_vi":"P3 là giá trị tại cuối năm 3 của dividends từ năm 4 trở đi.","trap_vi":""},{"stem_en":"In a Gordon terminal-value formula P3=D4/(r−g), which dividend is used in the numerator?","options":["D3","D4","D0"],"correct":1,"why_vi":"P3=D4/(r−gl); D4=D3(1+gl) là dividend đầu long-term phase.","trap_vi":""},{"stem_en":"A fixed-income security pays a level coupon and repays principal at maturity. Which valuation method is appropriate?","options":["Discount the coupon stream and principal separately","Discount principal only","Use the stock formula P=D1/(r−g)"],"correct":0,"why_vi":"Dùng bond price =PV(coupon annuity)+PV(principal).","trap_vi":""},{"stem_en":"For a conventional bond priced on a coupon payment date with coupon rate equal to yield to maturity on the same basis, its price is typically:","options":["Above par","Below par","At par"],"correct":2,"why_vi":"Khi C=FV×periodic yield, tổng coupon PV và FV PV bằng face.","trap_vi":""},{"stem_en":"Compared with an ordinary annuity having the same payment, number of periods, and positive discount rate, an annuity due has:","options":["Higher present value because cash flows occur earlier","Lower present value","The same present value"],"correct":0,"why_vi":"Annuity due payments sớm hơn một kỳ nên PV_annu_due =PV_ordinary×(1+r) khi r dương.","trap_vi":""},{"stem_en":"Why should equity dividends not automatically be discounted at a comparable bond's coupon rate?","options":["Debt and equity have identical risks","Equity requires its own risk-appropriate required return","Dividends have no timing"],"correct":1,"why_vi":"Required return of equity phản ánh equity risk và investor expectation; coupon chỉ quyết định contractual bond cashflow.","trap_vi":""},{"stem_en":"Why is calculating P0=D0/(r−g) generally incorrect for a Gordon growth stock when the input given is D0?","options":["The next expected dividend D1 has not been calculated","Growth has necessarily been counted twice","Present value requires no discounting"],"correct":0,"why_vi":"Giá P0 dựa on next-period dividend D1=D0(1+g), nếu D0 là cổ tức vừa chi.","trap_vi":""},{"stem_en":"For a bond with fixed future cash flows, what generally happens to its price when YTM rises?","options":["Price rises","Price falls","Price remains unchanged"],"correct":1,"why_vi":"PV của từng CF giảm khi discount rate cao hơn, giữ nguyên cash flows và time.","trap_vi":""},{"stem_en":"In a two-stage dividend discount model, P0 includes which components?","options":["Only terminal price Pn","Present values of all dividends through Year n plus the discounted terminal price Pn","Only dividend Dn+1"],"correct":1,"why_vi":"P0=sum discounted early dividends + Pn/(1+r)^n, tránh bỏ quên hai nguồn giá trị.","trap_vi":""}],"cards":[{"front_en":"LOS 2.a chính thức CFAI bao gồm?","back_vi":"Định giá PV của fixed-income và equity instruments, dù SAPP tách nhãn khác."},{"front_en":"Discount a single CF?","back_vi":"PV=FV/(1+r)^N, continuous PV=FV exp(−rN)."},{"front_en":"Discount bond có coupon không?","back_vi":"Không có interim coupon, chỉ final principal at maturity."},{"front_en":"Negative yield zero coupon ảnh hưởng gì?","back_vi":"Giá PV có thể lớn hơn face; convergence về face nếu r không đổi."},{"front_en":"Coupon bond C tính từ?","back_vi":"Face value×coupon rate / m, không lấy market YTM để ra coupon."},{"front_en":"Semiannual coupon bond N và r?","back_vi":"N=2×years, r=annual YTM/2 theo quoted nominal convention."},{"front_en":"Coupon rate > YTM thì?","back_vi":"Premium bond tại ngày coupon."},{"front_en":"Perpetual bond price?","back_vi":"C/r với end-period level coupon và r>0, giả định không early redeem."},{"front_en":"Annuity payment A?","back_vi":"A=PV×r/[1−(1+r)^−N]."},{"front_en":"Amort principal mỗi kỳ?","back_vi":"Principal repayment=A−opening balance×r."},{"front_en":"BAII Plus P/Y=1 dùng I/Y thế nào?","back_vi":"I/Y lãi mỗi kỳ, N số kỳ; PV âm nếu là outflow."},{"front_en":"Constant dividend share PV?","back_vi":"P0=D/r nếu dividend không đổi trả cuối kỳ vĩnh viễn."},{"front_en":"Gordon Growth PV?","back_vi":"P0=D1/(r−g)=D0(1+g)/(r−g), điều kiện r>g."},{"front_en":"Two-stage terminal value đặt ở đâu?","back_vi":"Pn ở cuối năm n, tử D(n+1), PV terminal Pn/(1+r)^n."},{"front_en":"Khi nào chuyển LOS 2.b?","back_vi":"Đề cho PV/price và hỏi implied bond return, equity required return/growth."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn đã đối chiếu CFAI Curriculum 2026 — Quantitative Methods, Learning Module 2, PDF trang 53–68. LOS 2.a chính thức bao gồm fixed-income VÀ equity instruments; trang 68 chuyển sang LOS 2.b. Kaplan SchweserNotes 2026 — Book 1, PDF trang 29–35, Reading 2 / Module 2.1, LOS 2.a. Xem đặc biệt warm-up BA II Plus P/Y=1 và các ví dụ PV. SAPP Quant 2026 — PDF trang 53–66 cho fixed-income (đặt nhãn 2.a), trang 67–70 và 73–76 cho equity dividend PV (đặt nhãn 2.b). Nhãn slide khác cách gộp của Curriculum; bài này tuân LOS 2.a chính thức. Prerequisite Reading 2024 — Khái niệm discounting/PV, annuity, perpetuity và time line được tham chiếu ở mức nền tảng; không dùng để thay LOS của năm 2026. Mindmap Quant — Nhóm Time Value of Money in Finance, đối chiếu khung phân loại fixed-income và equity. Question Banks / Mocks — Đối chiếu các kiểu câu hỏi định giá PV tương ứng theo chủ đề; câu hỏi trong trang là tự biên soạn, không trích nguyên văn ngân hàng đề. Đã đối chiếu trong phạm vi các trang chuyên môn ghi trên, không tuyên bố kiểm kê hết mọi câu hỏi của 534 PDF hoặc được CFA Institute chứng thực. Sự khác biệt giữa các nguồn phải được ghi thành hồ sơ riêng."}],"legacy":"sourcefirst-quant-tvm-los01.html"},{"id":"CFA26-01-02-LOS02","letter":"b","title_en":"Implied Returns and Growth Rates","outcome_en":"Implied Bond Yields, Equity Returns and Growth","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 2.b","body":"","html":"<p class=\"lead\">LOS 2.b — Implied Yield-to-Maturity, Dividend Growth &amp;amp; Price/Earnings Valuation</p><div class=\"badgeline\"><span class=\"tag\">35 ý kiến thức đối chiếu</span><span class=\"tag\">15 ví dụ mới</span><span class=\"tag\">26 câu luyện tập</span><span class=\"tag muted\">Chỉ nghiệm thu phạm vi LOS này</span></div>","trap":""},{"heading":"1. Implied return: giá đã biết, cần suy ra suất sinh lời hoặc tăng trưởng","body":"","html":"<p>Trong LOS 2.a, ta <strong>biết suất chiết khấu</strong> để tính PV. Trong LOS <strong>2.b</strong>, thị trường đã cho giá/PV và dòng tiền dự kiến, nên ta <strong>giải ngược</strong> suất sinh lời/yield hoặc dividend growth rate. Các tham số giải ra là <em>market-implied</em> trên cơ sở các giả định; không đồng nghĩa một dự báo chắc chắn về tương lai.</p><p>Chia rõ: (i) bond contractual cash flows → implied YTM/IRR, (ii) equity assumed DDM → required equity return hoặc implied constant growth, (iii) forward/trailing P/E → suy ra r−g qua payout.</p>","trap":""},{"heading":"2. Zero-coupon: giải ngược từ PV và FV","body":"","html":"<div class=\"formula-big\">r = (FV/PV)<sup>1/N</sup> − 1</div><p>Zero-coupon chỉ có FV ở N kỳ, vì vậy nghiệm r tìm bằng lũy thừa. Nếu PV&lt;FV thì r&gt;0; nếu PV&gt;FV thì r âm (với gross return vẫn dương). Với bond mua tại giá P0 rồi bán ở P<sub>h</sub> sau h kỳ, <b>realized annualized holding-period return</b> = (P<sub>h</sub>/P0)<sup>1/h</sup>−1 (không coupon). Khác với YTM của người mua mới tại thời điểm h: [FV/P<sub>h</sub>]<sup>1/(N−h)</sup>−1.</p><p><b>Bẫy dòng thời gian:</b> giá thời điểm 0 và giá thời điểm h không dùng cùng số kỳ còn lại; không lấy FV ở maturity làm ending value của holding period nếu nhà đầu tư bán trước maturity. Khi liên kết HPR nhiều đoạn, nhân gross factors theo độ dài từng đoạn.</p>","trap":""},{"heading":"3. Coupon bond YTM là nghiệm IRR của mọi cash flows","body":"","html":"<div class=\"formula-big\">Price = Σ<sub>t=1…N</sub> C/(1+r)<sup>t</sup> + FV/(1+r)<sup>N</sup></div><p>Với coupon bond, r thường phải giải số (trial-and-error, calculator hoặc spreadsheet) sao cho PV của tất cả coupon + principal đúng bằng market price. <b>YTM = IRR</b> của cash flows đã hứa theo giả định <em>no default</em> và giữ tới maturity. Nếu coupon cố định và FV dương, giá giảm khiến YTM tăng, và ngược lại.</p><p>BA II Plus: <b>CLR TVM; N; PV=−market price; PMT=period coupon; FV=principal; CPT I/Y</b>. Với coupon semiannual, suất tính ra là mỗi nửa năm; annual stated YTM ≈2×periodic yield theo quoted convention. Excel/Sheets YIELD function có thêm settlement/maturity và day-count; không nhầm annual YTM với return mỗi kỳ.</p>","trap":""},{"heading":"4. YTM không phải lợi nhuận thực nhận chắc chắn","body":"","html":"<p>Curriculum lưu ý YTM gắn với <b>nhận đủ promised cash flows và tái đầu tư interim coupons/principal amortization ở cùng YTM</b> để đạt horizon compound return đó. Nếu nắm giữ dưới maturity, giá bán và lãi tái đầu tư coupon tạo realized holding-period return khác YTM lúc mua. Với coupon bond, terminal wealth tại thời điểm bán = market selling price + FV coupons đã nhận và tái đầu tư đến thời điểm bán, rồi giải annualized HPR.</p><p><b>Không cộng đơn giản</b> coupon yield và price gain theo phần trăm nếu coupons đã tái đầu tư hoặc thời điểm cash flows khác nhau; lập timeline và đưa mọi khoản về cùng ngày để đo return.</p>","trap":""},{"heading":"5. Perpetual coupon, annuity và giới hạn tính implied yield","body":"","html":"<p>Với fixed perpetuity trả C mỗi kỳ: <b>r=C/PV</b> khi r&gt;0 và CF chắc chắn mãi mãi. Với khoản vay amortizing payment A, giải nghiệm r từ PV=A[1−(1+r)<sup>−N</sup>]/r; thường dùng <b>IRR/financial calculator</b>, không dùng r=A/PV (chỉ đúng cho perpetual), cũng không lấy coupon rate của trái phiếu làm YTM. Dòng thanh toán khác dấu theo nhà đầu tư/issuer ảnh hưởng cách nhập máy tính.</p><p><b>Lưu ý:</b> Kết quả IRR theo kỳ cần chuyển tần suất đúng; nếu nhiều đổi dấu dòng tiền, có thể tồn tại nhiều IRR hoặc không có nghiệm kinh tế phù hợp, nên phải diễn giải ngữ cảnh.</p>","trap":""},{"heading":"6. Equity constant-dividend & Gordon: required return ngầm định","body":"","html":"<div class=\"formula-big\">r (constant D) = D/P<sub>0</sub></div><div class=\"formula-big\">r (constant g) = D<sub>1</sub>/P<sub>0</sub> + g</div><p>Trong Gordon Growth, r−g là <b>forward dividend yield</b> (D1/P0), không phải trailing dividend yield (D0/P0). Nếu market price, next-period dividend và expected perpetual growth đã biết, required return = dividend yield + growth. DDM chỉ hợp lý dưới giả định dividends g bền vững, r&gt;g; nếu dividend chưa chi hoặc growth thay đổi, phải dùng mô hình khác.</p>","trap":""},{"heading":"7. Implied dividend growth — phải biết D0 hay D1","body":"","html":"<div class=\"formula-big\">g = r − D<sub>1</sub>/P<sub>0</sub> (khi D<sub>1</sub> đã biết)</div><div class=\"formula-big\">g = (rP<sub>0</sub> − D<sub>0</sub>)/(P<sub>0</sub> + D<sub>0</sub>) (khi chỉ biết D<sub>0</sub>)</div><p>Nếu đề chỉ cho D0 và r, không được dùng g=r−D0/P0 vì D1=D0(1+g) <b>chưa biết và phụ thuộc g</b>. Giải đại số:</p><p>P0=D0(1+g)/(r−g) ⇒ P0r−P0g=D0+D0g ⇒ g(P0+D0)=P0r−D0. Đối chiếu nghiệm để chắc chắn r&gt;g. Growth suy ra là giả định được hàm ý trong market price, cần so với tăng trưởng doanh nghiệp có thể đạt.</p>","trap":""},{"heading":"8. P/E trailing, forward và payout ratio","body":"","html":"<div class=\"formula-big\">P<sub>0</sub>/E<sub>0</sub> = (D<sub>0</sub>/E<sub>0</sub>)·(1+g)/(r−g)</div><div class=\"formula-big\">Forward P/E = P<sub>0</sub>/E<sub>1</sub> = (D<sub>1</sub>/E<sub>1</sub>)/(r−g)</div><p>D/E chính là <b>dividend payout ratio</b>; với <b>forward P/E</b> và kỳ vọng payout p, ta có <b>r=g+p/(forward P/E)</b> hoặc <b>g=r−p/(forward P/E)</b>. Forward P/E cao hơn khi payout hoặc growth cao hơn, thấp hơn khi required return cao hơn (giữ các giả định khác).</p><p>Không nhầm <b>trailing EPS E0</b> với <b>forward EPS E1</b>. Công thức trên giả định cùng perpetual dividend growth g, ổn định payout theo mô hình; không áp dụng máy móc cho EPS âm, doanh nghiệp không trả dividend hoặc payout bất thường.</p>","trap":""},{"heading":"9. Đọc kỳ vọng thị trường và so sánh với valuation","body":"","html":"<p>Ví dụ một cổ phiếu giao dịch <b>forward P/E=18</b>, payout dự báo <b>60%</b> thì spread <b>r−g=0,60/18=3,333%</b>. Nếu nhà phân tích kỳ vọng r=9% và g=4%, forward multiple hàm ý theo mô hình <b>0,60/(0,09−0,04)=12</b>, thấp hơn market P/E 18 → giá thị trường có vẻ cao so với bộ giả định đó; cần đối chiếu assumptions, chi phí giao dịch và khả năng shorting trước khi đưa khuyến nghị.</p><p>Điểm cần tránh: cho rằng market P/E cao tức chắc chắn đắt. P/E thể hiện phối hợp payout, required return và growth; một P/E cao có thể hợp lý nếu growth cao hay r thấp.</p>","trap":""}],"formulas":[{"name":"2. Zero-coupon: giải ngược từ PV và FV","expr":"r = (FV/PV) 1/N − 1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Coupon bond YTM là nghiệm IRR của mọi cash flows","expr":"Price = Σ t=1…N C/(1+r) t + FV/(1+r) N","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Equity constant-dividend & Gordon: required return ngầm định","expr":"r (constant D) = D/P 0","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"6. Equity constant-dividend & Gordon: required return ngầm định","expr":"r (constant g) = D 1 /P 0 + g","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Implied dividend growth — phải biết D0 hay D1","expr":"g = r − D 1 /P 0 (khi D 1 đã biết)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. Implied dividend growth — phải biết D0 hay D1","expr":"g = (rP 0 − D 0 )/(P 0 + D 0 ) (khi chỉ biết D 0 )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"8. P/E trailing, forward và payout ratio","expr":"P 0 /E 0 = (D 0 /E 0 )·(1+g)/(r−g)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"8. P/E trailing, forward và payout ratio","expr":"Forward P/E = P 0 /E 1 = (D 1 /E 1 )/(r−g)","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · Zero coupon yield dương","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · Zero coupon yield dương</div><div class=\"body\"><p><b>Đề:</b> Face 1.000, giá 800 và maturity còn 4 năm, annual compounding.</p><ol><li>Yield= (1.000/800)^(1/4)−1.</li><li>Kiểm tra PV tại yield đó bằng cách discount lại FV.</li></ol><p class=\"answer\">Kết quả: YTM≈5.73713%.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E02 · Zero coupon yield âm","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · Zero coupon yield âm</div><div class=\"body\"><p><b>Đề:</b> Face 1.000, market price 1.025, maturity còn 3 năm.</p><ol><li>r=(1.000/1.025)^(1/3)−1.</li><li>Giá premium dẫn đến negative implied yield.</li></ol><p class=\"answer\">Kết quả: r≈-0.81971%.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E03 · Hai holding periods khác nhau","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · Hai holding periods khác nhau</div><div class=\"body\"><p><b>Đề:</b> Investor mua zero-coupon ở 980, 2 năm sau bán 960; buyer mới sẽ thu 1.000 sau 3 năm.</p><ol><li>Original investor two-year annualized HPR=(960/980)^(1/2)−1.</li><li>Buyer new 3-year YTM=(1000/960)^(1/3)−1.</li><li>Không gộp hai tỷ lệ thành một lợi suất nếu không chuẩn hóa horizon.</li></ol><p class=\"answer\">Kết quả: HPR seller≈-1.0257%; YTM buyer≈1.3700%.</p><small>Nhóm kiến thức: zero</small></div>"},{"question_en":"E04 · Coupon bond: implied yield bằng nghiệm PV","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Coupon bond: implied yield bằng nghiệm PV</div><div class=\"body\"><p><b>Đề:</b> Par 1.000, coupon annual 4% (40), còn 5 năm, current price 980.</p><ol><li>Giải 980=Σ(40/(1+r)^t, t=1..5)+1.000/(1+r)^5.</li><li>Thử nghiệm r bằng solver hoặc BA II Plus N=5, PV=−980, PMT=40, FV=1.000.</li></ol><p class=\"answer\">Kết quả: YTM≈4.45501%.</p><small>Nhóm kiến thức: coupon</small></div>"},{"question_en":"E05 · Semiannual yield phải quy đổi đúng kỳ","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Semiannual yield phải quy đổi đúng kỳ</div><div class=\"body\"><p><b>Đề:</b> Face 1.000, semiannual coupon 25, còn 4 năm, market price 955; tìm nominal annual YTM.</p><ol><li>N=8 kỳ, PMT=25, PV=−955, FV=1.000.</li><li>Giải periodic r từ giá; annual stated YTM=2×r.</li></ol><p class=\"answer\">Kết quả: Periodic yield≈3.14498%; annual nominal≈6.28996%.</p><small>Nhóm kiến thức: bond-other</small></div>"},{"question_en":"E06 · Held-period return có tái đầu tư coupon","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · Held-period return có tái đầu tư coupon</div><div class=\"body\"><p><b>Đề:</b> Mua bond tại giá 1.000, nhận coupon 35 cuối năm 1 và cuối năm 2, bán cuối năm 2 ở 990; coupon năm 1 tái đầu tư 3% đến thời điểm bán.</p><ol><li>Terminal wealth=990+35×1,03+35.</li><li>Annualized realized return=(terminal wealth/1.000)^(1/2)−1.</li></ol><p class=\"answer\">Kết quả: Terminal wealth=1061.05; annualized return≈3.0073%.</p><small>Nhóm kiến thức: realized</small></div>"},{"question_en":"E07 · Perpetuity price suy ngược required yield","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · Perpetuity price suy ngược required yield</div><div class=\"body\"><p><b>Đề:</b> Perpetual coupon 3,60/năm, price 90, assume fixed periodic coupon forever.</p><ol><li>r=C/P=3,60/90.</li><li>Không áp dụng nếu callable debt bị redeem khi coupon không còn tồn tại.</li></ol><p class=\"answer\">Kết quả: r=4,00%/năm.</p><small>Nhóm kiến thức: bond-other</small></div>"},{"question_en":"E08 · Equity constant dividend implied r","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Equity constant dividend implied r</div><div class=\"body\"><p><b>Đề:</b> Cổ phiếu ưu đãi trả 2,80/năm vĩnh viễn, current price 35.</p><ol><li>r=D/P0=2,80/35.</li></ol><p class=\"answer\">Kết quả: r=8,00%.</p><small>Nhóm kiến thức: equity-r</small></div>"},{"question_en":"E09 · Gordon implied return","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Gordon implied return</div><div class=\"body\"><p><b>Đề:</b> Một cổ phiếu có market price 50, next dividend D1=2,25 và expected growth g=3%.</p><ol><li>Dividend yield=2,25/50=4,5%.</li><li>Required return r=D1/P0+g=4,5%+3%.</li></ol><p class=\"answer\">Kết quả: r=7,50%.</p><small>Nhóm kiến thức: equity-r</small></div>"},{"question_en":"E10 · Gordon implied growth biết D1","steps_vi":[],"answer":"","html":"<div class=\"top\">E10 · Gordon implied growth biết D1</div><div class=\"body\"><p><b>Đề:</b> P0=45, expected dividend D1=1,80, investor required r=9%.</p><ol><li>Dividend yield=1,80/45=4%.</li><li>g=9%−4%=5%.</li></ol><p class=\"answer\">Kết quả: g=5,00%.</p><small>Nhóm kiến thức: equity-g</small></div>"},{"question_en":"E11 · Implied growth khi chỉ cho D0","steps_vi":[],"answer":"","html":"<div class=\"top\">E11 · Implied growth khi chỉ cho D0</div><div class=\"body\"><p><b>Đề:</b> P0=60, D0=2, r=9%. Tìm g nếu dividends tăng đều mãi.</p><ol><li>P0=2(1+g)/(0,09−g).</li><li>g=(0,09×60−2)/(60+2).</li><li>Từ g mới tính D1=2(1+g), đối chiếu D1/(r−g)=60.</li></ol><p class=\"answer\">Kết quả: g≈5.48387%.</p><small>Nhóm kiến thức: equity-g</small></div>"},{"question_en":"E12 · Forward P/E suy required return","steps_vi":[],"answer":"","html":"<div class=\"top\">E12 · Forward P/E suy required return</div><div class=\"body\"><p><b>Đề:</b> Forward P/E=20, expected payout=50%, expected perpetual dividend g=4%.</p><ol><li>r−g=payout/(forward PE)=0,5/20=2,5%.</li><li>r=g+2,5%=6,5%.</li></ol><p class=\"answer\">Kết quả: r=6,50%.</p><small>Nhóm kiến thức: pe</small></div>"},{"question_en":"E13 · Forward P/E suy implied growth","steps_vi":[],"answer":"","html":"<div class=\"top\">E13 · Forward P/E suy implied growth</div><div class=\"body\"><p><b>Đề:</b> Forward P/E=24, payout=60%, assumed r=8%.</p><ol><li>r−g=0,6/24=2,5%.</li><li>g=8%−2,5%.</li></ol><p class=\"answer\">Kết quả: g=5,50%.</p><small>Nhóm kiến thức: pe</small></div>"},{"question_en":"E14 · Trailing P/E khác forward","steps_vi":[],"answer":"","html":"<div class=\"top\">E14 · Trailing P/E khác forward</div><div class=\"body\"><p><b>Đề:</b> D0=1,50; current EPS E0=5; g=4%, r=9%.</p><ol><li>Trailing implied P/E=(D0/E0)(1+g)/(r−g)=0,30×1,04/0,05.</li><li>Forward P/E cần E1 (khác E0), không tự coi hai P/E bằng nhau.</li></ol><p class=\"answer\">Kết quả: Trailing P/E≈6,24.</p><small>Nhóm kiến thức: pe</small></div>"},{"question_en":"E15 · Định giá P/E và kết luận có điều kiện","steps_vi":[],"answer":"","html":"<div class=\"top\">E15 · Định giá P/E và kết luận có điều kiện</div><div class=\"body\"><p><b>Đề:</b> Market forward P/E=18, expected payout=60%, investor r=9%, sustainable g=4%.</p><ol><li>Model implied PE=0,60/(0,09−0,04)=12.</li><li>Market multiple 18&gt;model 12, cổ phiếu có vẻ đắt so với các giả định, không phải kết luận chắc chắn.</li></ol><p class=\"answer\">Kết quả: Model forward PE=12; market premium 50% so với model (18/12−1).</p><small>Nhóm kiến thức: interpret</small></div>"}],"questions":[{"stem_en":"A bond's current price and promised cash flows are known. How is its yield to maturity determined?","options":["Solve for the discount rate that equates the present value of promised cash flows to price","Substitute price for the coupon rate","Subtract the coupon payment from price"],"correct":0,"why_vi":"YTM/IRR là rate thỏa P=ΣCF/(1+r)^t, không phải coupon rate.","trap_vi":""},{"stem_en":"A zero-coupon bond with face value USD 1,000 trades for USD 800 and matures in four years. Its implied annual compounded yield is closest to:","options":["5.737%","25.000%","4.000%"],"correct":0,"why_vi":"r=(1000/800)^(1/4)−1, annual compounding.","trap_vi":""},{"stem_en":"A zero-coupon bond with face value USD 1,000 trades for USD 1,025 and matures in three years. Its implied annual yield is:","options":["Positive","Negative","Zero"],"correct":1,"why_vi":"Giá mua cao hơn face, lợi suất theo FV/PV thấp hơn 0.","trap_vi":""},{"stem_en":"A zero-coupon bond is bought for 980 and sold two years later for 960, with no intervening cash flows. Its annualized holding-period return is closest to:","options":["−1.026%","+1.370%","0%"],"correct":0,"why_vi":"HPR seller dùng ending sale price 960, không dùng final principal 1.000.","trap_vi":""},{"stem_en":"A new investor pays 960 for a zero-coupon bond paying 1,000 in three years. The implied annual yield is closest to:","options":["+1.370%","−1.026%","+4.17%"],"correct":0,"why_vi":"Buyer YTM tính từ 960 đến 1.000 trong 3 năm còn lại.","trap_vi":""},{"stem_en":"An annual-coupon bond has five years remaining, pays USD 40 each year, has a USD 1,000 face value, and trades for USD 980. Its YTM is closest to:","options":["4.455%","4.000%","2.000%"],"correct":0,"why_vi":"Giải bằng IRR sao cho PV(5 coupons + face)=980; YTM>coupon rate khi price<par.","trap_vi":""},{"stem_en":"Holding a bond's promised cash flows constant, a decline in its market price implies that YTM:","options":["Falls","Rises","Does not change"],"correct":1,"why_vi":"Discount rate tăng sẽ làm PV giảm, và quan hệ đảo chiều khi giải ngược.","trap_vi":""},{"stem_en":"To calculate the YTM of a bond priced at 980 on a BA II Plus, if N=5, PMT=40, and FV=1,000, PV should be entered as:","options":["+980","−980","0"],"correct":1,"why_vi":"Theo convention investor pay 980 là outflow âm, coupon và principal thu về dương.","trap_vi":""},{"stem_en":"For a semiannual-pay bond, a financial calculator yields a per-half-year interest rate of 3.2%. Its nominal annual bond-equivalent YTM is:","options":["1.6%","6.4%","3.2%"],"correct":1,"why_vi":"Theo semiannual stated YTM=2×periodic rate=6,4%, không phải effective rate năm.","trap_vi":""},{"stem_en":"For a coupon bond's YTM to equal its realized annualized compound return through maturity, which condition is most relevant?","options":["All promised cash flows are paid and coupons can be reinvested at YTM","Coupon rate must exceed YTM","Any selling price before maturity will suffice"],"correct":0,"why_vi":"Reinvestment at YTM and promised cash flows received until maturity là giả định của compound yield.","trap_vi":""},{"stem_en":"An investor sells a bond before maturity. Calculating the investor's realized holding-period return requires:","options":["Sale proceeds, coupons received, and any applicable reinvestment of coupons","Only face value due at maturity","Only annual coupon rate"],"correct":0,"why_vi":"Terminal wealth gồm market sale price cộng coupon streams đầu tư đến đúng ngày bán.","trap_vi":""},{"stem_en":"A perpetual security pays an annual cash flow of 3.60 and trades at 90. Its implied required return is:","options":["3%","4%","9%"],"correct":1,"why_vi":"YTM của fixed perpetuity =C/PV=3,6/90=4%.","trap_vi":""},{"stem_en":"A constant-dividend share pays USD 2.80 annually and trades for USD 35. Its implied required return is:","options":["8%","10%","12%"],"correct":0,"why_vi":"r=D/P0=2,8/35=8% cho perpetuity dividend không tăng.","trap_vi":""},{"stem_en":"For a constant-growth share, P0=50, next dividend D1=2.25, and g=3%. The implied required return is:","options":["4.5%","7.5%","9.0%"],"correct":1,"why_vi":"Trong Gordon, forward dividend yield=2,25/50=4,5%, cộng tăng trưởng 3% được r=7,5%.","trap_vi":""},{"stem_en":"A constant-growth stock trades at P0=45, with next dividend D1=1.80 and required return r=9%. The implied growth rate is:","options":["5%","4%","9%"],"correct":0,"why_vi":"Implied growth khi D1 biết: g=r−D1/P0=9%−(1,80/45)=5%; khác với D0/P0.","trap_vi":""},{"stem_en":"Only D0 and P0 are known. Is g=r−D0/P0 a generally valid solution for Gordon growth?","options":["Yes, always","No; the next dividend D1=D0(1+g) also depends on g","Yes, when g exceeds r"],"correct":1,"why_vi":"D0 là dividend vừa chi, không phải next dividend D1; phải giải đại số.","trap_vi":""},{"stem_en":"In a Gordon growth model, P0=60, D0=2, and r=9%. The implied growth rate is closest to:","options":["5.484%","5.667%","9.000%"],"correct":0,"why_vi":"g=(rP0−D0)/(P0+D0), vì D1=D0(1+g).","trap_vi":""},{"stem_en":"The forward dividend yield is defined as:","options":["D0/P0","D1/P0","EPS/P0"],"correct":1,"why_vi":"Trong Gordon, r−g=D1/P0, suất cổ tức kỳ tới trên giá hiện tại.","trap_vi":""},{"stem_en":"A forward price-to-earnings ratio uses which earnings per share measure in its denominator?","options":["E0","E1","E−1"],"correct":1,"why_vi":"Forward P/E dùng kỳ dự kiến t+1 EPS, trailing dùng EPS quá khứ/current.","trap_vi":""},{"stem_en":"The dividend payout ratio equals:","options":["Dividend per share / earnings per share","Earnings per share / dividend per share","Share price / earnings per share"],"correct":0,"why_vi":"Payout=dividend per share/earnings per share theo cùng kỳ.","trap_vi":""},{"stem_en":"In the constant-growth model, forward P/E is 20, payout ratio is 50%, and g=4%. The implied required return is:","options":["6.5%","4.0%","2.5%"],"correct":0,"why_vi":"r=g+p/forwardPE=4%+0,5/20=6,5%.","trap_vi":""},{"stem_en":"Forward P/E is 24, dividend payout ratio is 60%, and required return is 8%. The implied growth rate is:","options":["2.5%","5.5%","8.0%"],"correct":1,"why_vi":"r−g=payout/PE=0,60/24=2,5%; g=5,5%.","trap_vi":""},{"stem_en":"Holding other Gordon model assumptions constant, why does forward P/E tend to rise when required return falls?","options":["The denominator r−g falls in P/E = payout/(r−g)","Cash flow necessarily falls","P/E is independent of required return"],"correct":0,"why_vi":"Mẫu số r−g nhỏ hơn làm forward P/E theo Gordon model lớn hơn.","trap_vi":""},{"stem_en":"A stock's market forward P/E is 18, while the analyst's model-implied forward P/E is 12. Which is most appropriate?","options":["The stock looks relatively expensive under the model's assumptions","A short sale is guaranteed to profit regardless of costs","The stock is necessarily cheap"],"correct":0,"why_vi":"Chỉ là overvaluation so với những r,g,payout đang giả định, cần kiểm tra dữ liệu/khả năng thực thi.","trap_vi":""},{"stem_en":"Why does a higher P/E than peers not automatically prove overvaluation?","options":["A higher P/E guarantees overvaluation","The company may have different expected growth, risk, or payout","A higher P/E guarantees greater future profits"],"correct":1,"why_vi":"Multiple phải xét jointly dividend payout, growth, required return, không quyết định chỉ từ PE cao.","trap_vi":""},{"stem_en":"To infer the yield on an amortizing loan when payment, maturity, and price are known, an analyst should:","options":["Solve the discounting equation for the internal rate of return","Divide payment by present value only","Use the coupon rate only"],"correct":0,"why_vi":"Annuity implied rate nằm trong both denominator và exponent, thường giải số.","trap_vi":""}],"cards":[{"front_en":"Bond YTM khi giá và CF đã biết?","back_vi":"IRR làm present value của promised CF bằng current price."},{"front_en":"Zero-coupon implied yield?","back_vi":"(FV/PV)^(1/N)−1."},{"front_en":"Giá zero-coupon > par, yield thường?","back_vi":"Âm nếu only one fixed future principal và r>-100%."},{"front_en":"Holding-period return khi bán sớm?","back_vi":"Dùng purchase price và terminal wealth tại ngày bán, không dùng face ở maturity."},{"front_en":"Yield semiannual trên BAII Plus?","back_vi":"I/Y theo kỳ là semiannual rate; annual nominal yield=2×I/Y."},{"front_en":"Reinvest coupons at YTM — vì sao?","back_vi":"Để compound return thực nhận trong kỳ nắm giữ phù hợp YTM đã tính."},{"front_en":"Coupon bond sale HPR cần gì?","back_vi":"Giá bán + coupons accumulated đến ngày bán."},{"front_en":"Perpetuity implied yield?","back_vi":"r=C/price."},{"front_en":"Gordon implied r?","back_vi":"r=D1/P0+g."},{"front_en":"Implied g nếu biết D1?","back_vi":"g=r−D1/P0."},{"front_en":"Implied g nếu biết D0?","back_vi":"g=(rP0−D0)/(P0+D0)."},{"front_en":"Trailing P/E dùng EPS nào?","back_vi":"EPS kỳ t/đã biết; forward dùng E(t+1)."},{"front_en":"Forward P/E theo payout?","back_vi":"Forward P/E = payout/(r−g), giả sử growth vĩnh viễn r>g."},{"front_en":"r từ forward PE?","back_vi":"r=g+payout/(forward P/E)."},{"front_en":"High PE kết luận được gì?","back_vi":"Chỉ thể hiện joint expectations payout/growth/required r, không tự kết luận expensive."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn đã đối chiếu CFAI 2026 — Curriculum Quantitative Methods, Learning Module 2, PDF trang 68–77: implied zero-coupon/coupon YTM, equity expected dividend yield and g, P/E forward/trailing, market-implied assumptions. Kaplan 2026 — SchweserNotes Book 1, PDF trang 36–37 (LOS 2.b), và trang 29–30 hướng dẫn calculator BA II Plus dùng I/Y mỗi kỳ. SAPP 2026 — Quant notes PDF trang 54–65 (tính bond yield minh họa), trang 68–80 (equity implied r/g và forward P/E). Slide SAPP tách fixed vs equity khác LOS CFAI. Mindmap / Prerequisite — Dùng đối chiếu khung TVM, IRR và PV; giữ trình bày chuẩn Curriculum 2026. Question Banks / Mocks — Đối chiếu kỹ năng nhận diện các bài toán ngược PV, từng câu trong web tự biên soạn; không tái phát hành nguyên văn tài liệu đề. Đã đối chiếu trong phạm vi các trang chuyên môn ghi trên, không tuyên bố kiểm kê hết mọi câu hỏi của 534 PDF hoặc được CFA Institute chứng thực. Sự khác biệt giữa các nguồn phải được ghi thành hồ sơ riêng."}],"legacy":"sourcefirst-quant-tvm-los02.html"},{"id":"CFA26-01-02-LOS03","letter":"c","title_en":"Cash Flow Additivity and No-Arbitrage","outcome_en":"Cash Flow Additivity, Forwards, FX and Option Replication","overview_vi":"Bài học Quantitative Methods từ bộ học liệu chuyên sâu gốc. Mở từng phần để xem bảng, công thức và diễn giải đầy đủ.","sections":[{"heading":"Learning Outcome 2.c","body":"","html":"<p class=\"lead\">LOS 2.c — No-Arbitrage Pricing from Equivalent Cash Flows</p><div class=\"badgeline\"><span class=\"tag\">34 ý kiến thức đối chiếu</span><span class=\"tag\">15 ví dụ mới</span><span class=\"tag\">28 câu luyện tập</span><span class=\"tag muted\">Chỉ nghiệm thu phạm vi LOS này</span></div>","trap":""},{"heading":"1. Cash flow additivity: nguyên tắc giá trị cộng được","body":"","html":"<div class=\"formula-big\">PV(CF<sub>A</sub>+CF<sub>B</sub>)=PV(CF<sub>A</sub>)+PV(CF<sub>B</sub>)</div><p>Nếu các dòng tiền được quy về <b>cùng mốc thời gian</b> và được discount nhất quán theo cùng trạng thái rủi ro/đơn vị tiền tệ, PV của tổng hai dòng đúng bằng tổng PV từng dòng. Có thể <em>tách khoản trả đều và khoản trả thêm</em> để tính tiện hơn; hoặc lấy chênh lệch hai chiến lược theo từng kỳ rồi discount để so NPV. Một khoản ở t=0 không discount, t=3 chia cho (1+r)^3.</p><p><b>Additivity không đòi dòng tiền cùng số tiền từng năm</b>; điều kiện cộng ở cùng thời điểm và chiết khấu đúng cơ sở. Cặp chiến lược cùng chi phí ban đầu có ΔNPV=PV(ΔCF). Nếu hai PV tài chính giống nhau và cùng risk, nhà đầu tư không ưu tiên chỉ vì một phương án có coupon sớm hơn.</p>","trap":""},{"heading":"2. Law of One Price và No-Arbitrage","body":"","html":"<p><b>No-arbitrage</b> (không có lợi nhuận chắc chắn với vốn ban đầu bằng 0, bỏ qua transaction costs) đòi các chiến lược cho cùng dòng tiền trong <b>mọi trạng thái thị trường, cùng thời điểm</b> có cùng giá. Nếu hai dòng tiền tương đương nhưng giá khác, mua rẻ/bán đắt tạo cash flow không rủi ro trước khi chênh lệch được giao dịch xóa.</p><p>Không nhầm với việc hai khoản có <em>expected returns</em> bằng nhau: khác payoff theo trạng thái có thể có premium rủi ro khác. Trong ví dụ thực tế, bid-ask spread, funding/margin, thuế, hạn chế shorting có thể ngăn arbitrage hoàn hảo, nên không suy diễn “có thể arbitrage trong thực tế” chỉ từ mô hình giản lược.</p>","trap":""},{"heading":"3. Forward interest rates bằng so sánh hai chiến lược tái đầu tư","body":"","html":"<div class=\"formula-big\">(1+s<sub>2</sub>)²=(1+s<sub>1</sub>)(1+F<sub>1,1</sub>)</div><div class=\"formula-big\">F<sub>1,1</sub>=(1+s<sub>2</sub>)²/(1+s<sub>1</sub>)−1</div><p>s1 là spot rate 1 năm, s2 là spot 2 năm (annual effective). F1,1 là lãi suất forward <b>1 năm, bắt đầu sau 1 năm</b>; không đồng nhất F với dự báo realized future spot rate. Hai chiến lược dùng 100 tại t=0: đầu tư 2 năm với s2 hoặc đầu tư năm đầu s1 và khóa năm tiếp theo F1,1. No-arbitrage buộc payoffs t=2 giống nhau.</p><p>Ví dụ s1=3%, s2=4% → F1,1=(1,04)²/1,03−1≈5,01%. Với annual compounding và định nghĩa F<sub>m,n</sub> là forward <b>n năm bắt đầu sau m năm</b>, công thức tổng quát: <b>(1+s<sub>m+n</sub>)<sup>m+n</sup>=(1+s<sub>m</sub>)<sup>m</sup>(1+F<sub>m,n</sub>)<sup>n</sup></b>.</p>","trap":""},{"heading":"4. Nếu market forward khác break-even, xác định arbitrage đúng chiều","body":"","html":"<p>Nếu forward có thể khóa ở 5,5% trong năm 2 nhưng F1,1 cân bằng là 5,01% (s1=3%,s2=4%), ta có thể vay 100 trong 2 năm với 4%/năm, đầu tư một năm ở 3%, sau đó đầu tư năm tiếp ở forward 5,5%. Khoản thu sau hai năm <b>100×1,03×1,055=108,665</b>; nghĩa vụ trả vay <b>100×1,04²=108,16</b>; lời chắc chắn <b>0,505</b> (bỏ qua chi phí). Nếu forward thấp hơn cân bằng, đảo chiều chiến lược.</p><p>Bẫy thường gặp: lấy bình quân lãi suất hai năm 4% và năm đầu 3% rồi suy year-two rate=5% chỉ là xấp xỉ; phải dùng tích <em>gross factors</em>. Không kết luận F1,1 là lãi thực tế năm sau: đây là <b>breakeven rate today</b>.</p>","trap":""},{"heading":"5. Forward FX bằng covered interest parity (đúng thứ tự tỷ giá)","body":"","html":"<p>Đặt S<sub>price/base</sub> là số đơn vị <b>price currency</b> cho 1 đơn vị <b>base currency</b> (ví dụ USD/EUR=1,25). Với suất risk-free đồng tiền báo giá (price) là r<sub>p</sub> và của đồng tiền cơ sở là r<sub>b</sub> cho <b>cùng kỳ</b>, dạng periodic one-year:</p><div class=\"formula-big\">F<sub>price/base</sub>=S<sub>price/base</sub>×(1+r<sub>p</sub>)/(1+r<sub>b</sub>)</div><p>Với continuous rates r<sub>p</sub> và r<sub>b</sub> annual, horizon T năm: <b>F=S×exp[(r<sub>p</sub>−r<sub>b</sub>)T]</b>. Với m kỳ r đơn: có thể dùng [(1+r<sub>p</sub>)<sup>T</sup>/(1+r<sub>b</sub>)<sup>T</sup>] theo đúng đơn vị và compounding. <b>Không tự đảo</b> numerator/denominator: trong quote USD/EUR, numerator rUSD, denominator rEUR. Số quote F tăng nghĩa là cần nhiều USD hơn để mua 1 EUR theo forward, không phải dự báo spot chắc chắn.</p>","trap":""},{"heading":"6. Hai chiến lược FX và covered arbitrage","body":"","html":"<p>Giả sử S=1,25 USD/EUR, lãi USD 5%, EUR 2% trong năm. Từ EUR100, đầu tư EUR risk-free thu EUR102. Nếu đổi EUR100→USD125 ngay, đầu tư 5% thu USD131,25. Giá forward hòa vốn cần <b>F=131,25/102≈1,286765 USD/EUR</b>. Nếu forward thị trường F=1,30, arbitrage mô hình: vay USD125, đổi lấy EUR100, đầu tư EUR tại 2%, bán EUR102 kỳ hạn ở 1,30 → nhận USD132,60, trả nợ USD131,25 → lời USD1,35.</p><p>Covered parity là quan hệ theo lãi suất/forward <b>được khóa</b>, không phải lý thuyết khẳng định tỷ giá spot tương lai. Các mức FX bid/ask, borrowing/lending rates và credit/settlement risks có thể làm arbitrage thực tế khác tình huống lý tưởng.</p>","trap":""},{"heading":"7. One-period binomial call: payoff và delta hedge","body":"","html":"<p>Quyền chọn mua (call) có strike X: <b>C<sub>u</sub>=max(S<sub>u</sub>−X,0)</b>, <b>C<sub>d</sub>=max(S<sub>d</sub>−X,0)</b>. Với underlying hiện S0, sau một kỳ có Su hoặc Sd, chọn <b>h=(Cu−Cd)/(Su−Sd)</b> cổ phiếu và <b>short 1 call</b> sao cho giá trị terminal V1u=hSu−Cu và V1d=hSd−Cd <b>giống nhau</b>. Khi đó:</p><div class=\"formula-big\">C<sub>0</sub>=hS<sub>0</sub>−(hS<sub>u</sub>−C<sub>u</sub>)/(1+r<sub>f</sub>)</div><p><b>Hedge ratio h</b> phản ánh số đơn vị underlying cần nắm giữ cho mỗi call short trong portfolio không rủi ro. Với một kỳ risk-free return rf, PV của payoff chắc chắn là VT/(1+rf). Chọn payoff <em>ở cùng trạng thái</em> để đối chiếu không sót dấu short call.</p>","trap":""},{"heading":"8. One-period binomial put: replicated risk-free portfolio","body":"","html":"<p>Put cho quyền bán tại strike X: <b>P<sub>u</sub>=max(X−S<sub>u</sub>,0)</b> và <b>P<sub>d</sub>=max(X−S<sub>d</sub>,0)</b>. Khi put tăng giá lúc underlying giảm, có thể tạo danh mục không rủi ro gồm <b>long h shares + long put</b> (không phải short put trong công thức sau), với <b>h=(Pd−Pu)/(Su−Sd)</b>:</p><div class=\"formula-big\">P<sub>0</sub>=(hS<sub>u</sub>+P<sub>u</sub>)/(1+r<sub>f</sub>)−hS<sub>0</sub></div><p>Kiểm tra V1u=hSu+Pu và V1d=hSd+Pd phải trùng nhau. Giá put hợp lý rút ra từ PV portfolio risk-free. Thay cấu trúc short/long mà không thay dấu sẽ cho kết quả âm/sai.</p>","trap":""},{"heading":"9. Kiểm tra chéo, điều kiện và ranh giới phạm vi","body":"","html":"<p>Trong binomial một kỳ không có dividend, để không có arbitrage nội tại phải có <b>d&lt;1+rf&lt;u</b>, với d=Sd/S0, u=Su/S0. Ví dụ S0=70, Su=91 (u=1,30), Sd=56 (d=0,80), rf=5% =&gt; 0,80&lt;1,05&lt;1,30. Từ call/put price có thể kiểm tra phụ: <b>C0−P0 = S0−X/(1+rf)</b> trong trường hợp không có dividend; đây chỉ là kiểm tra nhất quán, mô hình quyền chọn chi tiết được học thêm tại Derivatives.</p><p>Từng phương pháp trong LOS 2.c cùng xuất phát từ một ý: <b>tạo hai danh mục có payoffs cùng thời điểm và mọi trạng thái</b>, rồi buộc PV bằng nhau. Nếu payoff khác risk, đơn vị tiền hoặc kỳ, không thể áp dụng công thức chỉ bằng cách thay số.</p>","trap":""},{"heading":"10. Phân biệt lỗi ký hiệu trong nguồn và nguồn ưu tiên","body":"","html":"<p>SAPP Quant PDF trang 87 có một bản trình bày chênh lệch cash flow cuối kỳ khác (32,25) so với trang 88 và CFAI Curriculum 2026 PDF trang 78 (32,35). Tôi không bê dữ liệu của một ví dụ nguồn vào website, mà dùng <b>ví dụ tự biên soạn</b> và đối chiếu tính cộng với các giá trị kiểm tra bằng phép tính độc lập. Với công thức, <b>CFAI Curriculum 2026 là chuẩn ưu tiên</b>; các slide/sách bổ trợ được dùng để hiểu và nhận ra sự khác biệt.</p>","trap":""}],"formulas":[{"name":"1. Cash flow additivity: nguyên tắc giá trị cộng được","expr":"PV(CF A +CF B )=PV(CF A )+PV(CF B )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Forward interest rates bằng so sánh hai chiến lược tái đầu tư","expr":"(1+s 2 )²=(1+s 1 )(1+F 1,1 )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"3. Forward interest rates bằng so sánh hai chiến lược tái đầu tư","expr":"F 1,1 =(1+s 2 )²/(1+s 1 )−1","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"5. Forward FX bằng covered interest parity (đúng thứ tự tỷ giá)","expr":"F price/base =S price/base ×(1+r p )/(1+r b )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"7. One-period binomial call: payoff và delta hedge","expr":"C 0 =hS 0 −(hS u −C u )/(1+r f )","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""},{"name":"8. One-period binomial put: replicated risk-free portfolio","expr":"P 0 =(hS u +P u )/(1+r f )−hS 0","meaning":"Xem diễn giải, ký hiệu và điều kiện trong mục tương ứng của bài học.","conditions":""}],"examples":[{"question_en":"E01 · Cash flow decomposition","steps_vi":[],"answer":"","html":"<div class=\"top\">E01 · Cash flow decomposition</div><div class=\"body\"><p><b>Đề:</b> Một tài sản trả 100 vào cuối các năm 1,2,3,4 và thêm 250 vào cuối năm 3, discount 10%.</p><ol><li>PV annuity 4y=100×[1−1,10^−4]/0,10.</li><li>PV extra=250/1,10^3.</li><li>PV whole bằng tổng hai phần hoặc discount năm 3 là 350.</li></ol><p class=\"answer\">Kết quả: PV annuity≈316.9865; extra≈187.8287; tổng≈504.8152.</p><small>Nhóm kiến thức: basis</small></div>"},{"question_en":"E02 · PV difference of two strategies","steps_vi":[],"answer":"","html":"<div class=\"top\">E02 · PV difference of two strategies</div><div class=\"body\"><p><b>Đề:</b> A trả cuối năm 1 và 2 lần lượt 70, 90. B trả 80, 80. Cùng initial investment, discount 5%.</p><ol><li>ΔCF=A−B=[−10,+10] tại t=1,2.</li><li>ΔPV=−10/1,05+10/1,05².</li><li>A có PV thấp hơn B nếu ΔPV âm.</li></ol><p class=\"answer\">Kết quả: ΔPV≈-0.4535.</p><small>Nhóm kiến thức: basis</small></div>"},{"question_en":"E03 · 1-year forward in 1-year","steps_vi":[],"answer":"","html":"<div class=\"top\">E03 · 1-year forward in 1-year</div><div class=\"body\"><p><b>Đề:</b> Spot s1=3%/năm, s2=4%/năm (annual effective).</p><ol><li>(1+0,04)^2=(1+0,03)(1+F1,1).</li><li>F1,1=(1,04)^2/1,03−1.</li></ol><p class=\"answer\">Kết quả: F1,1≈5.00971%.</p><small>Nhóm kiến thức: interest</small></div>"},{"question_en":"E04 · Forward year 3 from spot curves","steps_vi":[],"answer":"","html":"<div class=\"top\">E04 · Forward year 3 from spot curves</div><div class=\"body\"><p><b>Đề:</b> Spot s2=3%/năm, s3=3,5%/năm. Tính forward một năm bắt đầu sau 2 năm.</p><ol><li>F2,1=(1,035)^3/(1,03)^2−1.</li><li>Check: reinvest 2y spot×1y forward equals 3y spot compounded.</li></ol><p class=\"answer\">Kết quả: F2,1≈4.50729%.</p><small>Nhóm kiến thức: interest</small></div>"},{"question_en":"E05 · Forward arbitrage nếu mispriced","steps_vi":[],"answer":"","html":"<div class=\"top\">E05 · Forward arbitrage nếu mispriced</div><div class=\"body\"><p><b>Đề:</b> Spot 1y 3%, 2y 4%; thị trường khóa forward năm thứ 2 ở 5,5%, vốn danh nghĩa 100.</p><ol><li>Vay 100 trong 2 năm tại spot 4%: repay 100×1,04²=108,16.</li><li>Đầu tư 1y 3% và 1y 5,5%: receive 100×1,03×1,055=108,665.</li><li>Profit difference sau 2 năm, zero net initial capital.</li></ol><p class=\"answer\">Kết quả: Profit=0.505.</p><small>Nhóm kiến thức: interest-arb</small></div>"},{"question_en":"E06 · FX forward periodic theo quote USD/EUR","steps_vi":[],"answer":"","html":"<div class=\"top\">E06 · FX forward periodic theo quote USD/EUR</div><div class=\"body\"><p><b>Đề:</b> S=1,25 USD/EUR, 1y USD rf=5%, EUR rf=2%.</p><ol><li>F=S×(1+USD rate)/(1+EUR rate).</li><li>F=1,25×1,05/1,02.</li></ol><p class=\"answer\">Kết quả: F≈1.286765 USD/EUR.</p><small>Nhóm kiến thức: fx</small></div>"},{"question_en":"E07 · FX forward với continuous rates","steps_vi":[],"answer":"","html":"<div class=\"top\">E07 · FX forward với continuous rates</div><div class=\"body\"><p><b>Đề:</b> Spot=1,25 USD/EUR, continuous rUSD=4%, rEUR=1,5%, horizon=0,75 năm.</p><ol><li>F=S×exp[(0,04−0,015)×0,75].</li><li>Dùng continuous-rate convention, không tự thay 1+yield.</li></ol><p class=\"answer\">Kết quả: F≈1.273659 USD/EUR.</p><small>Nhóm kiến thức: fx</small></div>"},{"question_en":"E08 · Covered FX arbitrage sai forward quote","steps_vi":[],"answer":"","html":"<div class=\"top\">E08 · Covered FX arbitrage sai forward quote</div><div class=\"body\"><p><b>Đề:</b> S=1,25 USD/EUR, rUSD=5%, rEUR=2%; market forward 1,30 USD/EUR, vay 125 USD.</p><ol><li>Vay USD125 → đổi spot thành EUR100.</li><li>Lend EUR100 at 2% → EUR102, bán EUR forward 1,30 → USD132,60.</li><li>Repay USD125×1,05=131,25.</li></ol><p class=\"answer\">Kết quả: Profit=USD1.35.</p><small>Nhóm kiến thức: fx-arb</small></div>"},{"question_en":"E09 · Call option payoff states","steps_vi":[],"answer":"","html":"<div class=\"top\">E09 · Call option payoff states</div><div class=\"body\"><p><b>Đề:</b> Stock S0=70, up Su=91, down Sd=56, call strike=75.</p><ol><li>Call up=max(91−75,0)=16.</li><li>Call down=max(56−75,0)=0.</li></ol><p class=\"answer\">Kết quả: Cu=16, Cd=0.</p><small>Nhóm kiến thức: call</small></div>"},{"question_en":"E10 · Call replicated price with hedge ratio","steps_vi":[],"answer":"","html":"<div class=\"top\">E10 · Call replicated price with hedge ratio</div><div class=\"body\"><p><b>Đề:</b> S0=70, Su=91, Sd=56, X=75, one-period rf=5%, không dividend.</p><ol><li>h=(Cu−Cd)/(Su−Sd)=16/(91−56).</li><li>V1u=h×91−16=V1d=h×56−0.</li><li>C0=h×70−V1/1,05.</li></ol><p class=\"answer\">Kết quả: h≈0.457143; riskless payoff≈25.6000; call≈7.6190.</p><small>Nhóm kiến thức: call</small></div>"},{"question_en":"E11 · Put option payoff states","steps_vi":[],"answer":"","html":"<div class=\"top\">E11 · Put option payoff states</div><div class=\"body\"><p><b>Đề:</b> Same underlying, put strike=75.</p><ol><li>Put up=max(75−91,0)=0.</li><li>Put down=max(75−56,0)=19.</li></ol><p class=\"answer\">Kết quả: Pu=0; Pd=19.</p><small>Nhóm kiến thức: put</small></div>"},{"question_en":"E12 · Put replicated price with stock+put","steps_vi":[],"answer":"","html":"<div class=\"top\">E12 · Put replicated price with stock+put</div><div class=\"body\"><p><b>Đề:</b> S0=70, Su=91, Sd=56, strike=75, rf=5%.</p><ol><li>h=(Pd−Pu)/(Su−Sd)=19/(91−56).</li><li>V1u=h×91+0=V1d=h×56+19.</li><li>P0=V1/1,05−h×70.</li></ol><p class=\"answer\">Kết quả: h≈0.542857; payoff≈49.4000; put≈9.0476.</p><small>Nhóm kiến thức: put</small></div>"},{"question_en":"E13 · Put-call consistency no dividend","steps_vi":[],"answer":"","html":"<div class=\"top\">E13 · Put-call consistency no dividend</div><div class=\"body\"><p><b>Đề:</b> Với dữ liệu call và put ở trên, kiểm tra C0−P0 và S0−X/(1+rf).</p><ol><li>C0−P0 dùng hai giá replication.</li><li>S0−75/1,05 theo cashflow additivity trong one-period no dividend.</li></ol><p class=\"answer\">Kết quả: C0−P0≈-1.428571; S0−X/1,05≈-1.428571.</p><small>Nhóm kiến thức: sanity</small></div>"},{"question_en":"E14 · Changing risk-free rate affects parity FX","steps_vi":[],"answer":"","html":"<div class=\"top\">E14 · Changing risk-free rate affects parity FX</div><div class=\"body\"><p><b>Đề:</b> S=1,25 USD/EUR, rEUR=2%; nếu rUSD tăng từ 5% lên 6%, all else equal.</p><ol><li>F trước=1,25×1,05/1,02.</li><li>F sau=1,25×1,06/1,02.</li><li>Forward USD/EUR tăng do price-currency rf USD tăng.</li></ol><p class=\"answer\">Kết quả: Forward tăng từ 1.286765 lên 1.299020 USD/EUR.</p><small>Nhóm kiến thức: fx</small></div>"},{"question_en":"E15 · No-arbitrage discounting identical future payoffs","steps_vi":[],"answer":"","html":"<div class=\"top\">E15 · No-arbitrage discounting identical future payoffs</div><div class=\"body\"><p><b>Đề:</b> Hai hợp đồng bảo đảm cùng CF=500 ở cuối năm 2, risk-free rate=4%/năm. Một niêm yết giá 450, một niêm yết 470.</p><ol><li>Fair PV of both is 500/1,04²≈462,28.</li><li>Trong mô hình frictionless, mua rẻ 450 và short hợp đồng 470 có identical terminal CF, profit upfront 20.</li><li>Giá sẽ bị kéo về cùng mức trong không-arbitrage equilibrium.</li></ol><p class=\"answer\">Kết quả: Fair PV≈462.2781; chênh giá=20.</p><small>Nhóm kiến thức: arbitrage</small></div>"}],"questions":[{"stem_en":"When does cash-flow additivity provide a valid present-value approach?","options":["Cash flows are aligned by date and risk and discounted consistently","Every cash flow has the same amount","Only annuities are allowed"],"correct":0,"why_vi":"PV tuyến tính theo các dòng tiền hợp lệ khi căn thời điểm và discount đúng cơ sở.","trap_vi":""},{"stem_en":"At a 10% annual discount rate, what is the present value of USD 100 at each year-end from Year 1 through Year 4 plus an additional USD 250 at the end of Year 3?","options":["USD 504.82","USD 350.00","USD 250.00"],"correct":0,"why_vi":"Lấy annuity PV 4y cộng PV 250/1,10^3, không cộng undiscounted.","trap_vi":""},{"stem_en":"Two portfolios have identical payoffs at every date in every state but trade for different prices. In a frictionless market, this indicates:","options":["An arbitrage opportunity","No arbitrage opportunity is possible","Their required returns must necessarily be identical"],"correct":0,"why_vi":"Law of one price yêu cầu giá bằng nhau với identical future payoffs in all states.","trap_vi":""},{"stem_en":"Two portfolios have equal expected cash flows but different state-dependent payoffs. Must their prices be identical?","options":["Yes, because expected cash flows are equal","No, because their payoff risks can differ","Yes, if maturity matches"],"correct":1,"why_vi":"No-arbitrage valuation yêu cầu equivalence theo từng state/time, không chỉ expected value.","trap_vi":""},{"stem_en":"Annual spot rates are 3% for one year and 4% for two years. The exact one-year forward rate beginning in one year is closest to:","options":["5.010%","4.000%","5.000%, rounded to one decimal place but less precise"],"correct":0,"why_vi":"F1,1=(1,04)^2/1,03−1, dùng gross factor không dùng arithmetic shortcut.","trap_vi":""},{"stem_en":"What does the notation F1,1 represent?","options":["A one-year rate starting one year from today","A one-year rate starting two years from today","A two-year rate starting one year from today"],"correct":0,"why_vi":"Ký hiệu forward 1y1y = 1-year loan starting in 1 year.","trap_vi":""},{"stem_en":"Under no-arbitrage, which relationship links one- and two-year annual spot rates to the one-year forward rate starting in Year 1?","options":["(1+s2)^2=(1+s1)(1+F1,1)","s2=s1+F1,1","s1=s2"],"correct":0,"why_vi":"Hai chiến lược đến cùng t=2 phải sinh gross accumulation factor bằng nhau.","trap_vi":""},{"stem_en":"The one-year spot rate is 3%, the two-year spot rate is 4%, and the quoted F1,1 is 5.5%, above the no-arbitrage rate. Ignoring costs, which strategy exploits the discrepancy?","options":["Borrow for two years at 4%; invest for one year at 3% and reinvest the proceeds at the 5.5% forward rate","Borrow for one year at 3%; invest for two years at 4%, leaving the refinancing rate unhedged","No arbitrage is possible"],"correct":0,"why_vi":"Thu về 100×1,03×1,055 hơn trả vay 100×1,04² => 0,505.","trap_vi":""},{"stem_en":"Is F1,1 a guaranteed forecast of the short-term rate that will prevail next year?","options":["Yes","No; it is a current break-even forward rate fixed by market pricing","Yes; it must equal the current one-year spot rate"],"correct":1,"why_vi":"Forward là rate no-arbitrage embedded in yield curve, không bảo đảm realized future spot.","trap_vi":""},{"stem_en":"For a foreign exchange quote expressed as USD per EUR, which currency's interest rate appears in the numerator of the covered-interest-parity gross-rate ratio?","options":["EUR interest rate","USD interest rate","Euro-area inflation rate"],"correct":1,"why_vi":"F USD/EUR = S×(1+rUSD)/(1+rEUR), price-currency rate USD nằm numerator.","trap_vi":""},{"stem_en":"The spot quote is 1.25 USD/EUR; annual USD and EUR interest rates are 5% and 2%. The one-year forward USD/EUR quote under covered parity is closest to:","options":["1.2868","1.2500","1.2100"],"correct":0,"why_vi":"Covered interest parity: 1,25×1,05/1,02≈1,28676 USD/EUR.","trap_vi":""},{"stem_en":"With continuously compounded interest rates, which formula is consistent with covered interest parity for a quote in price currency per unit of base currency?","options":["F=S exp[(r_price−r_base)T]","F=S(1+r_price)/(1+r_base) regardless of compounding convention","F=S/(r_price−r_base)"],"correct":0,"why_vi":"Với lãi ghép liên tục, các investment factors là exponential e^(rT).","trap_vi":""},{"stem_en":"If a USD/EUR quote increases from 1.25 to 1.29, which statement is correct?","options":["More USD are required to buy one EUR","Fewer USD are required to buy one EUR","EUR/USD necessarily increases in the same direction"],"correct":0,"why_vi":"Giá price currency USD per base currency EUR cao hơn.","trap_vi":""},{"stem_en":"A quoted USD/EUR forward of 1.30 exceeds its covered-parity value of 1.28676. Which strategy represents a covered arbitrage, ignoring costs?","options":["Borrow USD, purchase and invest EUR, and sell EUR forward","Borrow EUR, purchase and invest USD, and buy EUR forward","No forward contract can lock in the proceeds"],"correct":0,"why_vi":"Vay USD125 trả131,25; 100EUR gửi2% được102EUR bán1,30 thu132,60, profit1,35.","trap_vi":""},{"stem_en":"Does a covered-interest-parity forward exchange rate necessarily equal the future spot exchange rate?","options":["Yes","No","Only when USD interest rates exceed EUR rates"],"correct":1,"why_vi":"No-arbitrage covered forward khác expected future spot.","trap_vi":""},{"stem_en":"For a one-period binomial model with stock prices Su=91 and Sd=56 and a call strike of 75, the call payoffs are:","options":["Cu=16 and Cd=0","Cu=0 and Cd=19","Cu=16 and Cd=19"],"correct":0,"why_vi":"Call=max(S−X,0). 91−75=16; stock 56 nên OTM payoff0.","trap_vi":""},{"stem_en":"For the same stock outcomes Su=91 and Sd=56 with put strike X=75, the put payoffs are:","options":["Pu=16 and Pd=0","Pu=0 and Pd=19","Pu=0 and Pd=0"],"correct":1,"why_vi":"Put=max(X−S,0): up state 0, down state 75−56=19.","trap_vi":""},{"stem_en":"In the one-period call replication model, given Cu=16, Cd=0, Su=91 and Sd=56, the hedge ratio h is closest to:","options":["0.4571","1.0000","0.8000"],"correct":0,"why_vi":"h=(Cu−Cd)/(Su−Sd)=16/35≈0,4571 units underlying per short call.","trap_vi":""},{"stem_en":"Which portfolio becomes riskless by replicating a one-period call payoff difference using h shares?","options":["Long h shares and short one call","Long one share and long one call","Short one share and long one put"],"correct":0,"why_vi":"Payoff hSu−Cu=hSd−Cd; danh mục bảo đảm cùng terminal value.","trap_vi":""},{"stem_en":"Under a one-period model with S0=70, Su=91, Sd=56, strike X=75, and risk-free rate 5%, the call price C0 is closest to:","options":["7.6190","16.0000","0"],"correct":0,"why_vi":"C0=hS0−V1/(1+rf), h=16/35; V1=25,6.","trap_vi":""},{"stem_en":"In the one-period put replication setup, which position can form a riskless combination when h is chosen appropriately?","options":["Long h shares plus one put","Long h shares minus one put","Short one call only"],"correct":0,"why_vi":"V1u=hSu+Pu=V1d=hSd+Pd; h=(Pd−Pu)/(Su−Sd).","trap_vi":""},{"stem_en":"Under the same one-period assumptions S0=70, Su=91, Sd=56, X=75, and rf=5%, the put price P0 is closest to:","options":["9.0476","19.0000","0"],"correct":0,"why_vi":"Put P0=[hSu+Pu]/1,05−hS0, h=19/35; khoảng9,0476.","trap_vi":""},{"stem_en":"For a one-period binomial model with up factor 1.30, down factor 0.80, and risk-free rate 5%, which no-arbitrage condition holds?","options":["0.80 < 1.05 < 1.30","1.05 < 0.80","1.30 < 1.05"],"correct":0,"why_vi":"Riskfree factor 1+rf cần nằm giữa down factor d và up factor u.","trap_vi":""},{"stem_en":"With no dividends and a single maturity T=1 period, European put-call parity is:","options":["C0−P0 = S0−X/(1+rf)","C0−P0 = S0+X","C0−P0 = Cu−Pd"],"correct":0,"why_vi":"Theo replication parity one-period: C0−P0=S0−PV(strike).","trap_vi":""},{"stem_en":"In a one-period replication model, the hedge ratio represents:","options":["The number of underlying units needed to offset one option's payoff sensitivity across states","The actual probability that a stock price rises","Years to option expiration"],"correct":0,"why_vi":"Hedge ratio h từ chênh payoff option/chênh giá underlying, không phải probability.","trap_vi":""},{"stem_en":"Which precaution is most important for a one-period option valuation?","options":["Use a risk-free rate for the correct period and keep long/short cash-flow signs consistent","Substitute dividends for strike price","Multiply expected payoff by inflation"],"correct":0,"why_vi":"Risk-free rate và payoff phải cùng kỳ; short call và long put có dấu khác nhau.","trap_vi":""},{"stem_en":"Two adjacent slide pages give inconsistent final-year values in a cash-flow-additivity illustration. What should an analyst do?","options":["Reconstruct the timeline and verify the calculation against the primary curriculum","Choose either number arbitrarily","Discard the additivity principle"],"correct":0,"why_vi":"Curriculum p78 và SAPP p88 dùng 32,35; SAPP p87 ghi 32,25, phải xác minh.","trap_vi":""},{"stem_en":"Two-year and three-year annual spot rates are 3.0% and 3.5%. The implied one-year forward rate starting two years from today is closest to:","options":["4.507%","3.0%","3.5%"],"correct":0,"why_vi":"(1+s3)^3=(1+s2)^2(1+F2,1), lấy tỷ số gross factors.","trap_vi":""}],"cards":[{"front_en":"Cash flow additivity?","back_vi":"PV(A+B)=PV(A)+PV(B) khi aligned dates, same appropriate discounting."},{"front_en":"No-arbitrage law of one price?","back_vi":"Same payoff in all states and dates ⇒ same today price (frictionless)."},{"front_en":"F1,1 từ spot s1,s2?","back_vi":"(1+s2)^2/(1+s1)−1."},{"front_en":"Forward F1,1 là dự báo chắc chắn?","back_vi":"Không; breakeven locked interest rate today."},{"front_en":"F2,1 từ s2,s3?","back_vi":"(1+s3)^3/(1+s2)^2−1."},{"front_en":"FX quote price/base: F periodic?","back_vi":"F=S(1+rprice)/(1+rbase), cùng kỳ."},{"front_en":"FX continuous forward?","back_vi":"F=S exp[(rprice−rbase)T]."},{"front_en":"FX forward là future spot?","back_vi":"Không; covered parity không bảo đảm future spot."},{"front_en":"Call expiration payoff?","back_vi":"max(S−X,0)."},{"front_en":"Call hedge ratio?","back_vi":"h=(Cu−Cd)/(Su−Sd) với long h underlying và short call."},{"front_en":"Call option C0 từ replicated portfolio?","back_vi":"C0=hS0−(hSu−Cu)/(1+rf)."},{"front_en":"Put expiration payoff?","back_vi":"max(X−S,0)."},{"front_en":"Put riskless portfolio?","back_vi":"Long h shares + long put; h=(Pd−Pu)/(Su−Sd)."},{"front_en":"Put P0 from replication?","back_vi":"P0=(hSu+Pu)/(1+rf)−hS0."},{"front_en":"Binomial no-arbitrage condition?","back_vi":"d<1+rf<u với consistent rate per period."},{"front_en":"SAPP p87 vs p88 discrepancy?","back_vi":"CFAI p78 & SAPP p88 use 32.35; slide p87 has 32.25, verify rather than copy."}],"source":[{"id":"Nguồn đối chiếu từ học liệu gốc","pages":"Nguồn đã đối chiếu CFAI 2026 — Curriculum Quantitative Methods, Module 2, PDF trang 77–88: cash-flow additivity, spot/forward interest, covered FX parity, one-period call/put replication. Kaplan 2026 — SchweserNotes Book 1, PDF trang 37–42, cash flow additivity and no-arbitrage, forward rates, FX and binomial hedge ratio. SAPP 2026 — Quant notes PDF trang 84–102, prerequisite timeline, LOS 2.c forward interest, exchange and option replication. PDF trang 87 ghi cash flow 32.25 nhưng trang 88/ Curriculum trang 78 có 32.35; dùng nội dung nhất quán theo Curriculum. Prerequisite / Mindmap — Prerequisite Quant 2024: timelines, uneven CF, annuity/additivity; Mindmap Quant: TVM cash-flow additivity structure. QBank / Mocks — Các bộ đề theo chủ đề dùng kiểm tra phạm vi kỹ năng; câu hỏi hiển thị mới tự biên soạn, không đăng nguyên văn đề nguồn. Đã đối chiếu trong phạm vi các trang chuyên môn ghi trên, không tuyên bố kiểm kê hết mọi câu hỏi của 534 PDF hoặc được CFA Institute chứng thực. Sự khác biệt giữa các nguồn phải được ghi thành hồ sơ riêng."}],"legacy":"sourcefirst-quant-tvm-los03.html"}],"disclaimer_vi":"Giữ nguyên học liệu gốc; xem nguồn đối chiếu trong từng bài."}];
